window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0146", [{"word":"façade","ipa_uk":"/fəˈsɑːd/","ipa_us":"/fəˈsɑːd/","definition_zh":"建筑正面；主立面；假象；掩饰真面目的外表","definition_en":"the front of a building, or a false appearance that hides what is really there","core_image":"舞台布景般的一面墙：正面光鲜整齐，墙后是裸露的砖、管线和杂物","scene":"老剧场翻修时，工人只保留临街的那面墙，墙后全部重建。The architect kept only the original façade and rebuilt everything behind it.","sceneCN":"这里指「建筑临街的正面外壳」（第 1 个义项：建筑物朝向公众的那一面）；句意为建筑师只保留原来的临街立面，墙后全部重建。可辨识物件：旧墙、脚手架、裸露的砖、新钢梁。","pos":[{"tag":"n.","zh":"建筑正面；立面；主立面"},{"tag":"n.","zh":"（比喻）假象；掩饰真面目的外表"}],"collocations":[{"phrase":"the façade of the building","zh":"建筑的正面"},{"phrase":"a stone façade","zh":"石砌立面"},{"phrase":"a façade of calm","zh":"表面上的镇定"},{"phrase":"behind the façade","zh":"在表象背后"},{"phrase":"maintain a façade","zh":"维持表面的体面"},{"phrase":"a neoclassical façade","zh":"新古典风格的立面"}],"forms":[{"label":"单数形式","form":"façade"},{"label":"复数形式","form":"façades"},{"label":"所有格","form":"façade's"},{"label":"常见异体拼写","form":"facade"},{"label":"复数所有格","form":"façades’"}],"derivatives":[{"word":"facadism","pos":"n.","zh":"立面主义：只保住建筑正面外墙、其后全部翻新的做法（由基础词加表示「以某物为宗旨」的后缀构成，语义收窄为一种做法）"},{"word":"facadectomy","pos":"n.","zh":"保留立面式改建：留下旧立面、其后掏空重建（由基础词加借自外科「切除」义的后缀构成，语义偏移为「只留外壳」）"},{"word":"facade-like","pos":"adj.","zh":"像建筑正面的；只有表面一层的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"},{"word":"facade easement","pos":"n.","zh":"立面地役权：以合约长期保护历史建筑外墙的法律工具（由基础词与表示「地役权」的词复合，语义偏移为保护性权利）"}],"senses":[{"no":"01","title":"Front face of a building","titleCN":"建筑正面：朝向街道的那一面","definition":"the front wall of a building, especially the side that faces a street or public space","definitionCN":"建筑物的正面外墙，尤指朝向街道或公共空间的一面","example":"The shop's façade was repainted in deep green.","exampleCN":"这家店铺的正面外墙被重新漆成深绿色。","why":"The word came into English from French for 'face'. A building's public face is literally the side it turns toward the street.","whyCN":"这个词从法语进入英语，本义就是「脸」。建筑面向街道的那一侧，正像它的一张脸。"},{"no":"02","title":"Principal designed elevation","titleCN":"主立面：经过专门设计的那一面","definition":"the main side of a building when that side is treated as a designed architectural surface","definitionCN":"把某一面墙当作经过设计的建筑表面来处理时，指主立面","example":"The museum's façade is a grid of pale stone and glass.","exampleCN":"博物馆的主立面是一片浅色石材与玻璃构成的网格。","why":"Architects use the word for the elevation that carries the design, not merely for any outer wall. The face becomes a composition.","whyCN":"建筑师用这个词指承载设计意图的那个立面，而不只是任意一堵外墙。脸因此变成一幅构图。"},{"no":"03","title":"False appearance","titleCN":"假象：做给外人看的外表","definition":"a false or artificial appearance that hides the true state of something","definitionCN":"掩盖真实情况的虚假或人为外表","example":"The company maintained a façade of prosperity while its debts grew.","exampleCN":"公司维持着繁荣的假象，债务却在不断增加。","why":"If the front of a building can hide what is behind it, then any polished outward show can hide a messy reality. The architectural image becomes a metaphor for deception.","whyCN":"既然建筑的正面能遮住墙后的东西，任何光鲜的对外展示也就能遮住混乱的真实。建筑意象由此变成欺骗的隐喻。"},{"no":"04","title":"Outward composure of a person","titleCN":"人的表面镇定","definition":"the outward manner a person presents to others, often hiding inner distress","definitionCN":"一个人呈现给别人的外在举止，常掩盖内心的痛苦","example":"She kept up a cheerful façade long after the loss.","exampleCN":"失去之后很久，她仍维持着快活的外表。","why":"A person also has a public front. The word names the face worn in company, especially when the private self does not match it.","whyCN":"人也有对外的正面。这个词指在众人面前戴着的那张脸，尤其当私下的自己与它并不一致时。"},{"no":"05","title":"Front for an illegal activity","titleCN":"掩护门面：为非法活动打掩护的场所","definition":"an organization or business that exists mainly to conceal another, usually illegal, activity","definitionCN":"主要为掩盖另一项（通常非法的）活动而存在的机构或生意","example":"The restaurant was a façade for a smuggling operation.","exampleCN":"这家餐馆是一个走私活动的掩护门面。","why":"The sense extends the building image: a respectable front room is shown to the public while the real business happens out of sight.","whyCN":"这一义项延伸了建筑意象：给公众看的是体面的门面，真正的生意却在看不见的地方进行。"},{"no":"06","title":"Visible face of an institution","titleCN":"机构的对外形象","definition":"the public image an institution presents, as distinct from its internal workings","definitionCN":"机构对外呈现的公众形象，与内部运作相区别","example":"The committee is the public façade of a much larger network.","exampleCN":"这个委员会是一个庞大网络的对外门面。","why":"Institutions, like buildings, are judged by what meets the eye. The word separates that visible front from the structure behind it.","whyCN":"机构像建筑一样，先由看得见的部分被评判。这个词把这道可见的正面与其后的结构区分开。"},{"no":"07","title":"Simplified interface of a software system","titleCN":"软件系统的简化接口","definition":"in software design, a single simplified interface that hides a set of more complex subsystems","definitionCN":"软件设计中，用一个简化的统一接口遮住背后的一组复杂子系统","example":"The library offers a small façade over dozens of internal services.","exampleCN":"这个程序库在数十个内部服务之上提供了一个小型门面接口。","why":"Programmers borrowed the architectural word because their pattern does the same job: one clean front hides many moving parts.","whyCN":"程序员借用这个建筑词，因为这种设计模式做的是同一件事：一张干净的门面遮住许多运转的部件。"},{"no":"08","title":"Polished surface hiding disorder","titleCN":"抽象义：光洁表面掩盖内在混乱","definition":"any smooth, orderly surface that conceals confusion, conflict or decay underneath","definitionCN":"任何光滑有序、掩盖其下混乱、冲突或衰败的表面","example":"The report presented a façade of order over a department in crisis.","exampleCN":"报告给一个陷入危机的部门套上了秩序的外表。","why":"The general sense gathers the building, the person and the institution: whatever is shown is intact, whatever is hidden is not.","whyCN":"这个一般义把建筑、个人与机构三条线收在一起：展示出来的部分完好，藏起来的部分则不然。"},{"no":"09","title":"Preserved front of a historic building","titleCN":"历史建筑被保留的正面","definition":"the original front wall of a historic building, kept standing while the rest is altered or rebuilt","definitionCN":"历史建筑原有的正面外墙，在其余部分被改造或重建时仍保留下来","example":"Preservation rules protected the façade but allowed a new tower behind.","exampleCN":"保护规定保住了这面旧立面，却允许在其后建一座新塔楼。","why":"This sense joins the physical front to the idea of display: the wall is kept because it is the part the city remembers.","whyCN":"这一义项把实体正面与「展示」的观念接上：墙之所以被保留，是因为它是城市记得的那一部分。"}],"etymology":{"intro":{"en":"Façade came into English from French in the seventeenth century. French took the word from Italian, and Italian built it on the Latin word for 'face'. Dates are approximate.","cn":"façade 于十七世纪从法语进入英语。法语这个词借自意大利语，意大利语则用拉丁语中表示「脸」的词构成。年代均为约数。"},"items":[{"era":"LATIN FACIES","en":"Latin facies meant 'form, shape, appearance, face'. Its deeper origin is source uncertain; a link to facere 'to make' is generally believed by some references but not demonstrated.","cn":"拉丁语 facies 意为「形状、外观、脸」。其更深来源属「来源不确定」；有资料认为它与 facere「制作」有关，但这只是「一般认为是」，并未得到证明。"},{"era":"ITALIAN FACCIATA","en":"Italian built facciata 'front of a building' from faccia 'face'. The suffix marked a collective surface rather than a single face.","cn":"意大利语用 faccia「脸」构成 facciata「建筑正面」。后缀使这个词指一整片表面，而不是一张具体的脸。"},{"era":"FRENCH FAÇADE (C. 1600)","en":"French reshaped the Italian word into façade, and English borrowed it in the seventeenth century for the front of a large building.","cn":"法语把意大利语词改造成 façade，英语在十七世纪借来，指大型建筑的正面。"},{"era":"ARCHITECTURAL TERM","en":"For two centuries the word stayed technical: the principal elevation of a palace, church or public building.","cn":"此后两个世纪，这个词一直偏技术：宫殿、教堂或公共建筑的主立面。"},{"era":"FIGURATIVE SHIFT","en":"By the nineteenth century the metaphor of a front that hides what lies behind produced the sense of a false or superficial appearance.","cn":"到十九世纪，正面遮住其后之物的比喻催生了「虚假、表面的外观」这一义项。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origin of facies is unsettled, and any older Indo-European form offered for it is a reconstructed form rather than a recorded word.","cn":"来源不确定：facies 在拉丁语之前的来源没有定论，凡为其给出的更早印欧语形式都属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms that look or sound close but come from different roots; group two holds words for the same visible front.","cn":"第一组是形近或音近、但词根不同的词；第二组是同样表示「看得见的正面」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"face","ipa":"/feɪs/","tag":"doublet, not a derivative","definition":"the front of the head; also an outer surface. It descends from Latin facies through Old French, so it is a doublet of façade rather than a word built from it.","definitionCN":"头部正面；也指外表面。它经古法语来自拉丁 facies，与 façade 是同源异形词，而不是由 façade 派生出来的词。"},{"word":"facet","ipa":"/ˈfæsɪt/","tag":"diminutive relative","definition":"one flat cut surface of a gem or an aspect of a subject. It comes from French facette, a diminutive of face, so it belongs to the same family.","definitionCN":"宝石的一个平面；也指问题的一个方面。它来自法语 facette，是 face 的指小形式，属于同一词族。"},{"word":"fascia","ipa":"/ˈfæʃiə/","tag":"not related","definition":"a band of tissue, or a flat board covering a beam. It comes from Latin fascia 'band', a different root, although the spelling is close.","definitionCN":"筋膜；覆盖梁的平板。它来自拉丁 fascia「带子」，词根不同，只是拼写相近。"},{"word":"facade","ipa":"/fəˈsɑːd/","tag":"spelling variant","definition":"the same English word written without the cedilla; it is a spelling variant, not a separate lexical item.","definitionCN":"同一个英语词去掉变音符的写法；它只是拼写变体，不是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"front","ipa":"/frʌnt/","tag":"everyday word","definition":"the most general word for the side that faces forward; it carries no artistic or deceptive overtone.","definitionCN":"最普通的说法，泛指朝前的一面；不含艺术设计或欺骗的意味。"},{"word":"exterior","ipa":"/ɪkˈstɪəriə/","tag":"outside surface","definition":"the outside of a building or object as a whole, not specifically the designed public face.","definitionCN":"建筑或物体整体的外部，不特指经过设计的对外正面。"},{"word":"veneer","ipa":"/ˈviːnɪə/","tag":"thin covering","definition":"a thin layer of fine material glued over a cheaper surface; figuratively, a polished cover over something poor.","definitionCN":"贴在廉价表面上的薄层好材料；比喻义指覆盖在劣质事物上的光鲜表层。"},{"word":"mask","ipa":"/mɑːsk/","tag":"concealment","definition":"something worn or put on to hide a face or a feeling; it stresses deliberate concealment more than façade does.","definitionCN":"戴在脸上或用来掩盖情绪之物；比 façade 更强调刻意的遮掩。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The word is the same 'face' idea as in facial: a building's face turned toward the street.","cn":"这个词与 facial 中的「脸」是同一个观念：建筑朝向街道的那张脸。"},{"en":"The fixed phrase behind the façade marks the shift from stone to secrecy.","cn":"固定搭配「在表象背后」标出了从石头到隐秘的语义转移。"},{"en":"Facadism names the practice of keeping only that face while the body is replaced.","cn":"「立面主义」指只留下这张脸、把身体整个换掉的做法。"},{"en":"Architects speak of the principal elevation when they mean the designed front.","cn":"建筑师说「主立面」时，指的正是经过设计的正面。"},{"en":"Software calls a simplified interface a façade because it, too, is one clean front over many parts.","cn":"软件把简化接口叫作门面，因为它同样是一张干净正面遮住许多部件。"}],"abstract":[{"en":"Picture a stage set: painted walls in front, bare scaffolding behind.","cn":"想象一套舞台布景：前面是画好的墙，后面是裸露的脚手架。"},{"en":"Picture a person holding a smile steady while the hands tremble.","cn":"想象一个人稳稳挂着微笑，双手却在发抖。"},{"en":"Picture a tidy shop window with an empty room behind the glass.","cn":"想象一扇整洁的橱窗，玻璃后面却是一间空屋。"}]},"examples":[{"en":"The old bank kept its stone façade but rebuilt the interior as flats.","cn":"那家老银行保留了石砌立面，却把内部改建成公寓。"},{"en":"Behind a façade of calm, the negotiators were close to walking out.","cn":"在镇定的表象背后，谈判者们几乎要退场了。"},{"en":"The charity was accused of acting as a façade for a political group.","cn":"该慈善机构被指为一个政治团体充当掩护门面。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「发萨德」—— 发出一张萨德式的门面，门后却空着 → 建筑正面、假象","word":"façade"},"root":"法语 façade 借自意大利语 facciata，源头是拉丁 facies「形状、外观、脸」；与英语 face 同源而非派生。facies 在拉丁语之前的来源不确定，更早的印欧语形式均属重构。","sensesIntro":{"en":"Nine senses follow one object: a building turns a single face toward the public. That face becomes a designed composition, then a false front for a person, a business or an institution, and finally a clean surface laid over any disorder.","cn":"九个义项围绕同一个对象展开：建筑把一张脸转向公众。这张脸先是设计过的构图，再成为个人、生意或机构的虚假正面，最后成为铺在任何混乱之上的一层光洁表面。"},"semanticMap":{"core":{"en":"CORE IMAGE: one polished wall faces the street while everything unfinished stays behind it.","cn":"核心意象：一堵光洁的墙朝向街道，所有未完成的东西都留在墙后。"},"chain":["PUBLIC FACE","DESIGNED SURFACE","FALSE FRONT","INSTITUTIONAL IMAGE","HIDDEN STRUCTURE","SMOOTH INTERFACE"],"branches":[{"senses":"01","en":"THE FACE ITSELF: the word begins as the side a building turns toward the street.","cn":"脸本身：这个词最初只指建筑转向街道的那一面。"},{"senses":"02 · 09","en":"FACE AS ART AND MEMORY: the designed elevation and the preserved front are the same wall seen as art and as heritage.","cn":"脸作为艺术与记忆：精心设计的立面与被保留的旧立面，是同一堵墙在艺术与遗产两个角度下的样子。"},{"senses":"03 · 04","en":"FALSE FACE: a person or a company can wear a front the way a building does.","cn":"假脸：个人或公司可以像建筑一样戴上一张正面。"},{"senses":"05 · 06","en":"ORGANIZED COVER: a business or committee becomes the respectable front of something hidden.","cn":"有组织的掩护：一门生意或一个委员会成为隐藏之物的体面正面。"},{"senses":"07 · 08","en":"CLEAN SURFACE OVER COMPLEXITY: software and abstract order both use one smooth face to hide many parts.","cn":"复杂度上的光洁表面：软件与抽象的秩序都用一个光滑正面遮住许多部件。"}]},"affixes":{"intro":{"en":"Façade belongs to a Latin family built on facies 'form, face'. The same stock also gives the everyday word for a face, the word for a cut surface, and several verbs about removing or covering a surface.","cn":"façade 属于以拉丁 facies「形状、脸」为核心的一族词。同一词干还给出表示「脸」的日常词、表示「切面」的词，以及若干表示「去掉表面」或「覆盖表面」的动词。"},"latinIntro":{"en":"Latin facies and its relatives passed through French into English; the family includes face, facet, facial, surface and deface.","cn":"拉丁 facies 及其同族词经法语进入英语；这一族包括表示脸、切面、面部的词，以及表示表面与毁容的词。"},"items":[{"word":"fac-","structure":"fac- (bound root from Latin facies)","meaning":"form, shape, face","meaningCN":"形状；外观；脸","example":"The root carries the idea of a visible form.","exampleCN":"这个词根带着「可见形状」的意思。"},{"word":"facies","structure":"facies (Latin noun, fifth declension)","meaning":"form, appearance, face","meaningCN":"形状；外观；脸","example":"The Latin noun is the source of the whole family.","exampleCN":"这个拉丁名词是整个词族的源头。"},{"word":"façade","structure":"Italian facciata, from faccia 'face'","meaning":"the front of a building","meaningCN":"建筑正面","example":"The theatre's façade faces the square.","exampleCN":"剧院的正面朝向广场。"},{"word":"face","structure":"Latin facies through Old French","meaning":"the front of the head; an outer surface","meaningCN":"头部正面；外表面","example":"Her face gave nothing away.","exampleCN":"她的脸没有透露任何东西。"},{"word":"facet","structure":"French facette, diminutive of face","meaning":"a cut surface of a gem; an aspect","meaningCN":"宝石的切面；方面","example":"Each facet of the diamond caught the light.","exampleCN":"钻石的每个切面都反着光。"},{"word":"facial","structure":"facies + -alis (relating to)","meaning":"relating to the face","meaningCN":"面部的","example":"The spa offers facial treatments.","exampleCN":"这家水疗馆提供面部护理。"},{"word":"surface","structure":"sur- 'above' + face","meaning":"the outer layer of something","meaningCN":"表面；外层","example":"The surface of the lake was still.","exampleCN":"湖面静止不动。"},{"word":"deface","structure":"de- 'away, down' + face","meaning":"to spoil the surface of something","meaningCN":"损坏……的表面；毁容","example":"Someone defaced the poster.","exampleCN":"有人涂毁了那张海报。"},{"word":"facadism","structure":"façade + -ism (practice)","meaning":"preserving only the front wall of a building","meaningCN":"只保留建筑正面的做法","example":"Facadism saved the outline but not the rooms.","exampleCN":"立面主义保住了轮廓，却没保住房间。"},{"word":"facadectomy","structure":"façade + -ectomy (cutting out)","meaning":"rebuilding everything behind a kept front wall","meaningCN":"保留旧立面、其后全部重建","example":"The facadectomy left a hollow shell for one season.","exampleCN":"这项立面保留工程让建筑空了一季。"},{"word":"facade-like","structure":"façade + -like (resembling)","meaning":"resembling a building front; merely surface","meaningCN":"像建筑正面的；只有表面的","example":"The set was facade-like, flat and thin.","exampleCN":"那套布景像一面假墙，又平又薄。"}],"latinEntries":[{"word":"facies","structure":"facies, faciei (f., fifth declension)","meaning":"form, shape, appearance, face","meaningCN":"形状；外观；脸"},{"word":"facialis","structure":"facialis, faciale (adj., third declension)","meaning":"of the face","meaningCN":"脸的；面部的"},{"word":"superficies","structure":"superficies, superficiei (f., fifth declension)","meaning":"surface, outer face","meaningCN":"表面；外表面"}]}},{"word":"mosaic","ipa_uk":"/məʊˈzeɪɪk/","ipa_us":"/moʊˈzeɪɪk/","definition_zh":"马赛克；镶嵌画；镶嵌工艺；拼合而成的整体","definition_en":"a picture or pattern made by fixing small coloured pieces into a surface","core_image":"碎成百片的彩石被一块块嵌进灰泥，远看合成一幅完整图画","scene":"考古队在教堂地面清理出一幅由几千块小石子拼成的鸟形图案。The team uncovered a mosaic of tiny stones forming a bird on the church floor.","sceneCN":"这里指「用小石片拼成的镶嵌图案」（第 1 个义项：由许多小块材料嵌成的画面）；句意为考古队在教堂地面清理出一幅小石子拼成的鸟形镶嵌画。可辨识物件：小石片、灰泥、鸟形、刷子、标尺。","pos":[{"tag":"n.","zh":"镶嵌画；马赛克；拼合体"},{"tag":"adj.","zh":"镶嵌式的；由许多小块拼成的"}],"collocations":[{"phrase":"a mosaic floor","zh":"镶嵌地面"},{"phrase":"a mosaic pattern","zh":"镶嵌图案"},{"phrase":"a mosaic of cultures","zh":"多种文化拼合的整体"},{"phrase":"glass mosaic","zh":"玻璃马赛克"},{"phrase":"a mosaic tile","zh":"马赛克砖"},{"phrase":"lay a mosaic","zh":"铺设镶嵌画"}],"forms":[{"label":"单数形式","form":"mosaic"},{"label":"复数形式","form":"mosaics"},{"label":"动词三单","form":"mosaics"},{"label":"过去式","form":"mosaicked"},{"label":"过去分词","form":"mosaicked"},{"label":"现在分词","form":"mosaicking"}],"derivatives":[{"word":"mosaicist","pos":"n.","zh":"镶嵌艺术家；马赛克工匠（由基础词加表示「从事者」的后缀构成，语义收窄为职业身份）"},{"word":"mosaicked","pos":"adj.","zh":"用镶嵌法装饰的；镶成马赛克图案的（由基础词加表示「被施以……」的后缀构成，语义偏移为状态）"},{"word":"mosaic-like","pos":"adj.","zh":"类似镶嵌画的；由细碎单元拼成的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"}],"senses":[{"no":"01","title":"Picture made of small pieces","titleCN":"用小片拼成的镶嵌画","definition":"a picture or decorative pattern made by fixing small pieces of stone, glass or tile into a surface","definitionCN":"把小块石头、玻璃或瓷砖嵌进表面而拼成的画面或装饰图案","example":"The team uncovered a mosaic of tiny stones forming a bird.","exampleCN":"考古队清理出一幅由小石子拼成鸟形的镶嵌画。","why":"The word names the work first. A mosaic exists only because many separate pieces are set side by side, so the picture is literally made of parts.","whyCN":"这个词首先指成品。镶嵌画之所以存在，只因为许多分离的小块被并排嵌在一起，所以画面真的由碎片构成。"},{"no":"02","title":"The art of setting tesserae","titleCN":"镶嵌工艺：把小块材料嵌进表面的手艺","definition":"the craft or technique of assembling small pieces into a surface design","definitionCN":"把小块材料拼嵌成表面图案的手艺或技法","example":"She studied mosaic in Ravenna for three summers.","exampleCN":"她连续三个夏天在拉文纳学习镶嵌工艺。","why":"Once the product was familiar, the name moved to the skill that makes it. The art is defined by the setting of separate pieces, not by any one material.","whyCN":"成品为人熟知之后，名称就转指制作它的技艺。这门艺术的关键是把分离的小块嵌起来，而不在于某一种材料。"},{"no":"03","title":"A floor or wall work","titleCN":"镶嵌地面或墙面作品","definition":"a decorated floor, wall or vault executed in this technique","definitionCN":"用这种技法做成的地面、墙面或拱顶装饰","example":"The baptistery ceiling is a gold mosaic of the saints.","exampleCN":"洗礼堂的穹顶是一幅金底圣徒镶嵌画。","why":"Mosaic art lives on architecture. Because the pieces are fixed into mortar, the work belongs to the building rather than to a frame.","whyCN":"镶嵌艺术依附于建筑。因为小块被嵌进灰泥，作品属于建筑本身，而不属于画框。"},{"no":"04","title":"A mixture of distinct elements","titleCN":"由不同成分拼合的整体","definition":"a whole made of many different elements that remain individually visible","definitionCN":"由许多不同成分构成、各成分仍各自可见的整体","example":"The city is a mosaic of languages and cuisines.","exampleCN":"这座城市是语言与饮食的拼合体。","why":"The visual sense becomes social: separate communities lie side by side like stones in a floor, making one picture without melting into one colour.","whyCN":"视觉义转向社会：不同的群体像地面的石子那样并排相邻，合成一幅图，却没有熔成同一种颜色。"},{"no":"05","title":"Mixed cell populations in genetics","titleCN":"遗传学中由不同细胞群构成的个体","definition":"in genetics, an organism or tissue containing cells with more than one genotype","definitionCN":"遗传学中，体内含有一种以上基因型细胞的生物体或组织","example":"The lab detected a mosaic in the patient's skin cells.","exampleCN":"实验室在患者的皮肤细胞中检测到嵌合现象。","why":"Geneticists borrowed the image of pieces from different sources lying in one body. The whole is one organism, but its cells are not all the same.","whyCN":"遗传学家借用「不同来源的小块同处一体」的意象：整体是一个生物体，细胞却并不完全相同。"},{"no":"06","title":"Image built from many photographs","titleCN":"由许多照片拼成的数字图像","definition":"a digital image assembled from many small photographs so that they form a larger picture","definitionCN":"由许多小照片拼合、在远处构成更大画面的数字图像","example":"The poster was a mosaic of thousands of reader photos.","exampleCN":"那张海报由数千张读者照片拼成。","why":"The digital version repeats the old rule: each tile is a whole image by itself, yet at a distance it becomes one pixel in a larger face.","whyCN":"数字版本重复了旧规则：每一小块本身都是一张完整照片，远看却成为更大画面里的一个像素。"},{"no":"07","title":"Patchwork of habitats in ecology","titleCN":"生态学中由多种生境拼成的格局","definition":"in ecology, a landscape made of distinct habitat patches lying side by side","definitionCN":"生态学中，由彼此相邻的不同生境斑块构成的景观","example":"Fire created a mosaic of open grass and young forest.","exampleCN":"火灾造成了草地与幼林交错的生境格局。","why":"Ecologists see a landscape as a floor of patches. Each patch keeps its own character, and the whole supports more life than any single patch would.","whyCN":"生态学家把景观看成由斑块铺成的地面。每块保留自己的性质，整体能供养的生命比任何单块都多。"},{"no":"08","title":"Made of many small parts","titleCN":"形容词义：由许多小部分构成的","definition":"made up of many small, distinct parts rather than one uniform substance","definitionCN":"由许多细小而彼此不同的部分构成，而非单一均匀的物质","example":"The old farmland survives as a mosaic landscape.","exampleCN":"旧农田以拼块状景观的形式留存下来。","why":"As an adjective the word simply states the structure that the noun implies: not one mass, but many pieces set together.","whyCN":"作形容词时，这个词只是把名词所隐含的结构说出来：不是一整块，而是许多小块拼在一起。"},{"no":"09","title":"Unity that keeps parts visible","titleCN":"抽象义：保持各部分的统一","definition":"any unity in which the separate contributors remain visible instead of being fused","definitionCN":"任何各部分仍清晰可见、未被熔为一体的统一体","example":"History is a mosaic of remembered fragments, not a single stream.","exampleCN":"历史是记忆碎片的拼合，而不是一条单一的河流。","why":"The abstract sense states what every earlier sense shares: the whole is real, but it never erases the edges of its pieces.","whyCN":"抽象义说出了前面各义项的共同点：整体确实存在，但它从不抹去各小块的边界。"}],"etymology":{"intro":{"en":"Mosaic reached English through French and Italian from a Latin word for mosaic work. The Latin term is generally believed to go back to the Muse, but the chain is not fully settled. Dates are approximate.","cn":"mosaic 经法语与意大利语来自一个表示「镶嵌作品」的拉丁词。这个拉丁词一般认为可追溯到「缪斯」，但整条链条并未完全定论。年代均为约数。"},"items":[{"era":"LATIN MUSA","en":"Latin musa 'muse' came from Greek mousa. Work worthy of the Muses was called mousikos or mouseios, a word for art and learning rather than for stonework.","cn":"拉丁 musa「缪斯」来自希腊 mousa。配得上缪斯的作品被称作 mousikos 或 mouseios，这个词当时指艺术与学问，而不是石头工艺。"},{"era":"LATE LATIN MUSIVUM","en":"The phrase opus musivum, 'work of the Muses', is generally believed to name mosaic decoration. The adjective musaicus appears in late Latin texts beside it.","cn":"短语 opus musivum 意为「缪斯之作」，一般认为指镶嵌装饰。晚期拉丁文献中还有形容词 musaicus 与它并用。"},{"era":"ITALIAN MOSAICO","en":"Italian mosaico named both the work and the craft, and it is the form that spread through Mediterranean trade and church building.","cn":"意大利语 mosaico 既指作品，也指工艺；正是这个形式随地中海贸易与教堂建造传播开来。"},{"era":"FRENCH MOSAÏQUE","en":"French mosaïque carried the word into English in the sixteenth century, first for wall and floor decoration.","cn":"法语 mosaïque 在十六世纪把这个词带进英语，最初指墙面与地面的装饰。"},{"era":"MODERN EXTENSIONS","en":"From the nineteenth century the word was applied to mixed societies, and later to genetics, digital images and patchy landscapes, all by the same image of separate pieces in one frame.","cn":"从十九世纪起，这个词被用于混合社会，后来又用于遗传学、数字图像与斑块状景观，靠的都是「分离小块同处一框」的同一个意象。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: some references link the Latin adjective to Greek mouseion 'place of the Muses', while others doubt any direct derivation from the Muse at all, and no pre-Greek origin can be demonstrated.","cn":"来源不确定：一些资料把这个拉丁形容词与希腊 mouseion「缪斯之所」联系起来，另一些则根本怀疑它与缪斯有直接派生关系，而其希腊语之前的来源无法证明。"}]},"similar":{"note":{"en":"Group one holds near spellings with different histories; group two holds words for composite works made of many parts.","cn":"第一组是拼写相近但来历不同的词；第二组是同样表示「由许多部分构成的作品」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"Mosaic","ipa":"/ˈməʊzeɪk/","tag":"different word, capitalised","definition":"relating to Moses, as in Mosaic law. It comes from the name Moses, not from the art term, and is usually written with a capital M.","definitionCN":"与摩西有关的，如摩西律法。它来自人名摩西，而非镶嵌艺术，通常首字母大写。"},{"word":"musical","ipa":"/ˈmjuːzɪkəl/","tag":"distant relative","definition":"relating to music. Music and mosaic are generally believed to share the Muse root, but the words split long before English.","definitionCN":"与音乐有关的。一般认为 music 与 mosaic 共享缪斯词根，但两个词在进入英语之前早已分开。"},{"word":"museum","ipa":"/mjuˈziːəm/","tag":"Muse place","definition":"a building for displaying objects of art or science. It comes from Greek mouseion, a place of the Muses, so it is a cousin rather than a synonym.","definitionCN":"陈列艺术或科学物品的场所。它来自希腊 mouseion「缪斯之所」，因此是远亲而非同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"collage","ipa":"/kəˈlɑːʒ/","tag":"pasted pieces","definition":"a picture made by pasting paper, cloth or photographs onto a surface; the pieces stay flat and visible, unlike set stones.","definitionCN":"把纸、布或照片粘贴在表面上形成的画面；各片平贴可见，不像嵌入的石子。"},{"word":"patchwork","ipa":"/ˈpætʃwɜːk/","tag":"sewn pieces","definition":"cloth made by sewing many pieces together, or any whole of mixed parts; it stresses stitching rather than setting.","definitionCN":"把许多布片缝在一起做成的织物，或任何混合部分构成的整体；强调缝接而非嵌置。"},{"word":"montage","ipa":"/ˈmɒntɑːʒ/","tag":"film and photo","definition":"a composite image or sequence made by cutting and joining separate shots; the joins are meant to be felt.","definitionCN":"通过剪辑拼接独立镜头而成的合成画面或片段；接缝是故意让人感觉到的。"},{"word":"inlay","ipa":"/ˈɪnleɪ/","tag":"set into a surface","definition":"material set into a hollowed surface to form a design, as in wood or metal; it is close in technique but narrower in material.","definitionCN":"把材料嵌进挖空的表面形成图案，如木器或金属器；技法相近，但材料范围更窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin phrase for the art meant 'work of the Muses', which links the craft to the arts rather than to building.","cn":"指这门艺术的拉丁短语意为「缪斯之作」，把工艺与艺术而非建筑连在一起。"},{"en":"A mosaicist is the person; mosaic is the work and the craft.","cn":"mosaicist 是做这件事的人；mosaic 既是作品，也是工艺。"},{"en":"Fixed phrases mark the places where it appears: mosaic floor, mosaic pattern, glass mosaic.","cn":"固定搭配标出它出现的地方：镶嵌地面、镶嵌图案、玻璃马赛克。"},{"en":"The social sense keeps the picture: a mosaic of cultures, a mosaic of languages.","cn":"社会义保留了这个画面：文化的拼合、语言的拼合。"},{"en":"Genetics uses the same word for one body made of cells from more than one line.","cn":"遗传学用同一个词指一个体内含有一条以上细胞来源的身体。"}],"abstract":[{"en":"Picture a broken plate that becomes a better picture than the whole plate ever was.","cn":"想象一只打碎的盘子，拼出的画比完整的盘子本身更好看。"},{"en":"Picture a city map where every block keeps its own colour and still reads as one city.","cn":"想象一张城市地图，每个街区保留自己的颜色，却仍读作一座城。"},{"en":"Picture a crowd photo where each face is clear at close range and only a dot from far away.","cn":"想象一张人群合影，近看每张脸都清楚，远看只是一个点。"}]},"examples":[{"en":"The restored mosaic covers the whole apse with blue and gold glass.","cn":"修复后的镶嵌画用蓝金两色玻璃铺满整个半圆殿。"},{"en":"The neighborhood is a mosaic of old workshops and new studios.","cn":"这个街区是旧作坊与新工作室拼合成的整体。"},{"en":"The software builds a mosaic from a folder of holiday photos.","cn":"这款软件用一个文件夹里的假日照片拼成一幅马赛克图。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「马赛克」是中文音译：一块块小砖像赛场上的队伍，拼起来才成一整幅画 → 镶嵌画","word":"mosaic"},"root":"经法语与意大利语上溯至晚期拉丁 opus musivum「缪斯之作」，一般认为与拉丁 musa、希腊 mousa「缪斯」有关；但直接派生链条不确定，另有与 mouseion 相联的假说，均不选定论。","sensesIntro":{"en":"Nine senses follow one structure: many separate pieces are set into one frame. The frame can be a floor, an art form, a society, a body, a digital image, a landscape, or finally any unity that refuses to melt its parts.","cn":"九个义项围绕同一种结构：许多分离的小块被嵌进同一个框。这个框可以是地面、一门艺术、一个社会、一个身体、一幅数字图像、一片景观，最后是任何拒绝熔掉各部分的统一体。"},"semanticMap":{"core":{"en":"CORE IMAGE: hundreds of small stones set in mortar, each distinct, all forming one bird.","cn":"核心意象：数百颗小石子嵌在灰泥里，每颗都独立，合起来却是一只鸟。"},"chain":["SMALL PIECES","SET IN SURFACE","WHOLE PICTURE","MIXED WHOLE","VISIBLE PARTS","PIXEL GRID"],"branches":[{"senses":"01","en":"THE PICTURE: the first sense is the finished image that the pieces make.","cn":"画面：第一个义项是这些小块最终拼成的成品图。"},{"senses":"02 · 03","en":"THE CRAFT AND ITS HOME: the technique and the wall or floor it covers are the act and its place.","cn":"工艺与所在：技法与它所覆盖的墙面或地面，是动作与场所。"},{"senses":"04 · 09","en":"SOCIETY AND ABSTRACTION: a mixed society and a kept-parts unity apply the same frame to people and ideas.","cn":"社会与抽象：混合社会与保留部分的统一体，把同一个框用到人与观念上。"},{"senses":"05 · 06","en":"BODY AND IMAGE: genetics and digital pictures both assemble one whole from unlike small units.","cn":"身体与图像：遗传学与数字图片都用不同的小单元拼成一个整体。"},{"senses":"07 · 08","en":"LANDSCAPE STRUCTURE: habitat patches and the adjective describe a surface made of many distinct parts.","cn":"景观结构：生境斑块与形容词义都描述由许多不同部分构成的表面。"}]},"affixes":{"intro":{"en":"Mosaic is a Latin-derived word whose family is built on the Muse: the art of the Muses gave its name to the craft, and the same root reaches music and the museum.","cn":"mosaic 是一个源自拉丁语的词，其词族以「缪斯」为核心：缪斯的艺术给了这门工艺名称，同一词根还通到音乐与博物馆。"},"latinIntro":{"en":"Latin musa and the late Latin adjective musaicus stand behind mosaic; Greek mousa is the older source, and mouseion gives museum.","cn":"拉丁 musa 与晚期拉丁形容词 musaicus 是 mosaic 的来源；更早的源头是希腊 mousa，而 mouseion 则给出 museum。"},"items":[{"word":"mus-","structure":"mus- (bound root from Latin musa)","meaning":"Muse; art, music, learning","meaningCN":"缪斯；艺术、音乐、学问","example":"The root ties stonework to the arts of the Muses.","exampleCN":"这个词根把石头工艺与缪斯的艺术系在一起。"},{"word":"musa","structure":"musa (Latin noun, first declension)","meaning":"a Muse, a goddess of the arts","meaningCN":"缪斯；掌管艺术的女神","example":"Latin musa came from Greek mousa.","exampleCN":"拉丁 musa 来自希腊 mousa。"},{"word":"mosaic","structure":"Italian mosaico, from late Latin musaicus","meaning":"a picture set in small pieces","meaningCN":"用小片嵌成的画","example":"The floor mosaic shows a hunting scene.","exampleCN":"地面镶嵌画表现的是一场狩猎。"},{"word":"mosaicist","structure":"mosaic + -ist (person who practises)","meaning":"an artist who makes mosaics","meaningCN":"制作镶嵌画的艺术家","example":"The mosaicist cut each stone by hand.","exampleCN":"镶嵌师亲手切割每一颗石子。"},{"word":"mosaicked","structure":"mosaic + -ed (provided with)","meaning":"decorated with mosaic work","meaningCN":"用镶嵌工艺装饰的","example":"The chapel is fully mosaicked.","exampleCN":"这座小礼拜堂通体用镶嵌装饰。"},{"word":"mosaicking","structure":"mosaic + -ing (action noun)","meaning":"the act or process of setting a mosaic","meaningCN":"镶嵌的过程；铺镶工作","example":"Mosaicking the vault took two years.","exampleCN":"给拱顶铺镶花了两年。"},{"word":"mosaic-like","structure":"mosaic + -like (resembling)","meaning":"resembling a mosaic in structure","meaningCN":"结构上像镶嵌画的","example":"The field shows a mosaic-like pattern.","exampleCN":"田野呈现出类似镶嵌的图案。"},{"word":"music","structure":"Greek mousike, 'art of the Muses'","meaning":"the art of sound","meaningCN":"音乐","example":"Music and mosaic share the Muse root.","exampleCN":"music 与 mosaic 共享缪斯词根。"},{"word":"musical","structure":"music + -al (relating to)","meaning":"relating to music","meaningCN":"音乐的","example":"The evening had a musical programme.","exampleCN":"晚会安排了音乐节目。"},{"word":"museum","structure":"Greek mouseion, 'place of the Muses'","meaning":"a building for showing art or science","meaningCN":"博物馆","example":"The museum holds the city's mosaics.","exampleCN":"博物馆收藏着这座城市的镶嵌画。"}],"latinEntries":[{"word":"musa","structure":"musa, musae (f., first declension)","meaning":"a Muse","meaningCN":"缪斯"},{"word":"musivum","structure":"musivum, musivi (n., second declension)","meaning":"mosaic work","meaningCN":"镶嵌作品"},{"word":"musaicus","structure":"musaicus, musaica, musaicum (adj., first and second declension)","meaning":"of mosaic work; of the Muses","meaningCN":"镶嵌作品的；缪斯的"}]}},{"word":"mosaic art","ipa_uk":"/məʊˈzeɪɪk ɑːt/","ipa_us":"/moʊˈzeɪɪk ɑːrt/","definition_zh":"镶嵌艺术；马赛克艺术","definition_en":"the art of making pictures and patterns by setting small pieces into a surface","core_image":"一面长墙上，成千上万块碎瓷砖各就各位，拼出远看才显形的一幅大画","scene":"社区中心邀请居民把旧瓷砖敲碎，一起贴在长墙上。The community invited residents to turn broken tiles into a large wall of mosaic art.","sceneCN":"这里指「以小块材料拼嵌成画面的艺术门类」（第 1 个义项：镶嵌作为一门艺术）；句意为社区邀请居民把碎瓷砖拼成长墙上的镶嵌艺术墙。可辨识物件：碎瓷砖、长墙、胶桶、居民的手。","pos":[{"tag":"n.","zh":"镶嵌艺术（作为艺术门类）"},{"tag":"n.","zh":"镶嵌艺术作品（集合或单件）"}],"collocations":[{"phrase":"ancient mosaic art","zh":"古代镶嵌艺术"},{"phrase":"Byzantine mosaic art","zh":"拜占庭镶嵌艺术"},{"phrase":"modern mosaic art","zh":"现代镶嵌艺术"},{"phrase":"study mosaic art","zh":"学习镶嵌艺术"},{"phrase":"a mosaic art studio","zh":"镶嵌艺术工作室"},{"phrase":"the revival of mosaic art","zh":"镶嵌艺术的复兴"}],"forms":[{"label":"单数形式","form":"mosaic art"},{"label":"复数形式（指多个门类或作品）","form":"mosaic arts"},{"label":"所有格","form":"mosaic art's"},{"label":"定语用法","form":"mosaic-art"}],"derivatives":[{"word":"mosaic artist","pos":"n.","zh":"镶嵌艺术家（由本短语前半与表示「艺术家」的词复合，指以镶嵌为创作方式的人）"},{"word":"mosaic artwork","pos":"n.","zh":"镶嵌艺术作品（由本短语前半与表示「作品」的词复合，指具体的镶嵌成品）"},{"word":"mosaic arts","pos":"n.","zh":"镶嵌艺术门类（由本短语前半与表示「门类」的复数形式复合，指这一类别下的多种形式）"},{"word":"mosaicist","pos":"n.","zh":"镶嵌师（由基础词加表示「从事者」的后缀构成，语义收窄为职业身份）"}],"senses":[{"no":"01","title":"The art form itself","titleCN":"镶嵌艺术这一门类","definition":"the art of composing images from small pieces of stone, glass or tile set into a surface","definitionCN":"把石头、玻璃或瓷砖的小块嵌进表面、组成画面的艺术","example":"The community invited residents to turn broken tiles into mosaic art.","exampleCN":"社区邀请居民把碎瓷砖变成镶嵌艺术。","why":"The phrase adds the word for art to the word for the work, so it names the discipline rather than any single object.","whyCN":"这个短语在表示作品的词后面加上「艺术」，因此命名的是门类，而不是某一件成品。"},{"no":"02","title":"Ancient floor tradition","titleCN":"古代地面镶嵌传统","definition":"the tradition of decorated floors practised in Greek, Roman and later Mediterranean buildings","definitionCN":"希腊、罗马及后来地中海建筑中装饰地面的传统","example":"Ancient mosaic art survives best in the floors of villas.","exampleCN":"古代镶嵌艺术保存得最好的是别墅地面。","why":"Floors were the first large surface that could take the technique. The art grew where people walked, not where they looked up.","whyCN":"地面是最早能承载这种技法的大面积表面。这门艺术成长于人行走之处，而不是人抬头仰望之处。"},{"no":"03","title":"Byzantine wall and vault work","titleCN":"拜占庭墙面与穹顶镶嵌","definition":"the use of glass mosaic on church walls and vaults to create luminous sacred images","definitionCN":"在教堂墙面与穹顶上用玻璃镶嵌营造发光的神圣图像","example":"Byzantine mosaic art fills the vault with gold light.","exampleCN":"拜占庭镶嵌艺术用金光填满穹顶。","why":"Glass pieces reflect light from every angle, so the technique moved from the floor to the ceiling, where light could make the image glow.","whyCN":"玻璃小块从各个角度反光，于是这门技法从地面移到天花板，让光把图像点亮。"},{"no":"04","title":"Modern revival","titleCN":"近现代的复兴","definition":"the renewed use of mosaic art by nineteenth and twentieth century designers and architects","definitionCN":"十九、二十世纪设计师与建筑师对镶嵌艺术的重新运用","example":"Modern mosaic art returned to public buildings and metro stations.","exampleCN":"现代镶嵌艺术重新回到公共建筑与地铁站。","why":"Industrial tiles made the pieces cheap and regular, so architects could cover large modern surfaces with the old technique.","whyCN":"工业生产的瓷砖让小块变得便宜而规整，建筑师因此能用这门古老技法覆盖现代的大面积表面。"},{"no":"05","title":"Community and public work","titleCN":"社区与公共艺术","definition":"mosaic art made collectively by residents or volunteers in a public place","definitionCN":"由居民或志愿者在公共场所共同完成的镶嵌艺术","example":"The school's mosaic art project gave every pupil one tile.","exampleCN":"学校的镶嵌艺术项目让每个学生负责一块瓷砖。","why":"The technique naturally divides a picture into many small tasks, so it suits a group where each person contributes one piece.","whyCN":"这种技法天然把一幅画拆成许多小任务，因此适合每人负责一块的集体创作。"},{"no":"06","title":"Studio craft and teaching","titleCN":"工作室工艺与教学","definition":"mosaic art as a taught craft practised in studios with cutters, nippers and adhesives","definitionCN":"作为可教授的手艺，在工作室里借助切割器、钳子与黏合剂来制作","example":"She teaches mosaic art to adults on Saturday mornings.","exampleCN":"她周六上午教成年人镶嵌艺术。","why":"Once the work became a subject in art schools, the phrase named a course and a set of tools rather than a monument.","whyCN":"当这门作品成为艺术学校的科目后，这个短语就指一门课程与一套工具，而不再指某座纪念碑。"},{"no":"07","title":"Digital photographic mosaic","titleCN":"数字照片镶嵌","definition":"a digital form in which many small photographs are arranged to form a larger image","definitionCN":"把许多小照片排布成更大图像的数字形式","example":"Digital mosaic art builds a portrait from hundreds of snapshots.","exampleCN":"数字镶嵌艺术用数百张快照拼出一幅肖像。","why":"The computer repeats the old logic without stone: each small image is complete in itself, yet together they form one face.","whyCN":"计算机不用石头却重复了旧逻辑：每张小图自身完整，合起来却构成一张脸。"},{"no":"08","title":"Architectural surface design","titleCN":"建筑表面设计","definition":"the integration of mosaic art into the surfaces of a building as part of its design","definitionCN":"把镶嵌艺术整合进建筑表面，作为建筑设计的一部分","example":"Mosaic art turns the station wall into a map of the river.","exampleCN":"镶嵌艺术把车站墙面变成一幅河流地图。","why":"Because the pieces are fixed to the structure, the art can act as skin. This sense joins the craft back to architecture.","whyCN":"因为小块被固定在结构上，艺术可以充当皮肤。这一义项把这门工艺重新接回建筑。"}],"etymology":{"intro":{"en":"Mosaic art joins two borrowings: mosaic, which came through French and Italian from a Latin word for mosaic work, and art, which came through Old French from Latin ars 'skill'. Dates are approximate.","cn":"mosaic art 由两个借词组合而成：mosaic 经法语与意大利语来自一个表示镶嵌作品的拉丁词，art 经古法语来自拉丁 ars「技艺」。年代均为约数。"},"items":[{"era":"LATIN ARS","en":"Latin ars (genitive artis) meant 'skill, craft, method'. Its deeper origin is source uncertain; a link to a root meaning 'to fit together' is a reconstructed form, not a recorded word.","cn":"拉丁 ars（属格 artis）意为「技艺、手艺、方法」。其更深来源属「来源不确定」；把它连到某个意为「拼合」的词根，只是重构形式，并非有记录的真实词形。"},{"era":"OLD FRENCH ART","en":"Old French art carried both 'skill' and 'knowledge' into English, where the word long meant learned technique before it narrowed to the fine arts.","cn":"古法语 art 把「技艺」与「知识」两层意思带进英语；这个词长期指习得的技法，后来才收窄到美术。"},{"era":"LATIN MUSA","en":"Latin musa 'muse' and the late Latin adjective musaicus are generally believed to stand behind mosaic, although the exact chain from the Muse to stonework is not settled.","cn":"拉丁 musa「缪斯」与晚期拉丁形容词 musaicus 一般认为与 mosaic 有关，但从缪斯到石头工艺的确切链条并未定论。"},{"era":"ITALIAN AND FRENCH","en":"Italian mosaico and French mosaïque supplied the English noun in the sixteenth century, first for decorated floors and walls.","cn":"意大利语 mosaico 与法语 mosaïque 在十六世纪提供了英语名词，最初指装饰过的地面与墙面。"},{"era":"ENGLISH COMPOUND","en":"The compound mosaic art appears in art writing once mosaics were discussed as a discipline with its own history and schools.","cn":"当镶嵌被当作一门有自身历史与流派的手艺来讨论时，复合词 mosaic art 才出现在艺术写作中。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin history of both ars and musa is unsettled, and the route from the Muse to mosaic remains a hypothesis rather than a demonstrated derivation.","cn":"来源不确定：ars 与 musa 在拉丁语之前的历史都无定论，而从缪斯到 mosaic 的路径仍属假说，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds compounds that share the mosaic word but name other things; group two holds names for related art forms.","cn":"第一组是共用 mosaic 一词、却指别的事物的复合词；第二组是相邻艺术门类的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mosaic","ipa":"/məʊˈzeɪɪk/","tag":"short form, different scope","definition":"the single word names a work or the craft in general; the longer phrase names the art as a discipline.","definitionCN":"单词形式指一件作品或笼统的工艺；较长的短语则把镶嵌当作一门艺术门类。"},{"word":"mosaic tile","ipa":"/məʊˈzeɪɪk taɪl/","tag":"material, not the art","definition":"one small piece of tile used in the technique; it is a material, not an art form.","definitionCN":"这门技法使用的一小块瓷砖；它是材料，不是艺术门类。"},{"word":"mosaic floor","ipa":"/məʊˈzeɪɪk flɔː/","tag":"object, not the art","definition":"a decorated floor made in this technique; it names a place or object, not the discipline.","definitionCN":"用这种技法做的装饰地面；它指场所或物件，而非学科。"},{"word":"mosaicist","ipa":"/məʊˈzeɪɪsɪst/","tag":"person, not the practice","definition":"a person who makes mosaics; it names the maker rather than the art.","definitionCN":"制作镶嵌画的人；它指创作者，而非艺术本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mosaic","ipa":"/məʊˈzeɪɪk/","tag":"the work itself","definition":"the finished picture or pattern; mosaic art is the discipline that produces it.","definitionCN":"完成的画面或图案；镶嵌艺术则是产出它的那门学科。"},{"word":"tessellation","ipa":"/ˌtesəˈleɪʃən/","tag":"tiling pattern","definition":"a pattern of shapes fitted together without gaps or overlaps; it stresses geometry rather than picture-making.","definitionCN":"形状无缝无叠地拼合的图案；强调几何，而非造像。"},{"word":"inlay","ipa":"/ˈɪnleɪ/","tag":"set-in decoration","definition":"the craft of setting contrasting material into a hollowed surface; it is a technique cousin with a narrower material range.","definitionCN":"把对比材料嵌进挖空表面的工艺；是技法上的近亲，材料范围更窄。"},{"word":"fresco","ipa":"/ˈfreskəʊ/","tag":"wall painting","definition":"wall painting done on fresh lime plaster; it shares the architectural setting but uses paint, not pieces.","definitionCN":"在未干石灰层上作的壁画；同样依附建筑，但用颜料而非小块。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The phrase is simply the noun for the work plus the noun for skill: the skill of making mosaics.","cn":"这个短语就是把表示作品的词与表示技艺的词并在一起：制作镶嵌画的技艺。"},{"en":"Art goes back to Latin ars 'skill', so mosaic art is literally the skill of setting pieces.","cn":"art 上溯到拉丁 ars「技艺」，因此这个短语字面上就是「嵌置小块的技艺」。"},{"en":"Fixed phrases sort its periods: ancient, Byzantine, modern, public.","cn":"固定搭配按时期分类：古代的、拜占庭的、现代的、公共的。"},{"en":"A mosaic artist is the person; mosaic art is the field.","cn":"mosaic artist 指人；mosaic art 指领域。"},{"en":"The plural mosaic arts names the branches taught under one heading.","cn":"复数形式指同一名目下所教的各个分支。"}],"abstract":[{"en":"Picture a classroom where thirty children each hold one coloured square and the picture appears only when all stand together.","cn":"想象一间教室，三十个孩子各拿一块彩色方片，只有全部站到一起，图画才出现。"},{"en":"Picture a wall that changes colour as you walk past because each tiny piece turns the light differently.","cn":"想象一面墙，你走过时颜色不断变化，因为每颗小片反光的角度都不同。"},{"en":"Picture an art that cannot be moved without becoming rubble.","cn":"想象一门艺术，一旦搬动就会变成碎石。"}]},"examples":[{"en":"Roman mosaic art spread with the legions across the empire.","cn":"罗马镶嵌艺术随军团传遍帝国。"},{"en":"The city commissioned mosaic art for the new metro entrance.","cn":"市政府为新地铁入口委约了镶嵌艺术。"},{"en":"Students learn mosaic art by copying a small Byzantine panel.","cn":"学生通过临摹一小块拜占庭镶嵌板来学习镶嵌艺术。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「马赛克艺术」：把打碎的马赛克（瓷砖）拼成画 → 镶嵌艺术","word":"mosaic art"},"root":"由 mosaic 与 art 组合：mosaic 经法语、意大利语上溯至晚期拉丁 musaicus，一般认为与缪斯有关但链条不确定；art 经古法语上溯至拉丁 ars「技艺」，其更早来源不确定。","sensesIntro":{"en":"Eight senses follow one discipline through its settings: it begins as a named art, moves from ancient floors to Byzantine vaults, is revived by modern architects, practised by communities and studios, rebuilt digitally, and finally treated as the skin of a building.","cn":"八个义项让同一门艺术穿过不同场景：它先被命名为一门艺术，从古代地面走到拜占庭穹顶，被现代建筑师复兴，由社区与工作室实践，再以数字方式重建，最后被当作建筑的皮肤。"},"semanticMap":{"core":{"en":"CORE IMAGE: one wall made of thousands of separate pieces, readable only when they are all in place.","cn":"核心意象：一面由成千上万小块组成的墙，只有全部就位才读得成画。"},"chain":["ART DISCIPLINE","ANCIENT FLOOR","SACRED VAULT","MODERN REVIVAL","PUBLIC PRACTICE","CONTEMPORARY STUDIO"],"branches":[{"senses":"01","en":"THE NAME: the phrase first sets the craft apart as an art with a history.","cn":"名目：这个短语首先把这门工艺确立为一门有历史的艺术。"},{"senses":"02 · 03","en":"FROM FLOOR TO VAULT: the same technique moves from the ground people walk on to the ceiling they look up at.","cn":"从地面到穹顶：同一技法从人脚下的地面移到人仰望的天花板。"},{"senses":"04 · 08","en":"ART IN ARCHITECTURE: modern revival and surface design both put the craft back onto buildings.","cn":"建筑中的艺术：现代复兴与表面设计都把工艺重新放回建筑上。"},{"senses":"05 · 06","en":"HANDS AND TEACHING: community projects and studio classes turn the art into shared practice.","cn":"手与教学：社区项目与工作室课程把这门艺术变成共同实践。"},{"senses":"07","en":"DIGITAL COUNTERPART: photographs replace stone while the rule of small units stays the same.","cn":"数字对应物：照片取代石头，而小单元拼合的规则保持不变。"}]},"affixes":{"intro":{"en":"The phrase is built from two old borrowings, one for the work and one for skill, and both carry large families into English.","cn":"这个短语由两个古老借词构成，一个表示作品，一个表示技艺，两者都为英语带来庞大的词族。"},"latinIntro":{"en":"Latin ars and Latin musa stand behind the two halves; art, artist, artistic and artisan come from the first, while mosaic and museum come from the second.","cn":"拉丁 ars 与拉丁 musa 分别是两半的来源；art、artist、artistic 与 artisan 出自前者，mosaic 与 museum 出自后者。"},"items":[{"word":"ars","structure":"ars, artis (Latin noun, third declension)","meaning":"skill, craft, method","meaningCN":"技艺；手艺；方法","example":"Ars names learned skill rather than mere labour.","exampleCN":"ars 指习得的技艺，而不只是体力劳动。"},{"word":"art","structure":"Latin ars through Old French","meaning":"skill; the fine arts","meaningCN":"技艺；美术","example":"Art once meant any learned skill.","exampleCN":"art 原指任何习得的技艺。"},{"word":"artist","structure":"art + -ist (person who practises)","meaning":"a person who makes art","meaningCN":"艺术家","example":"The artist works in glass and stone.","exampleCN":"这位艺术家用玻璃与石头创作。"},{"word":"artistic","structure":"artist + -ic (relating to)","meaning":"relating to art or artists","meaningCN":"艺术的；艺术家的","example":"The mosaic has real artistic value.","exampleCN":"这幅镶嵌画有真正的艺术价值。"},{"word":"artisan","structure":"Italian artigiano, from Latin ars","meaning":"a skilled craft worker","meaningCN":"工匠；手艺人","example":"The artisan cuts each tile by hand.","exampleCN":"工匠亲手切割每一块砖。"},{"word":"artifact","structure":"arte 'by skill' + factum 'made'","meaning":"an object made by human skill","meaningCN":"人工制品；文物","example":"The floor yielded many small artifacts.","exampleCN":"这处地面出土了许多小件人工制品。"},{"word":"mosaic","structure":"Italian mosaico, from late Latin musaicus","meaning":"a picture set in small pieces","meaningCN":"镶嵌画","example":"The mosaic fills the apse.","exampleCN":"镶嵌画铺满半圆殿。"},{"word":"mosaicist","structure":"mosaic + -ist (person who practises)","meaning":"a mosaic artist","meaningCN":"镶嵌艺术家","example":"The mosaicist planned the colour scheme.","exampleCN":"镶嵌师规划了配色。"},{"word":"mosaic art","structure":"mosaic + art","meaning":"the discipline of making mosaics","meaningCN":"镶嵌艺术","example":"Mosaic art is taught in the studio.","exampleCN":"工作室教授镶嵌艺术。"},{"word":"mosaic artist","structure":"mosaic + artist","meaning":"a person who practises mosaic art","meaningCN":"镶嵌艺术家","example":"The mosaic artist worked on site.","exampleCN":"镶嵌艺术家在现场创作。"}],"latinEntries":[{"word":"ars","structure":"ars, artis (f., third declension)","meaning":"skill, craft, art","meaningCN":"技艺；手艺；艺术"},{"word":"musa","structure":"musa, musae (f., first declension)","meaning":"a Muse","meaningCN":"缪斯"},{"word":"musivum","structure":"musivum, musivi (n., second declension)","meaning":"mosaic work","meaningCN":"镶嵌作品"}]}},{"word":"stained glass","ipa_uk":"/ˌsteɪnd ˈɡlɑːs/","ipa_us":"/ˌsteɪnd ˈɡlæs/","definition_zh":"彩色玻璃；彩色玻璃窗；彩色玻璃工艺","definition_en":"coloured glass used in windows, or a window made from such glass","core_image":"铅条把一块块红蓝玻璃框住，阳光穿过时把整间屋子染成宝石般的颜色","scene":"工匠把红蓝两色玻璃按铅条拼好，抬进教堂的尖窗。The craftsman set the stained glass into the pointed window of the chapel.","sceneCN":"这里指「经过着色、用于窗上的玻璃」（第 1 个义项：彩色玻璃这种材料）；句意为工匠把彩色玻璃装进小礼拜堂的尖顶窗。可辨识物件：铅条、红蓝玻璃片、尖窗、木梯。","pos":[{"tag":"n.","zh":"彩色玻璃（材料）"},{"tag":"n.","zh":"彩色玻璃窗（可数，指一扇窗）"}],"collocations":[{"phrase":"a stained glass window","zh":"一扇彩色玻璃窗"},{"phrase":"medieval stained glass","zh":"中世纪彩色玻璃"},{"phrase":"stained glass panels","zh":"彩色玻璃板"},{"phrase":"a stained glass artist","zh":"彩色玻璃艺术家"},{"phrase":"restore the stained glass","zh":"修复彩色玻璃"},{"phrase":"the stained glass in the chapel","zh":"小礼拜堂里的彩色玻璃"}],"forms":[{"label":"不可数用法（指材料）","form":"stained glass"},{"label":"可数用法（指一扇窗，须与窗字连用）","form":"a stained glass window"},{"label":"复数形式（指多扇窗）","form":"stained glasses"},{"label":"所有格","form":"stained glass's"},{"label":"定语用法","form":"stained-glass"}],"derivatives":[{"word":"stained-glass window","pos":"n.","zh":"彩色玻璃窗（由本短语与表示「窗」的词复合，语义收窄为建筑构件）"},{"word":"stained-glass artist","pos":"n.","zh":"彩色玻璃艺术家（由本短语与表示「艺术家」的词复合，语义偏移为职业身份）"},{"word":"stained-glass panel","pos":"n.","zh":"彩色玻璃嵌板（由本短语与表示「嵌板」的词复合，指可独立安装的一片）"},{"word":"stained-glass-like","pos":"adj.","zh":"类似彩色玻璃效果的（由本短语加表示「像……的」后缀构成，语义偏移为性质描述）"}],"senses":[{"no":"01","title":"Coloured glass used in windows","titleCN":"用于窗户的彩色玻璃","definition":"glass that has been coloured, especially for use in windows","definitionCN":"经过着色、尤用于窗户的玻璃","example":"The craftsman set the stained glass into the pointed window.","exampleCN":"工匠把彩色玻璃装进尖顶窗。","why":"The phrase names the material by the way it was treated. Glass is 'stained' when colour is fixed into or onto it, so the colour is the point of the name.","whyCN":"这个短语按处理方式来命名材料。玻璃被「染色」是指颜色被固定进玻璃内部或表面，所以颜色正是名称的关键。"},{"no":"02","title":"The craft of making it","titleCN":"制作彩色玻璃的工艺","definition":"the craft of cutting, colouring and joining glass pieces into a window design","definitionCN":"把玻璃片切割、着色并连接成窗户图案的手艺","example":"He trained in stained glass for six years.","exampleCN":"他学了六年彩色玻璃工艺。","why":"Once the material had a name, the name moved to the skill of working it. The craft covers cutting, painting, firing and leading.","whyCN":"材料有了名称之后，名称就转指加工它的技艺。这门手艺包括切割、绘制、烧制与铅条拼接。"},{"no":"03","title":"A window made of it","titleCN":"用彩色玻璃做成的窗","definition":"a window assembled from pieces of coloured glass held in lead or copper strips","definitionCN":"由彩色玻璃片嵌在铅条或铜条中拼成的窗户","example":"Every window in the nave is stained glass.","exampleCN":"中殿的每一扇窗都是彩色玻璃窗。","why":"The material and the object share one name because the material is almost never used for anything else in a church. The window is simply the glass in its frame.","whyCN":"材料与成品共用一名，因为这种材料在教堂里几乎不作他用。窗不过是镶在框里的那块玻璃。"},{"no":"04","title":"Sacred window art","titleCN":"宗教窗饰艺术","definition":"a church window treated as a work of sacred art telling a story in light","definitionCN":"把教堂窗户当作以光讲述故事的宗教艺术品","example":"The east window is the finest stained glass in the region.","exampleCN":"东窗是该地区最精美的彩色玻璃艺术品。","why":"In a church the window is not only a barrier but a picture. Light carries the story, so the object is judged as art rather than as glazing.","whyCN":"在教堂里，窗不只是隔挡，还是一幅画。光把故事带进来，因此这件物体被当作艺术而非普通窗玻璃来评判。"},{"no":"05","title":"Separate pieces and fragments","titleCN":"彩色玻璃的碎片与单件","definition":"the individual pieces of coloured glass, especially old fragments kept for repair","definitionCN":"一片片彩色玻璃，尤指为修复而保存的旧碎片","example":"The box held stained glass from a demolished church.","exampleCN":"盒子里装着从一座拆除教堂取下的彩色玻璃残片。","why":"A window is made of parts, and when it breaks the parts survive. Conservators therefore speak of the glass itself as countable pieces.","whyCN":"一扇窗由许多片组成，破碎后这些片仍能留存。修复师因此把玻璃本身当作可数的单件来说。"},{"no":"06","title":"Lamps and small panels","titleCN":"灯罩与小嵌板","definition":"coloured glass used in lamp shades, small panels and decorative objects","definitionCN":"用于灯罩、小嵌板与装饰物件的彩色玻璃","example":"The reading lamp had a stained glass shade.","exampleCN":"那盏阅读灯有一个彩色玻璃灯罩。","why":"The technique left the church and entered the home. A lamp shade uses the same coloured glass, only the light now comes from inside.","whyCN":"这门技法走出教堂进入住宅。灯罩用的是同样的彩色玻璃，只是光改从内部发出。"},{"no":"07","title":"Modern secular decoration","titleCN":"现代世俗装饰","definition":"coloured glass used in modern homes, restaurants and public buildings for decoration","definitionCN":"现代住宅、餐馆与公共建筑中用于装饰的彩色玻璃","example":"The hotel lobby is lit by stained glass panels.","exampleCN":"酒店大堂由彩色玻璃嵌板照明。","why":"When religious subjects gave way to abstract patterns, the material became a general decorative surface rather than a narrative one.","whyCN":"当宗教题材让位于抽象图案，这种材料就从叙事表面变成了一般的装饰表面。"},{"no":"08","title":"Heritage glass in museums","titleCN":"博物馆中的遗产玻璃","definition":"old coloured glass preserved, displayed or studied as a heritage object","definitionCN":"作为遗产物件被保存、展出或研究的古老彩色玻璃","example":"The museum keeps stained glass from dissolved monasteries.","exampleCN":"博物馆收藏着来自解散修道院的彩色玻璃。","why":"Once a window loses its building, the glass becomes a movable relic. The phrase then names a museum category, not an architectural fixture.","whyCN":"当窗户失去它所属的建筑，玻璃就成了可移动的遗物。这个短语于是指博物馆的藏品类别，而不是建筑构件。"}],"etymology":{"intro":{"en":"Stained glass joins a French-derived verb for dyeing with a native Germanic word for glass. The 'stain' in the name first referred to a silver compound painted onto the surface. Dates are approximate.","cn":"stained glass 由一个经法语而来的「染色」动词与一个本族日耳曼语的「玻璃」词组合而成。名称里的「染色」最初指涂在表面的银化合物。年代均为约数。"},"items":[{"era":"LATIN TINGERE","en":"Latin tingere meant 'to wet, soak, dye'. Colour was understood as something put into a liquid and then into a material.","cn":"拉丁 tingere 意为「弄湿、浸泡、染色」。颜色被理解成先进入液体、再进入材料的东西。"},{"era":"OLD FRENCH TEINDRE","en":"Old French teindre carried the verb into English as stain in the fourteenth century, first for dyeing cloth and later for marking a surface.","cn":"古法语 teindre 在十四世纪把这个动词带进英语，写作 stain，最初指染布，后来指在表面留下痕迹。"},{"era":"OLD ENGLISH GLÆS","en":"Old English glæs 'glass' comes from a Germanic form reconstructed as *glasam. The deeper origin is source uncertain; a connection with words for glowing is sometimes suggested but not proved.","cn":"古英语 glæs「玻璃」来自一个被重构为 *glasam 的日耳曼语形式。更深来源属「来源不确定」；有人提出它与表示「发光」的词有关，但未获证明。"},{"era":"SILVER STAIN (14TH CENTURY)","en":"Medieval glaziers painted a silver compound on clear glass and fired it, producing a yellow tone. This silver stain is the original 'stain' in stained glass.","cn":"中世纪玻璃匠把银化合物画在透明玻璃上再烧制，产生黄色调。这种「银染」正是 stained glass 名称中「染色」的最初所指。"},{"era":"COMPOUND TERM","en":"The full phrase stained glass spread in the nineteenth century as medieval windows were studied, collected and restored.","cn":"随着中世纪窗户被研究、收藏与修复，完整的短语 stained glass 在十九世纪流行开来。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Germanic origin of glass is unsettled, and any older form proposed for it is a reconstructed form rather than a recorded word.","cn":"来源不确定：glass 在日耳曼语之前的来源没有定论，凡为其提出的更早形式都是重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds window terms that look alike but name different treatments; group two holds words for coloured or decorative glass.","cn":"第一组是形近但指不同处理方式的窗用词；第二组是表示彩色或装饰玻璃的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"frosted glass","ipa":"/ˈfrɒstɪd ɡlɑːs/","tag":"surface treatment","definition":"glass made opaque by etching or sandblasting the surface; it is not coloured and carries no leaded picture.","definitionCN":"通过蚀刻或喷砂使表面变毛的玻璃；它没有着色，也不含铅条拼成的画面。"},{"word":"leaded glass","ipa":"/ˈliːdɪd ɡlɑːs/","tag":"structure, not colour","definition":"glass held together by lead strips; leaded glass may be clear, so the term names the structure while stained names the colour.","definitionCN":"用铅条连接起来的玻璃；铅条玻璃可以是透明的，因此前者指结构，后者指着色。"},{"word":"cathedral glass","ipa":"/kəˈθiːdrəl ɡlɑːs/","tag":"rolled texture","definition":"machine-rolled glass with a wavy surface; it imitates old window glass but is not necessarily stained.","definitionCN":"表面起伏的机制压延玻璃；模仿旧窗玻璃，但不一定经过染色。"},{"word":"glass stain","ipa":"/ɡlɑːs steɪn/","tag":"the pigment, not the window","definition":"the colouring compound applied to glass; it names the substance, while stained glass names the finished material.","definitionCN":"涂在玻璃上的着色化合物；它指着色物质，而 stained glass 指成品材料。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coloured glass","ipa":"/ˈkʌləd ɡlɑːs/","tag":"plain description","definition":"the everyday description for glass with colour; it lacks the craft and window associations of stained glass.","definitionCN":"对有色玻璃的日常说法；不含 stained glass 的工艺与窗饰联想。"},{"word":"art glass","ipa":"/ɑːt ɡlɑːs/","tag":"decorative glassware","definition":"decorative glass objects valued for design, often vases or bowls rather than windows.","definitionCN":"以设计见长的装饰玻璃器物，多为瓶碗而非窗户。"},{"word":"leadlight","ipa":"/ˈledlaɪt/","tag":"regional term","definition":"a decorative window of small glass pieces in lead cames, common in Australian and New Zealand English.","definitionCN":"用铅条把小玻璃片拼成的装饰窗，常见于澳大利亚与新西兰英语。"},{"word":"glass painting","ipa":"/ɡlɑːs ˈpeɪntɪŋ/","tag":"the painted layer","definition":"the craft of painting details onto glass before firing; it is one stage of stained glass work, not the whole product.","definitionCN":"在烧制前把细节画到玻璃上的工艺；它是彩色玻璃制作的一个环节，而非整件成品。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Stain is the old dyeing verb, so the glass is coloured rather than merely dirty.","cn":"stain 是古老的染色动词，所以这块玻璃是着了色的，而不只是被弄脏。"},{"en":"The silver stain of the fourteenth century explains why the word is 'stained' and not 'painted'.","cn":"十四世纪的银染说明了这个词为什么用「染色」而不是「绘制」。"},{"en":"Glazier and glazing belong to the same glass family as the material itself.","cn":"glazier 与 glazing 和这种材料本身属于同一个玻璃词族。"},{"en":"Fixed phrases place it: a stained glass window, medieval stained glass, stained glass panels.","cn":"固定搭配标出它的位置：彩色玻璃窗、中世纪彩色玻璃、彩色玻璃嵌板。"},{"en":"The phrase functioned as both material and object long before museums made it a category.","cn":"在博物馆把它变成藏品类别之前很久，这个短语就既指材料也指物件。"}],"abstract":[{"en":"Picture a dark room where one window turns sunlight into a coloured story.","cn":"想象一间暗屋，只有一扇窗把阳光变成彩色的故事。"},{"en":"Picture a jigsaw puzzle that is already assembled inside a frame and lit from behind.","cn":"想象一幅拼图已经装进框里，并从背后被照亮。"},{"en":"Picture a material that looks dull grey until light passes through it.","cn":"想象一种材料，光穿过之前看起来只是暗淡的灰色。"}]},"examples":[{"en":"The cathedral's stained glass was removed and stored during the war.","cn":"战争期间大教堂的彩色玻璃被取下存放。"},{"en":"She repairs stained glass with lead strips and old fragments.","cn":"她用铅条与旧碎片修复彩色玻璃。"},{"en":"The pub door held a small stained glass panel of a ship.","cn":"酒馆门上嵌着一小块画着船的彩色玻璃。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「染色 + 玻璃」—— 把颜色固定进玻璃里 → 彩色玻璃","word":"stained glass"},"root":"stain 经古法语 teindre 上溯至拉丁 tingere「浸泡、染色」；glass 来自古英语 glæs，属日耳曼语，更深来源不确定。名称中的「染色」原指十四世纪涂在玻璃表面的银染。","sensesIntro":{"en":"Eight senses follow one material through its uses: coloured glass itself, the craft, the window, the sacred artwork, the surviving fragments, the lamp shade, the modern panel, and finally the museum relic.","cn":"八个义项让同一种材料穿过不同用途：彩色玻璃本身、制作工艺、窗户、宗教艺术品、留存碎片、灯罩、现代嵌板，最后是博物馆里的遗物。"},"semanticMap":{"core":{"en":"CORE IMAGE: lead lines dividing a sheet of coloured glass while daylight turns it into a picture.","cn":"核心意象：铅条把一片彩色玻璃分成小格，日光使它成为一幅画。"},"chain":["COLOURED MATERIAL","CUT AND LEAD","WINDOW","LIGHT STORY","MOVABLE RELIC","RESTORED PANEL"],"branches":[{"senses":"01","en":"THE MATERIAL: the phrase begins with glass that has been coloured on purpose.","cn":"材料：这个短语从有意着色的玻璃开始。"},{"senses":"02 · 05","en":"WORKING THE PIECES: the craft cuts and joins them, and the fragments survive after the window breaks.","cn":"加工小片：工艺负责切割与连接，窗破碎之后碎片仍然留存。"},{"senses":"03 · 08","en":"THE OBJECT: a window is the assembled material, and a relic is that material after its building is gone.","cn":"物件：窗是拼装好的材料，遗物则是建筑消失后留下的同一材料。"},{"senses":"04","en":"SACRED PICTURE: in a church the window becomes a story carried by light.","cn":"神圣画面：在教堂里，窗成为由光承载的故事。"},{"senses":"06 · 07","en":"BEYOND THE CHURCH: lamps and modern panels move the same coloured glass into homes and lobbies.","cn":"走出教堂：灯罩与现代嵌板把同样的彩色玻璃带进住宅与大堂。"}]},"affixes":{"intro":{"en":"The phrase is half Romance and half Germanic: a dyeing verb of Latin descent joined to a native word for glass.","cn":"这个短语一半属罗曼语系、一半属日耳曼语系：一个源自拉丁的染色动词，接上一个本族的玻璃词。"},"latinIntro":{"en":"Latin tingere 'to dye' gives stain and the whole tinct- family; the glass half has no Latin source, and the Latin word for glass, vitrum, is a different root.","cn":"拉丁 tingere「染色」给出 stain 与整个 tinct- 词族；玻璃那一半没有拉丁来源，拉丁语中表示玻璃的 vitrum 属于另一个词根。"},"items":[{"word":"tingere","structure":"tingere, tinxi, tinctum (Latin verb, third conjugation)","meaning":"to wet, soak, dye","meaningCN":"弄湿；浸泡；染色","example":"The Latin verb describes colour entering a material.","exampleCN":"这个拉丁动词描述颜色进入材料的过程。"},{"word":"stain","structure":"Old French teindre, from Latin tingere","meaning":"to dye; to mark a surface","meaningCN":"染色；在表面留下痕迹","example":"The glazier stained the border yellow.","exampleCN":"玻璃匠把边框染成黄色。"},{"word":"-ed","structure":"-ed (past participle suffix)","meaning":"having been acted on","meaningCN":"已经受到该动作的","example":"Stained means colour has been fixed in.","exampleCN":"stained 表示颜色已被固定进去。"},{"word":"glass","structure":"Old English glæs, Germanic *glasam","meaning":"the hard transparent material","meaningCN":"坚硬透明的玻璃材料","example":"Glass lets light through.","exampleCN":"玻璃让光穿过。"},{"word":"glaze","structure":"glass + -e (verb from the noun)","meaning":"to fit with glass; to give a glossy coat","meaningCN":"装上玻璃；上釉","example":"Workers glazed the new windows.","exampleCN":"工人给新窗装上了玻璃。"},{"word":"glazier","structure":"glass + -ier (person who works with)","meaning":"a person who cuts and fits glass","meaningCN":"玻璃匠；装玻璃的人","example":"The glazier measured each pane.","exampleCN":"玻璃匠量了每一块窗格。"},{"word":"glazing","structure":"glass + -ing (action or material)","meaning":"the act of fitting glass; glasswork","meaningCN":"装玻璃；玻璃工作","example":"The glazing dates from the fifteenth century.","exampleCN":"这批玻璃窗饰可追溯到十五世纪。"},{"word":"stained glass","structure":"stained + glass","meaning":"coloured window glass","meaningCN":"彩色玻璃","example":"The chapel is known for its stained glass.","exampleCN":"这座小礼拜堂以彩色玻璃闻名。"},{"word":"stained-glass window","structure":"stained glass + window","meaning":"a window made of coloured glass","meaningCN":"彩色玻璃窗","example":"The east window is stained glass.","exampleCN":"东窗是彩色玻璃窗。"},{"word":"stained-glass artist","structure":"stained glass + artist","meaning":"a person who designs coloured windows","meaningCN":"彩色玻璃艺术家","example":"The stained-glass artist sketched the design.","exampleCN":"彩色玻璃艺术家画出了草图。"}],"latinEntries":[{"word":"tingere","structure":"tingere, tinxi, tinctum (verb, third conjugation)","meaning":"to wet, dye, colour","meaningCN":"弄湿；染色；着色"},{"word":"tinctura","structure":"tinctura, tincturae (f., first declension)","meaning":"a dyeing; a dye","meaningCN":"染色；染料"},{"word":"tinctus","structure":"tinctus, tinctus (m., fourth declension)","meaning":"a dyeing; colour","meaningCN":"染色；颜色"}]}},{"word":"tapestry","ipa_uk":"/ˈtæpəstri/","ipa_us":"/ˈtæpəstri/","definition_zh":"挂毯；织锦画；丰富交织的整体","definition_en":"a heavy woven cloth with a picture or pattern, hung on a wall","core_image":"一幅巨大的编织画从墙上垂下，经纬线里藏着战争、狩猎与四季","scene":"修道院墙上垂下一幅巨幅挂毯，用经纬线讲出家族的往事。A huge tapestry covered the abbey wall, telling the family's history in thread.","sceneCN":"这里指「织有图案的大型悬挂织物」（第 1 个义项：作为壁挂的织锦画）；句意为修道院墙上垂下一幅巨幅挂毯，用经纬线讲述家族往事。可辨识物件：墙面、垂下的织毯、狩猎图案、织线。","pos":[{"tag":"n.","zh":"挂毯；织锦画"},{"tag":"n.","zh":"（比喻）丰富交织的整体；错综复杂的组合"}],"collocations":[{"phrase":"a wall tapestry","zh":"壁挂织毯"},{"phrase":"a tapestry depicting a hunt","zh":"描绘狩猎场景的挂毯"},{"phrase":"the Bayeux Tapestry","zh":"贝叶挂毯"},{"phrase":"a rich tapestry of cultures","zh":"丰富多彩的文化交织"},{"phrase":"weave a tapestry","zh":"编织挂毯"},{"phrase":"a tapestry hanging","zh":"悬挂的织毯"}],"forms":[{"label":"单数形式","form":"tapestry"},{"label":"复数形式","form":"tapestries"},{"label":"所有格","form":"tapestry's"},{"label":"形容词形式","form":"tapestried"}],"derivatives":[{"word":"tapestried","pos":"adj.","zh":"用挂毯装饰的；织有图案的（由基础词加表示「覆有……」的后缀构成，语义偏移为状态）"},{"word":"tapestry-maker","pos":"n.","zh":"挂毯织造者（由基础词与表示「制作者」的词复合，语义收窄为职业）"},{"word":"tapestry-like","pos":"adj.","zh":"类似挂毯的；织纹丰富的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"}],"senses":[{"no":"01","title":"Woven pictorial hanging","titleCN":"织有图案的大型悬挂织物","definition":"a heavy hand-woven cloth with a pictorial design, usually hung on a wall","definitionCN":"手工织成、带图案的厚重织物，通常挂在墙上","example":"A huge tapestry covered the abbey wall.","exampleCN":"修道院墙上垂下一幅巨幅挂毯。","why":"The word first names the object. It is woven rather than painted, so the picture is built into the cloth thread by thread.","whyCN":"这个词首先指物件。它是织出来的，而不是画上去的，所以画面是一根线一根线织进布里的。"},{"no":"02","title":"The weaving craft","titleCN":"挂毯织造工艺","definition":"the craft or industry of weaving pictorial hangings on a loom","definitionCN":"在织机上织造图画挂毯的手艺或行业","example":"The town lived by tapestry for three centuries.","exampleCN":"这座小镇靠挂毯织造业生活了三百年。","why":"A tapestry takes months at a loom, so the making became a named trade with its own workshops and masters.","whyCN":"一幅挂毯要在织机上耗费数月，制作因此成为有作坊、有师傅的专门行业。"},{"no":"03","title":"A decorative wall hanging","titleCN":"作为室内装饰的壁挂","definition":"a large decorative cloth hung on a wall to furnish or warm a room","definitionCN":"挂在墙上用于布置或保暖的大幅装饰织物","example":"The hall was warmed by heavy tapestries.","exampleCN":"大厅靠厚重的挂毯保暖。","why":"Before wallpaper, a woven hanging covered a cold stone wall. The object was furniture as much as picture.","whyCN":"在壁纸出现之前，编织悬挂物用来覆盖冰冷的石墙。它既是画，也是家具。"},{"no":"04","title":"Needlework on canvas","titleCN":"在帆布上做的绒线绣","definition":"a piece of needlework worked on canvas in coloured wools, also called tapestry work","definitionCN":"用彩色毛线在帆布上绣成的作品，也称绒线绣","example":"She finished the tapestry with a fine needle.","exampleCN":"她用细针完成了这幅绒线绣。","why":"Handwork that covers a whole canvas with stitches came to share the name, because it too builds a picture from many separate threads.","whyCN":"把整块帆布用针脚盖满的手工也共享了这个名称，因为它同样用许多分离的线构成画面。"},{"no":"05","title":"A woven historical record","titleCN":"以织物形式留存的历史叙述","definition":"a hanging that records events, genealogies or legends as a visual chronicle","definitionCN":"以图像编年方式记录事件、世系或传说的悬挂织物","example":"The tapestry records the duke's voyage in seventy scenes.","exampleCN":"这幅挂毯用七十个场景记录了公爵的航行。","why":"A hanging can be read across a room. When few people could read text, a woven sequence of scenes served as a public record.","whyCN":"挂在墙上的织物可以横跨整间屋子被阅读。在识字者不多的年代，连续的编织场景就是公共记录。"},{"no":"06","title":"A complex interwoven whole","titleCN":"错综交织的整体","definition":"a whole made of many interwoven parts, such as peoples, stories or events","definitionCN":"由许多相互交织的部分构成的整体，如族群、故事或事件","example":"The district is a tapestry of old trades and new arrivals.","exampleCN":"这个街区是旧行业与新来者的交织体。","why":"The visual structure becomes a metaphor: separate threads cross without replacing one another, and the pattern exists only because they do.","whyCN":"视觉结构成为隐喻：不同的线交错而过，彼此不替换对方，图案正因为它们交错才存在。"},{"no":"07","title":"Rich variety of life","titleCN":"人生或历史的丰富多样","definition":"the varied, colourful complexity of a life, a culture or a period","definitionCN":"一段人生、一种文化或一个时期的多样而丰富的复杂性","example":"The memoir covers a rich tapestry of village life.","exampleCN":"这本回忆录写尽了乡村生活的丰富交织。","why":"The phrase 'a rich tapestry' generalizes the hanging into any dense mixture that rewards close reading.","whyCN":"「丰富的织锦」这一说法把挂毯一般化，指任何值得细看的密集混合。"},{"no":"08","title":"An interwoven abstract pattern","titleCN":"抽象的交织图案","definition":"a pattern or structure in which many strands cross and hold together","definitionCN":"许多线索交错并彼此维系而成的图案或结构","example":"The novel's plot is a tapestry of parallel lives.","exampleCN":"这部小说的情节是平行人生的交织图案。","why":"The most abstract sense keeps only the geometry: crossing strands that make a surface without any picture at all.","whyCN":"最抽象的义项只保留几何关系：交错的线构成一个表面，却完全不需要画面。"}],"etymology":{"intro":{"en":"Tapestry came through Old French from a word for carpet. The same Greek noun that gave Latin its word for a rug also gave French its word for a hanging. Dates are approximate.","cn":"tapestry 经古法语来自一个表示「地毯」的词。给拉丁语提供「毯子」说法的同一个希腊名词，也为法语提供了「悬挂织物」的说法。年代均为约数。"},"items":[{"era":"GREEK TAPES","en":"Greek tapēs (genitive tapētos) meant 'carpet, heavy cloth'. Its origin is source uncertain and it is generally believed to be a loanword from an Anatolian language rather than an inherited Greek word.","cn":"希腊 tapēs（属格 tapētos）意为「地毯、厚重织物」。其来源属「来源不确定」，一般认为它是来自安纳托利亚某语言的借词，而非希腊语固有词。"},{"era":"LATIN TAPETE","en":"Latin tapete and tapetum, both 'carpet or coverlet', were borrowings of the Greek noun; Latin did not inherit the word.","cn":"拉丁 tapete 与 tapetum 都意为「地毯、床罩」，是那个希腊名词的借词；拉丁语并未继承这个词。"},{"era":"OLD FRENCH TAPIS","en":"Old French tapis 'carpet' came from the Latin form. Its derived tapisserie first meant a workshop of hangings and then the hangings themselves.","cn":"古法语 tapis「地毯」来自拉丁形式。由它派生的 tapisserie 先指制作悬挂物的作坊，再指悬挂物本身。"},{"era":"ENGLISH TAPESTRY","en":"English borrowed tapestry in the fifteenth century for a pictorial wall hanging, at a time when such hangings were among the most valuable objects a household owned.","cn":"英语在十五世纪借入 tapestry，指带图案的壁挂；当时这类悬挂物是家庭最贵重的财产之一。"},{"era":"FIGURATIVE USE","en":"By the nineteenth century writers used the word for any rich interweaving of events or cultures, and the metaphor remains the most common use outside museums.","cn":"到十九世纪，作家用它指事件或文化的丰富交织；在博物馆之外，这一比喻义如今是最常见的用法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Greek origin of tapēs is unresolved, and any older form proposed for it is a reconstructed form rather than a recorded word.","cn":"来源不确定：tapēs 在希腊语之前的来源没有定论，凡为其提出的更早形式都属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms built on the same word that name related things; group two holds other words for large decorative hangings.","cn":"第一组是由同一个词构成、指相关事物的形式；第二组是其他表示大型装饰悬挂物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tapestried","ipa":"/ˈtæpəstrid/","tag":"adjective, not noun","definition":"covered with or shown in tapestry; it describes a surface, while tapestry names the object.","definitionCN":"覆有挂毯的；以挂毯表现的。它描述表面，而 tapestry 指物件。"},{"word":"tapestry needle","ipa":"/ˈtæpəstri ˈniːdl/","tag":"a tool","definition":"a large blunt needle used in wool needlework; the compound names a tool, not a hanging.","definitionCN":"绒线绣用的大号钝针；这个复合词指工具，而非悬挂织物。"},{"word":"tapestry weave","ipa":"/ˈtæpəstri wiːv/","tag":"a structure","definition":"a weaving structure in which the coloured threads form the pattern itself; it names a technique, not a finished hanging.","definitionCN":"彩色线本身构成图案的织造结构；它指技法，而非成品挂毯。"},{"word":"tapestry crochet","ipa":"/ˈtæpəstri ˈkrəʊʃeɪ/","tag":"a craft method","definition":"a crochet technique that carries one colour while working another; the compound names a method rather than a wall hanging.","definitionCN":"一种一边带线一边换色的钩织技法；这个复合词指方法，而非壁挂。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arras","ipa":"/ˈærəs/","tag":"historical synonym","definition":"a tapestry, especially one from the town of Arras; the word comes from the place name, not from the tapestry root.","definitionCN":"挂毯，尤指阿拉斯城出产的；这个词来自地名，而非挂毯词根。"},{"word":"wall hanging","ipa":"/wɔːl ˈhæŋɪŋ/","tag":"general term","definition":"any decorative cloth hung on a wall; it says nothing about weaving or a pictorial design.","definitionCN":"挂在墙上的任何装饰织物；不涉及织造或图案。"},{"word":"embroidery","ipa":"/ɪmˈbrɔɪdəri/","tag":"stitched decoration","definition":"decoration stitched onto existing cloth; a tapestry is woven as a whole, while embroidery is added to a surface.","definitionCN":"缝在既有布料上的装饰；挂毯整体织成，刺绣则加在表面上。"},{"word":"carpet","ipa":"/ˈkɑːpɪt/","tag":"historical relative","definition":"a floor covering; the French ancestor of tapestry meant carpet, and the two words separated when hangings moved from floor to wall.","definitionCN":"地面覆盖物；挂毯的法语祖词本指地毯，当悬挂物从地面移到墙上，两词才分开。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The French ancestor meant carpet, which explains why a hanging and a floor covering once shared a name.","cn":"法语祖词本指地毯，这解释了为什么壁挂与地面覆盖物曾共用一个名称。"},{"en":"The Greek noun behind it is generally believed to be a borrowed word, not an inherited one.","cn":"它背后的希腊名词一般认为是个借词，而非继承词。"},{"en":"Fixed phrases show both object and metaphor: a wall tapestry, a rich tapestry of cultures.","cn":"固定搭配同时展示实物与比喻：壁挂织毯、丰富的文化交织。"},{"en":"A tapestry is woven, not painted, so the picture lives in the threads.","cn":"挂毯是织出来的，不是画出来的，所以画面活在经纬线里。"},{"en":"The historical hanging was read like a chronicle across a room.","cn":"历史上的挂毯可以横跨整间屋子当作编年史来读。"}],"abstract":[{"en":"Picture many coloured threads crossing without ever replacing one another.","cn":"想象许多彩色线交错而过，却从不替换对方。"},{"en":"Picture a family story that can only be told by weaving several lives together.","cn":"想象一个只能把几段人生织在一起才讲得完的家族故事。"},{"en":"Picture a wall that speaks only when you step back far enough to see the whole pattern.","cn":"想象一面墙，只有退得足够远、看见整幅图案时才会说话。"}]},"examples":[{"en":"The tapestry took four weavers almost a year to finish.","cn":"这幅挂毯用了四名织工将近一年才完成。"},{"en":"Visitors read the battle across the tapestry from left to right.","cn":"参观者从左到右读着挂毯上的战役。"},{"en":"The memoir is a tapestry of farm work, gossip and grief.","cn":"这本回忆录是农活、闲话与悲伤的交织。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「毯铺斯特里」—— 毯子铺在墙上，织出一整幅画 → 挂毯","word":"tapestry"},"root":"经古法语 tapisserie、tapis「地毯」上溯至拉丁 tapete、tapetum，再上溯至希腊 tapēs「地毯、厚织物」；希腊词一般认为借自安纳托利亚语言，更早来源不确定。","sensesIntro":{"en":"Eight senses follow one woven surface: a pictorial hanging, the craft that makes it, the wall object, the needlework cousin, the historical chronicle, and then three metaphors built on crossing threads.","cn":"八个义项围绕同一块编织表面展开：带图案的挂毯、制作它的工艺、墙上的物件、绒线绣近亲、历史编年，最后是三个由交错经纬线构成的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long woven panel on a wall, its threads crossing to hold a story.","cn":"核心意象：墙上的一长幅编织物，经纬线交错，托住一个故事。"},"chain":["WOVEN CLOTH","PICTURE IN THREAD","WALL HANGING","CHRONICLE","CROSSED STRANDS","FIGURED MIXTURE"],"branches":[{"senses":"01","en":"THE OBJECT: the word begins with heavy cloth carrying a woven picture.","cn":"物件：这个词从织有图案的厚重布料开始。"},{"senses":"02 · 04","en":"MAKING IT: loom weaving and canvas needlework are two ways of building a picture from threads.","cn":"制作：织机织造与帆布刺绣，都是用线构成画面的两种方式。"},{"senses":"03","en":"IN THE ROOM: hung on a wall, the cloth becomes furniture and warmth.","cn":"在房间里：挂到墙上，这块布就成了家具与温暖。"},{"senses":"05","en":"AS RECORD: a sequence of scenes turns the hanging into a public chronicle.","cn":"作为记录：连续的场景把这幅悬挂物变成公共编年史。"},{"senses":"06 · 07 · 08","en":"THREE METAPHORS: a mixed society, a rich life and an abstract pattern all keep the image of crossing threads.","cn":"三个比喻：混合社会、丰富人生与抽象图案，都保留交错经纬线的意象。"}]},"affixes":{"intro":{"en":"Tapestry is a French noun formed with a suffix of trade and place, built on a word for carpet that entered Europe from Greek.","cn":"tapestry 是一个法语名词，由表示行业与场所的后缀构成，其词干来自一个从希腊语进入欧洲的「地毯」词。"},"latinIntro":{"en":"Latin tapete and tapetum are themselves borrowings of Greek tapēs, so the Latin forms record the word's passage rather than its invention.","cn":"拉丁 tapete 与 tapetum 本身就是希腊 tapēs 的借词，因此这些拉丁形式记录的是这个词的传递，而不是它的创造。"},"items":[{"word":"tapēs","structure":"tapēs, tapētos (Greek noun, third declension)","meaning":"carpet, heavy cloth","meaningCN":"地毯；厚重织物","example":"Greek tapēs is generally believed to be a loanword.","exampleCN":"希腊 tapēs 一般认为是个借词。"},{"word":"tapete","structure":"tapete, tapetis (Latin noun, third declension)","meaning":"carpet, coverlet","meaningCN":"地毯；床罩","example":"Latin borrowed the Greek noun as tapete.","exampleCN":"拉丁语把希腊名词借作 tapete。"},{"word":"tapis","structure":"Old French tapis, from Latin tapete","meaning":"carpet, hanging","meaningCN":"地毯；悬挂织物","example":"French tapis kept the carpet sense.","exampleCN":"法语 tapis 保留了地毯义。"},{"word":"-erie","structure":"-erie (Old French suffix of place or trade)","meaning":"a workshop or a collective product","meaningCN":"作坊；成类的产物","example":"Tapisserie first meant a hanging workshop.","exampleCN":"tapisserie 最初指制作悬挂物的作坊。"},{"word":"tapestry","structure":"Old French tapisserie","meaning":"a pictorial wall hanging","meaningCN":"带图案的壁挂","example":"The tapestry shows a hunting scene.","exampleCN":"这幅挂毯表现狩猎场景。"},{"word":"tapestried","structure":"tapestry + -ed (covered with)","meaning":"hung with or shown in tapestry","meaningCN":"用挂毯装饰的；织成图案的","example":"The chamber was tapestried with hunting scenes.","exampleCN":"这间厅堂挂满狩猎图案的织毯。"},{"word":"tapestry-maker","structure":"tapestry + maker","meaning":"a person who weaves tapestries","meaningCN":"挂毯织造者","example":"The tapestry-maker dyed his own wool.","exampleCN":"织毯人自己染羊毛。"},{"word":"tapestry-like","structure":"tapestry + -like (resembling)","meaning":"resembling a tapestry","meaningCN":"像挂毯的","example":"The field is tapestry-like from the air.","exampleCN":"从空中看，田野像一幅挂毯。"},{"word":"tapestry needle","structure":"tapestry + needle","meaning":"a large needle for wool needlework","meaningCN":"绒线绣用的大号针","example":"Use a tapestry needle for the thick wool.","exampleCN":"织厚羊毛要用大号绒线针。"}],"latinEntries":[{"word":"tapete","structure":"tapete, tapetis (n., third declension)","meaning":"carpet, coverlet","meaningCN":"地毯；床罩"},{"word":"tapetum","structure":"tapetum, tapeti (n., second declension)","meaning":"carpet, hanging","meaningCN":"地毯；悬挂织物"}]}},{"word":"textile","ipa_uk":"/ˈtekstaɪl/","ipa_us":"/ˈtekstaɪl/","definition_zh":"纺织品；织物；纺织原料；纺织的","definition_en":"cloth made by weaving or knitting, or the material from which such cloth is made","core_image":"无数细线在织机上纵横交错，最后压成一整匹平整的布","scene":"工厂把成卷的棉纱送进织机，出来时已是一整匹布。The mill fed rolls of cotton yarn into the loom, and a bolt of textile came out.","sceneCN":"这里指「织成的布匹」（第 1 个义项：纺织成品）；句意为工厂把成卷的棉纱送进织机，出来时已是一整匹纺织品。可辨识物件：棉纱卷、织机、布匹、传送带。","pos":[{"tag":"n.","zh":"纺织品；织物；纺织原料"},{"tag":"adj.","zh":"纺织的；织物的"}],"collocations":[{"phrase":"the textile industry","zh":"纺织工业"},{"phrase":"textile production","zh":"纺织品生产"},{"phrase":"a textile mill","zh":"纺织厂"},{"phrase":"textile fibers","zh":"纺织纤维"},{"phrase":"home textiles","zh":"家用纺织品"},{"phrase":"technical textiles","zh":"技术纺织品"}],"forms":[{"label":"单数形式","form":"textile"},{"label":"复数形式","form":"textiles"},{"label":"所有格","form":"textile's"},{"label":"形容词形式（同形）","form":"textile"}],"derivatives":[{"word":"textiles","pos":"n.","zh":"纺织产品；纺织业（由基础词加表示复数的后缀构成，语义偏移为商品类别与行业）"},{"word":"textile designer","pos":"n.","zh":"纺织品设计师（由基础词与表示「设计师」的词复合，语义收窄为职业）"},{"word":"textile-based","pos":"adj.","zh":"以纺织材料为基础的（由基础词与表示「以……为基础」的词复合，语义偏移为材料属性）"},{"word":"textile-like","pos":"adj.","zh":"类似纺织品的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"}],"senses":[{"no":"01","title":"Woven cloth","titleCN":"织成的布匹","definition":"cloth produced by weaving, knitting or another fabric-making process","definitionCN":"通过机织、针织或其他制布工艺生产出来的布","example":"A bolt of textile came out of the loom.","exampleCN":"一整匹布从织机里出来。","why":"The word comes from a Latin verb meaning 'to weave'. A textile is literally a woven thing, so the sense begins with the finished cloth.","whyCN":"这个词来自一个意为「编织」的拉丁动词。纺织品字面上就是「被织成的东西」，因此词义从成品布开始。"},{"no":"02","title":"The textile industry","titleCN":"纺织工业与纺织业","definition":"the industry that makes cloth, usually referred to in the plural","definitionCN":"制造布料的工业，通常用复数形式指整个行业","example":"The town's textiles employed half its workers.","exampleCN":"这座镇的纺织业雇用了半数工人。","why":"An industry named after its product uses the plural to mean the sector as a whole, not a pile of individual cloths.","whyCN":"以产品命名的行业用复数指整个部门，而不是指一堆具体的布。"},{"no":"03","title":"Fibre material for cloth","titleCN":"用于织布的纤维原料","definition":"the fibre, yarn or filament from which cloth is made","definitionCN":"用来制作布料的纤维、纱线或长丝","example":"The lab tests textile before it reaches the loom.","exampleCN":"实验室在原料上织机之前先做检测。","why":"Because the finished cloth and its material are stages of one process, the same noun serves for both, distinguished by context.","whyCN":"成品布与原料是同一过程的不同阶段，因此同一个名词兼指两者，靠语境区分。"},{"no":"04","title":"Relating to cloth","titleCN":"形容词义：与织物有关的","definition":"used before a noun to mean 'of cloth, weaving or the cloth trade'","definitionCN":"用在名词前，表示「织物的、织造的或纺织业的」","example":"Textile exports rose for the third year.","exampleCN":"纺织品出口连续第三年增长。","why":"As an adjective the word simply labels a field, so textile exports or textile design means the cloth sector rather than a particular cloth.","whyCN":"作形容词时，这个词只是给一个领域贴标签，因此纺织品出口或纺织品设计指的是布料行业，而非某一块布。"},{"no":"05","title":"Industrial and technical fabrics","titleCN":"工业与技术用织物","definition":"engineered fabrics made for strength, filtration, protection or other technical uses","definitionCN":"为强度、过滤、防护等技术用途而设计的织物","example":"The car uses technical textile in its seats.","exampleCN":"这辆车的座椅用了技术纺织品。","why":"Modern fibres can be designed for a job rather than for appearance, so the word now covers fabrics that never reach a wardrobe.","whyCN":"现代纤维可以为功能而非外观来设计，因此这个词现在也涵盖根本不会进入衣柜的织物。"},{"no":"06","title":"Non-woven fabric","titleCN":"非织造布","definition":"fabric made by bonding or felting fibres rather than by weaving them","definitionCN":"通过黏合或毡合纤维、而非编织制成的布","example":"The mask is made of non-woven textile.","exampleCN":"这只口罩由非织造布制成。","why":"The category expanded past its own etymology: cloth can now be made without a loom, yet it still belongs to the textile family.","whyCN":"这个类别超出了自身的词源：如今不用织机也能制布，但它仍属于纺织品家族。"},{"no":"07","title":"Textile design as a field","titleCN":"纺织品设计这门学科","definition":"the discipline of designing patterns, structures and surfaces for cloth","definitionCN":"为布料设计图案、结构与表面的学科","example":"She studied textile at an art school.","exampleCN":"她在艺术学校学习纺织品设计。","why":"Once cloth became a designed surface, the noun named a course of study and a profession, not only a material.","whyCN":"当布料成为被设计的表面，这个名词就指一门课程与一种职业，而不只是材料。"},{"no":"08","title":"Household textile goods","titleCN":"家用纺织品","definition":"cloth goods sold for the home, such as bedding, towels and curtains, usually in the plural","definitionCN":"面向家庭销售的布制品，如床品、毛巾与窗帘，通常用复数","example":"The shop sells home textiles on the ground floor.","exampleCN":"这家店在一层卖家用纺织品。","why":"Retail groups cloth by where it is used. The plural marks a product category rather than any single woven piece.","whyCN":"零售业按使用场所给布料分类。复数标记的是一个商品类别，而不是某一件织物。"}],"etymology":{"intro":{"en":"Textile comes from a Latin adjective meaning 'woven', built on the verb texere 'to weave'. The same verb also gives text, texture, context and tissue. Dates are approximate.","cn":"textile 来自一个意为「织成的」的拉丁形容词，其动词是 texere「编织」。同一个动词还给出 text、texture、context 与 tissue。年代均为约数。"},"items":[{"era":"LATIN TEXERE","en":"Latin texere meant 'to weave, plait, construct'. A text was first something woven, and only later something written.","cn":"拉丁 texere 意为「编织、编结、构造」。最初 text 指织成的东西，后来才指写成的东西。"},{"era":"LATIN TEXTILIS","en":"The adjective textilis 'woven, able to be woven' produced the noun textilis in later usage, and English took the adjective directly.","cn":"形容词 textilis 意为「织成的、可织的」，在后来的用法中产生名词形式；英语直接借入了这个形容词。"},{"era":"FRENCH TEXTILE","en":"French textile mediated the word in the seventeenth century, when cloth manufacture was becoming an organised trade in Europe.","cn":"法语 textile 在十七世纪传递了这个词；当时布料制造在欧洲正变成有组织的行业。"},{"era":"INDUSTRIAL TERM","en":"With mechanised spinning and weaving, textile became the standard word for mill-made cloth and for the industry itself.","cn":"随着机械化纺纱与织造，textile 成为工厂制布以及整个行业的标准词。"},{"era":"MODERN MATERIALS","en":"Synthetic and non-woven fibres widened the word in the twentieth century, so it now covers fabrics that are not woven at all.","cn":"合成纤维与非织造纤维在二十世纪拓宽了这个词，因此它现在也涵盖根本不经编织的布。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the origin of texere before Latin is unsettled, and the Indo-European root often cited for it is a reconstructed form rather than a recorded word.","cn":"来源不确定：texere 在拉丁语之前的来源没有定论，常被引用的印欧词根属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds words from the same weaving root that now mean different things; group two holds everyday words for cloth.","cn":"第一组是同出「编织」词根、但现在意思不同的词；第二组是表示布料的日常词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"textual","ipa":"/ˈtekstjuəl/","tag":"of writing, not cloth","definition":"relating to a text or wording; it shares the weaving root but followed the written branch.","definitionCN":"与文本或措辞有关的；它共享编织词根，却走了「书写」这一支。"},{"word":"texture","ipa":"/ˈtekstjə/","tag":"surface feel","definition":"the feel or arrangement of a surface; it keeps the woven image as a quality rather than an object.","definitionCN":"表面的手感或结构；它把编织意象保留为一种性质，而非物件。"},{"word":"text","ipa":"/tekst/","tag":"written work","definition":"written or printed words; historically 'that which is woven', now entirely separated from cloth.","definitionCN":"书写或印刷的文字；历史上意为「织成之物」，如今已与布料完全分开。"},{"word":"context","ipa":"/kənˈtekst/","tag":"woven together","definition":"the words around a passage, literally 'woven together'; it belongs to the writing branch, not the cloth trade.","definitionCN":"一段文字周围的词语，字面义为「织在一起」；它属于书写分支，而非纺织行业。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fabric","ipa":"/ˈfæbrɪk/","tag":"made thing","definition":"cloth or any material made by joining parts; from Latin fabrica 'workshop', it stresses manufacture rather than weaving.","definitionCN":"布料或任何由部件构成的材料；来自拉丁 fabrica「作坊」，强调制造而非编织。"},{"word":"cloth","ipa":"/klɒθ/","tag":"everyday word","definition":"the common word for woven material; it is plainer and less industrial than textile.","definitionCN":"指织物的普通词；比 textile 更朴素，也更少工业色彩。"},{"word":"material","ipa":"/məˈtɪəriəl/","tag":"general term","definition":"any substance used to make something; it is broader than textile and says nothing about weaving.","definitionCN":"用来制作某物的任何物质；比 textile 宽泛，不涉及编织。"},{"word":"drapery","ipa":"/ˈdreɪpəri/","tag":"hanging cloth","definition":"cloth arranged in folds as curtains or hangings; it names a use of fabric rather than the fabric itself.","definitionCN":"以褶皱形式布置成窗帘或悬挂物的布；它指布料的用途，而非布料本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means 'to weave', so textile is literally 'the woven thing'.","cn":"词根意为「编织」，所以 textile 字面上就是「被织成的东西」。"},{"en":"Text, texture and context come from the same verb, which is why a text can be described as woven.","cn":"text、texture 与 context 都出自同一个动词，这也是为什么一篇文本可以被形容为「织成」的。"},{"en":"Fixed phrases mark the industry: textile industry, textile mill, textile production.","cn":"固定搭配标出行业：纺织工业、纺织厂、纺织品生产。"},{"en":"The plural textiles names goods and the sector, not several separate cloths.","cn":"复数形式指商品与行业部门，而不是几块分开的布。"},{"en":"Technical textile shows that modern fabrics may be engineered rather than woven.","cn":"技术纺织品说明现代织物可以是设计出来的，而不一定是织出来的。"}],"abstract":[{"en":"Picture thousands of threads that only become a surface when they cross.","cn":"想象成千上万根线，只有交错之后才成为一片表面。"},{"en":"Picture a word and a cloth made by the same gesture of binding strands.","cn":"想象一个词与一块布，由同一个「把线束在一起」的动作做成。"},{"en":"Picture a material that can be flat, stiff, soft or filtering without changing its name.","cn":"想象一种材料，可以是平的、硬的、软的或用于过滤，却不必改名。"}]},"examples":[{"en":"The museum displays textile from the eighteenth-century mill.","cn":"博物馆展出十八世纪工厂生产的纺织品。"},{"en":"Textile workers demanded cleaner air in the spinning rooms.","cn":"纺织工人要求在纺纱车间里呼吸更干净的空气。"},{"en":"The designers mixed textile with recycled plastic.","cn":"设计师把织物与再生塑料混用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「特克斯太尔」—— 把特别细密的线一根根织成整匹布 → 纺织品","word":"textile"},"root":"拉丁 textilis「织成的」，来自 texere「编织、编结」；同一动词还派生 text、texture、context、tissue。texere 在拉丁语之前的来源不确定，常见印欧词根属重构形式。","sensesIntro":{"en":"Eight senses follow one process: fibres are woven into cloth, cloth becomes an industry, a material, a field of design and a retail category, and finally a family of engineered fabrics that need no loom.","cn":"八个义项沿同一过程展开：纤维被织成布，布再成为行业、材料、设计领域与零售类别，最后成为一个无需织机的工程织物家族。"},"semanticMap":{"core":{"en":"CORE IMAGE: thousands of threads crossing on a loom until they hold together as one surface.","cn":"核心意象：成千上万根线在织机上交错，直到合成一整片表面。"},"chain":["FIBRE","YARN","WOVEN CLOTH","INDUSTRY","DESIGNED SURFACE","TECHNICAL FABRIC"],"branches":[{"senses":"01 · 03","en":"FROM FIBRE TO CLOTH: the material and the finished cloth are two ends of one process.","cn":"从纤维到布：原料与成品布是同一过程的两端。"},{"senses":"02 · 08","en":"GOODS AND SECTOR: the plural covers both mill products and the trade that makes them.","cn":"商品与行业：复数形式既涵盖工厂产品，也涵盖制造它们的行业。"},{"senses":"04","en":"AS A LABEL: the adjective marks anything belonging to cloth or the cloth trade.","cn":"作为标签：形容词标记任何属于布料或纺织业的事物。"},{"senses":"05 · 06","en":"BEYOND WEAVING: technical and non-woven fabrics keep the family name after leaving the loom.","cn":"超越编织：技术织物与非织造布在离开织机后仍保留这个家族名称。"},{"senses":"07","en":"AS DISCIPLINE: design turns cloth into a subject with patterns, structures and training.","cn":"作为学科：设计把布料变成一门有图案、结构与训练体系的科目。"}]},"affixes":{"intro":{"en":"Textile is one branch of a large Latin family built on weaving. The same root reaches writing, surface feel and the surrounding words of a passage.","cn":"textile 是以「编织」为核心的一大型拉丁词族中的一支。同一词根还通到书写、表面手感以及一段文字周围的词语。"},"latinIntro":{"en":"Latin texere gives textile, text, texture, context and tissue; the past participle textus is literally 'a woven thing'.","cn":"拉丁 texere 给出 textile、text、texture、context 与 tissue；过去分词 textus 字面义就是「织成之物」。"},"items":[{"word":"texere","structure":"texere, texui, textum (Latin verb, third conjugation)","meaning":"to weave, plait, construct","meaningCN":"编织；编结；构造","example":"The verb covers both cloth and language.","exampleCN":"这个动词既覆盖布料，也覆盖语言。"},{"word":"text-","structure":"text- (bound root from textus)","meaning":"woven thing; constructed thing","meaningCN":"织成之物；构造之物","example":"The root appears in both fabric and writing.","exampleCN":"这个词根同时出现在织物与书写中。"},{"word":"textilis","structure":"textilis, textile (Latin adjective, third declension)","meaning":"woven, able to be woven","meaningCN":"织成的；可织的","example":"The adjective became the English noun.","exampleCN":"这个形容词变成了英语名词。"},{"word":"textile","structure":"Latin textilis through French","meaning":"woven cloth","meaningCN":"织成的布","example":"Textile fills the mill's output.","exampleCN":"纺织品构成工厂的产出。"},{"word":"texture","structure":"textura 'a weaving', from texere","meaning":"the feel or arrangement of a surface","meaningCN":"表面的手感或结构","example":"The texture of the cloth is coarse.","exampleCN":"这块布的手感粗糙。"},{"word":"text","structure":"textus 'woven thing', from texere","meaning":"written or printed words","meaningCN":"书面或印刷文字","example":"The text runs to forty pages.","exampleCN":"正文长达四十页。"},{"word":"context","structure":"con- 'together' + texere","meaning":"the words woven around a passage","meaningCN":"环绕一段文字的上下文","example":"Read the sentence in context.","exampleCN":"把这个句子放在上下文中读。"},{"word":"tissue","structure":"Old French tissu, from texere","meaning":"a woven fabric; body tissue","meaningCN":"织物；生物组织","example":"The word first meant a ribbon of cloth.","exampleCN":"这个词最初指一条布带。"},{"word":"textiles","structure":"textile + -s (plural)","meaning":"cloth goods; the cloth trade","meaningCN":"纺织产品；纺织业","example":"Textiles dominate the region's exports.","exampleCN":"纺织品占该地区出口的主要部分。"},{"word":"textile designer","structure":"textile + designer","meaning":"a person who designs cloth patterns","meaningCN":"纺织品设计师","example":"The textile designer works with jacquard looms.","exampleCN":"这位纺织品设计师使用提花织机工作。"},{"word":"textile-like","structure":"textile + -like (resembling)","meaning":"resembling cloth","meaningCN":"像织物的","example":"The wall has a textile-like finish.","exampleCN":"这面墙有类似织物的饰面。"}],"latinEntries":[{"word":"texere","structure":"texere, texui, textum (verb, third conjugation)","meaning":"to weave, construct","meaningCN":"编织；构造"},{"word":"textilis","structure":"textilis, textile (adj., third declension)","meaning":"woven","meaningCN":"织成的"},{"word":"textura","structure":"textura, texturae (f., first declension)","meaning":"a weaving; texture","meaningCN":"编织；纹理"},{"word":"textus","structure":"textus, textus (m., fourth declension)","meaning":"a woven thing; a text","meaningCN":"织成之物；文本"}]}},{"word":"textile art","ipa_uk":"/ˈtekstaɪl ɑːt/","ipa_us":"/ˈtekstaɪl ɑːrt/","definition_zh":"纺织艺术；纤维艺术","definition_en":"art made from fibre, thread, cloth or other soft materials","core_image":"画廊里一幅由粗麻、棉线与羊毛缝成的立体作品，从墙面微微凸出","scene":"画廊把旧床单、羊毛与棉线缝成一幅悬挂作品。The gallery sewed old sheets, wool and cotton thread into a hanging work of textile art.","sceneCN":"这里指「以纤维与织物为材料的艺术门类」（第 1 个义项：纺织作为艺术创作）；句意为画廊把旧床单、羊毛与棉线缝成一件悬挂的纺织艺术作品。可辨识物件：旧床单、羊毛团、棉线、针、悬挂作品。","pos":[{"tag":"n.","zh":"纺织艺术（作为艺术门类）"},{"tag":"n.","zh":"纺织艺术作品（单件或集合）"}],"collocations":[{"phrase":"contemporary textile art","zh":"当代纺织艺术"},{"phrase":"a textile art exhibition","zh":"纺织艺术展"},{"phrase":"traditional textile art","zh":"传统纺织艺术"},{"phrase":"a textile art piece","zh":"一件纺织艺术作品"},{"phrase":"study textile art","zh":"学习纺织艺术"},{"phrase":"a textile art gallery","zh":"纺织艺术画廊"}],"forms":[{"label":"单数形式","form":"textile art"},{"label":"复数形式（指多个门类或作品）","form":"textile arts"},{"label":"所有格","form":"textile art's"},{"label":"定语用法","form":"textile-art"}],"derivatives":[{"word":"textile artist","pos":"n.","zh":"纺织艺术家（由本短语前半与表示「艺术家」的词复合，语义收窄为职业身份）"},{"word":"textile artwork","pos":"n.","zh":"纺织艺术作品（由本短语前半与表示「作品」的词复合，指具体成品）"},{"word":"textile arts","pos":"n.","zh":"纺织艺术门类（由本短语前半与表示「门类」的复数形式复合，指类别下的多种形式）"},{"word":"textile-art-based","pos":"adj.","zh":"以纺织艺术为基础的（由本短语与表示「以……为基础」的词复合，语义偏移为属性描述）"}],"senses":[{"no":"01","title":"Art made from fibre","titleCN":"以纤维为材料的艺术门类","definition":"art whose main material is fibre, thread, yarn or cloth rather than paint or stone","definitionCN":"以纤维、线、纱或布为主要材料、而非颜料或石头的艺术","example":"The gallery sewed old sheets and wool into textile art.","exampleCN":"画廊把旧床单与羊毛缝成纺织艺术。","why":"The phrase names a field by its material. Unlike painting, the work is built from soft, flexible strands that can be sewn, knotted or wrapped.","whyCN":"这个短语按材料命名一个领域。与绘画不同，作品由柔软可弯的线构成，可以缝、结或缠绕。"},{"no":"02","title":"Traditional domestic crafts","titleCN":"传统家庭手工艺","definition":"the older craft traditions of weaving, embroidery, quilting and lace that the art grew from","definitionCN":"纺织艺术所源自的织造、刺绣、绗缝与蕾丝等古老手工传统","example":"Textile art began in household weaving and embroidery.","exampleCN":"纺织艺术起源于家庭织造与刺绣。","why":"Every culture made cloth at home. When those skills moved from use to display, they became an art with a lineage.","whyCN":"每种文化都在家里制布。当这些技能从实用转向展示，它们就成了有谱系的技艺门类。"},{"no":"03","title":"Gallery fibre art","titleCN":"画廊中的纤维艺术","definition":"the movement from the 1960s that brought woven and fibre works into art galleries","definitionCN":"二十世纪六十年代起把编织与纤维作品带进美术馆的运动","example":"Textile art entered the gallery with large hanging pieces.","exampleCN":"纺织艺术以大型悬挂作品进入画廊。","why":"Artists pushed craft materials into the fine-art space, and critics needed a term that claimed gallery status without hiding the fibre.","whyCN":"艺术家把手工材料推进纯艺术空间，评论界需要一个既主张画廊地位、又不掩盖纤维材料的说法。"},{"no":"04","title":"Sculptural textile forms","titleCN":"立体的纺织造型","definition":"three-dimensional textile work built by stuffing, wrapping, hanging or stiffening cloth","definitionCN":"通过填充、缠绕、悬挂或硬化布料做成的三维纺织作品","example":"Her textile art hangs from the ceiling in loops.","exampleCN":"她的纺织艺术以环状从天花板垂下。","why":"Cloth can hold a shape once it is stuffed or sized, so the material leaves the wall and becomes sculpture.","whyCN":"布料一旦被填充或上浆就能保持形状，于是材料离开墙面，成为雕塑。"},{"no":"05","title":"Wearable textile art","titleCN":"可穿戴的纺织艺术","definition":"garments or body pieces made as artworks rather than as ordinary clothing","definitionCN":"作为艺术品而非日常服装制作的衣物或身体作品","example":"The show presented textile art worn by the models.","exampleCN":"这场秀让模特穿上了纺织艺术作品。","why":"Clothing is the body's nearest textile, so the art can move onto the body and be worn rather than viewed.","whyCN":"衣物是身体最近的织物，因此这门艺术可以移到身体上，被穿着而非被观看。"},{"no":"06","title":"Narrative and ceremonial cloth","titleCN":"叙事与礼仪织物","definition":"traditional cloth made to record events, mark rank or serve in ceremony","definitionCN":"为记录事件、标示身份或用于礼仪而制作的传统织物","example":"Textile art in the village records weddings and harvests.","exampleCN":"村里的纺织艺术记录婚礼与收成。","why":"Before writing was common, patterned cloth carried genealogy, status and ritual, so the art served memory as well as beauty.","whyCN":"在书写普及之前，带图案的布承载世系、身份与礼仪，因此这门艺术既服务美，也服务记忆。"},{"no":"07","title":"Installation and public space","titleCN":"装置与公共空间中的纺织艺术","definition":"large textile works installed in public buildings, streets or landscapes","definitionCN":"安装在公共建筑、街道或景观中的大型纺织作品","example":"Textile art wrapped the bridge for one summer.","exampleCN":"纺织艺术在一个夏天里包裹了那座桥。","why":"Because cloth is light and can be tied, wrapped and hung, it suits temporary works that change a whole place rather than one wall.","whyCN":"布料轻，可系、可裹、可挂，因此适合改变整个场所而非一面墙的临时作品。"},{"no":"08","title":"A taught studio discipline","titleCN":"可教授的工作室学科","definition":"textile art as a course of study with techniques, materials and critique","definitionCN":"作为一门有技法、材料与评论体系的学科来教授","example":"The school offers textile art as a three-year course.","exampleCN":"这所学校开设三年制的纺织艺术课程。","why":"Once the field had exhibitions and history, it needed teaching. The phrase then names a curriculum as well as a body of work.","whyCN":"这门领域有了展览与历史之后就需要教学。这个短语于是既指一批作品，也指一套课程。"}],"etymology":{"intro":{"en":"Textile art joins the Latin word for woven cloth with the Latin word for skill. Both halves are old borrowings, and the compound is modern. Dates are approximate.","cn":"textile art 把拉丁语中表示「织成的布」的词与表示「技艺」的词并在一起。两半都是古老借词，组合却是现代的。年代均为约数。"},"items":[{"era":"LATIN TEXERE","en":"Latin texere 'to weave' gave textilis 'woven'. The verb treats cloth and language as the same act of binding strands.","cn":"拉丁 texere「编织」给出 textilis「织成的」。这个动词把布料与语言都看作同一种「把线束在一起」的动作。"},{"era":"LATIN ARS","en":"Latin ars (genitive artis) meant 'skill, craft'. Its deeper origin is source uncertain, and the root sometimes proposed for it is a reconstructed form.","cn":"拉丁 ars（属格 artis）意为「技艺、手艺」。其更深来源属「来源不确定」，常为其提出的词根只是重构形式。"},{"era":"OLD FRENCH","en":"Old French carried both art and textile into English, where art long meant learned skill before it narrowed to the fine arts.","cn":"古法语把 art 与 textile 都带进英语；art 长期指习得的技艺，后来才收窄到美术。"},{"era":"CRAFT REVIVAL","en":"The nineteenth-century craft revival began to treat weaving and embroidery as art rather than mere household work.","cn":"十九世纪的手工艺复兴开始把织造与刺绣当作艺术，而不只是家务劳动。"},{"era":"GALLERY TERM","en":"In the second half of the twentieth century textile art became a gallery and academic term, often overlapping with fibre art.","cn":"二十世纪下半叶，textile art 成为画廊与学术用语，常与纤维艺术一词重叠。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origins of both texere and ars are unresolved, so older forms offered for them are reconstructed forms rather than recorded words.","cn":"来源不确定：texere 与 ars 在拉丁语之前的来源都没有定论，因此为它们提出的更早形式属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds phrases built from the same words that name narrower things; group two holds names for neighbouring art practices.","cn":"第一组是由同样几个词构成、却指更窄事物的短语；第二组是相邻艺术实践的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"textile","ipa":"/ˈtekstaɪl/","tag":"material, not the art","definition":"cloth itself; the longer phrase names the art made from it.","definitionCN":"布料本身；较长的短语指用它创作的艺术。"},{"word":"textile design","ipa":"/ˈtekstaɪl dɪˈzaɪn/","tag":"commercial field","definition":"the design of patterns and structures for manufactured cloth; it serves industry rather than the gallery.","definitionCN":"为工业生产的布料设计图案与结构；它服务工业，而非画廊。"},{"word":"textile arts","ipa":"/ˈtekstaɪl ɑːts/","tag":"plural variant","definition":"the plural form names the branches or the school subject as a whole; it is not a different art form.","definitionCN":"复数形式指各个分支或整门学科；它不是另一种艺术形式。"},{"word":"textile artist","ipa":"/ˈtekstaɪl ˈɑːtɪst/","tag":"person, not the field","definition":"a person who makes work in this medium; the compound names the maker.","definitionCN":"用这种媒介创作的人；这个复合词指创作者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fibre art","ipa":"/ˈfaɪbə ɑːt/","tag":"parallel term","definition":"a term coined in the mid twentieth century for art made from fibre; it overlaps with textile art but stresses the material rather than the cloth.","definitionCN":"二十世纪中叶为纤维艺术创造的说法；与纺织艺术重叠，但强调材料而非布。"},{"word":"soft sculpture","ipa":"/sɒft ˈskʌlptʃə/","tag":"three-dimensional","definition":"sculpture made from soft materials such as cloth, foam or vinyl; it is one branch of textile art rather than its name.","definitionCN":"用布、海绵或乙烯基等软材料做的雕塑；它是纺织艺术的一支，而非其名称。"},{"word":"craft art","ipa":"/kræft ɑːt/","tag":"broader category","definition":"art made in craft media such as clay, glass, wood or fibre; it is wider than textile art.","definitionCN":"用陶、玻璃、木或纤维等手工材料创作的艺术；比纺织艺术更宽泛。"},{"word":"wearable art","ipa":"/ˈweərəbl ɑːt/","tag":"body-centred","definition":"art designed to be worn on the body; it can be made of textile but is defined by use, not material.","definitionCN":"设计来穿在身体上的艺术；可以用纺织材料制作，但按用途而非材料定义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The phrase is material plus skill: the art of the woven thing.","cn":"这个短语是材料加技艺：织成之物的艺术。"},{"en":"Textile goes back to the verb 'to weave', and art goes back to 'skill', so the two halves name exactly what the field is.","cn":"textile 上溯到「编织」动词，art 上溯到「技艺」，两半正好说出了这个领域的本质。"},{"en":"Fixed phrases mark its settings: contemporary, traditional, exhibition, gallery.","cn":"固定搭配标出它的场合：当代的、传统的、展览、画廊。"},{"en":"A textile artist is the maker; textile art is the field.","cn":"textile artist 指创作者；textile art 指领域。"},{"en":"The plural textile arts covers the branches taught under one heading.","cn":"复数形式涵盖同一名目下所教的各个分支。"}],"abstract":[{"en":"Picture a painting that can be folded, worn and walked through.","cn":"想象一幅可以折叠、穿在身上、也能走进去的画。"},{"en":"Picture a family quilt that is also a gallery piece.","cn":"想象一床家用被子同时是画廊作品。"},{"en":"Picture an art whose material was once everyone's daily labour.","cn":"想象一门艺术，它的材料曾是每个人的日常劳动。"}]},"examples":[{"en":"The biennial gives textile art a whole floor.","cn":"这届双年展给了纺织艺术整整一层。"},{"en":"Her textile art uses hospital sheets and red thread.","cn":"她的纺织艺术使用医院床单与红线。"},{"en":"Textile art students learn dyeing before construction.","cn":"纺织艺术学生先学染色，再学构造。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「纺织艺术」：把布料与线当作颜料和画笔 → 用纤维创作的艺术","word":"textile art"},"root":"由 textile 与 art 组合：textile 经法语上溯至拉丁 textilis「织成的」，源自 texere「编织」；art 经古法语上溯至拉丁 ars「技艺」。两者的更早来源均不确定。","sensesIntro":{"en":"Eight senses follow one material into art: fibre itself, the domestic crafts behind it, the gallery, sculpture, the worn body, ceremonial cloth, public installation and finally the classroom.","cn":"八个义项让同一种材料走进艺术：纤维本身、其后的家庭手艺、画廊、雕塑、被穿上的身体、礼仪织物、公共装置，最后是教室。"},"semanticMap":{"core":{"en":"CORE IMAGE: soft strands stitched and hung until they hold a shape in space.","cn":"核心意象：柔软的线被缝起、挂起，直到在空间中撑出一个形状。"},"chain":["FIBRE","HAND CRAFT","GALLERY WORK","THREE DIMENSIONS","PUBLIC SPACE","BODY AND SHELTER"],"branches":[{"senses":"01","en":"THE FIELD: the phrase first claims fibre as an art material.","cn":"领域：这个短语首先把纤维确立为艺术材料。"},{"senses":"02 · 06","en":"THE OLD CRAFTS: domestic weaving and ceremonial cloth are the tradition the art inherits.","cn":"古老手艺：家庭织造与礼仪织物是这门艺术继承的传统。"},{"senses":"03 · 08","en":"THE INSTITUTION: the gallery and the classroom turn the craft into a recognised discipline.","cn":"机构：画廊与教室把这门手艺变成被承认的学科。"},{"senses":"04 · 07","en":"IN SPACE: sculpture and installation take cloth off the wall and into three dimensions.","cn":"在空间中：雕塑与装置把布离开墙面，带进三维空间。"},{"senses":"05","en":"ON THE BODY: wearable work makes the viewer into the support.","cn":"在身体上：可穿戴作品让观者本人成为承托物。"}]},"affixes":{"intro":{"en":"The phrase joins a weaving root to a root for skill, and both sides bring large families of English words.","cn":"这个短语把「编织」词根接到「技艺」词根上，两边都为英语带来庞大的词族。"},"latinIntro":{"en":"Latin texere gives textile, texture, text and context; Latin ars gives art, artist, artistic and artisan.","cn":"拉丁 texere 给出 textile、texture、text 与 context；拉丁 ars 给出 art、artist、artistic 与 artisan。"},"items":[{"word":"texere","structure":"texere, texui, textum (Latin verb, third conjugation)","meaning":"to weave","meaningCN":"编织","example":"The verb binds strands into a surface.","exampleCN":"这个动词把线束成一片表面。"},{"word":"textilis","structure":"textilis, textile (Latin adjective)","meaning":"woven","meaningCN":"织成的","example":"Textilis is the source of textile.","exampleCN":"textilis 是 textile 的来源。"},{"word":"textile","structure":"textilis through French","meaning":"woven cloth","meaningCN":"织成的布","example":"Textile is the material of the art.","exampleCN":"纺织材料是这门艺术的媒介。"},{"word":"texture","structure":"textura, from texere","meaning":"surface feel","meaningCN":"表面手感","example":"Texture matters in textile art.","exampleCN":"在纺织艺术中，表面手感很重要。"},{"word":"ars","structure":"ars, artis (Latin noun, third declension)","meaning":"skill, craft","meaningCN":"技艺；手艺","example":"Ars names learned skill.","exampleCN":"ars 指习得的技艺。"},{"word":"art","structure":"Latin ars through Old French","meaning":"skill; the fine arts","meaningCN":"技艺；美术","example":"Textile art claims a place among the arts.","exampleCN":"纺织艺术在艺术之列争取一席之地。"},{"word":"artist","structure":"art + -ist (person who practises)","meaning":"a person who makes art","meaningCN":"艺术家","example":"The artist works in wool.","exampleCN":"这位艺术家用羊毛创作。"},{"word":"artistic","structure":"artist + -ic (relating to)","meaning":"relating to art","meaningCN":"艺术的","example":"The piece has artistic ambition.","exampleCN":"这件作品有艺术抱负。"},{"word":"textile art","structure":"textile + art","meaning":"art made from cloth and fibre","meaningCN":"用织物与纤维创作的艺术","example":"Textile art fills the upper gallery.","exampleCN":"纺织艺术占满上层画廊。"},{"word":"textile artist","structure":"textile + artist","meaning":"a person who makes textile art","meaningCN":"纺织艺术家","example":"The textile artist dyes her own thread.","exampleCN":"这位纺织艺术家自己染线。"}],"latinEntries":[{"word":"texere","structure":"texere, texui, textum (verb, third conjugation)","meaning":"to weave","meaningCN":"编织"},{"word":"textilis","structure":"textilis, textile (adj., third declension)","meaning":"woven","meaningCN":"织成的"},{"word":"ars","structure":"ars, artis (f., third declension)","meaning":"skill, craft","meaningCN":"技艺；手艺"}]}},{"word":"ceramic art","ipa_uk":"/səˈræmɪk ɑːt/","ipa_us":"/səˈræmɪk ɑːrt/","definition_zh":"陶瓷艺术；陶艺","definition_en":"art made from clay shaped by hand and hardened by fire","core_image":"转盘上的湿泥被手指慢慢拉高，变成一只薄壁碗，再进窑烧成硬器","scene":"工作室给拉好的泥坯上釉，排进窑里烧成一件作品。The studio glazed the shaped clay and fired it as a piece of ceramic art.","sceneCN":"这里指「以陶土烧制成艺术品的门类」（第 1 个义项：陶瓷作为艺术创作）；句意为工作室给泥坯上釉，烧成一件陶瓷艺术作品。可辨识物件：泥坯、转盘、釉桶、窑口。","pos":[{"tag":"n.","zh":"陶瓷艺术（作为门类）"},{"tag":"n.","zh":"陶瓷艺术作品（单件或集合）"}],"collocations":[{"phrase":"ancient ceramic art","zh":"古代陶瓷艺术"},{"phrase":"studio ceramic art","zh":"工作室陶艺"},{"phrase":"a ceramic art exhibition","zh":"陶瓷艺术展"},{"phrase":"glazed ceramic art","zh":"上釉的陶瓷艺术"},{"phrase":"a ceramic art class","zh":"陶艺课"},{"phrase":"architectural ceramic art","zh":"建筑陶瓷艺术"}],"forms":[{"label":"单数形式","form":"ceramic art"},{"label":"复数形式（指多个门类或作品）","form":"ceramic arts"},{"label":"所有格","form":"ceramic art's"},{"label":"定语用法","form":"ceramic-art"}],"derivatives":[{"word":"ceramicist","pos":"n.","zh":"陶瓷艺术家；陶艺师（由基础词加表示「从事者」的后缀构成，语义收窄为职业身份）"},{"word":"ceramics","pos":"n.","zh":"陶瓷制品；陶瓷工艺（由基础词加表示复数的后缀构成，语义偏移为类别与行业）"},{"word":"ceramic-like","pos":"adj.","zh":"类似陶瓷的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"},{"word":"ceramic artwork","pos":"n.","zh":"陶瓷艺术作品（由基础词与表示「作品」的词复合，指具体成品）"}],"senses":[{"no":"01","title":"Art made from fired clay","titleCN":"以陶土烧制的艺术","definition":"the art of shaping clay into objects and hardening them by firing","definitionCN":"把陶土塑成物件并以高温烧硬的艺术","example":"The studio fired the clay as a piece of ceramic art.","exampleCN":"工作室把泥坯烧成一件陶瓷艺术作品。","why":"The word names the field by its process. Clay is soft, fire makes it permanent, and that change from mud to stone is the art's core.","whyCN":"这个词按制作过程命名领域。泥柔软，火使其永久，从泥到石的转变正是这门艺术的核心。"},{"no":"02","title":"Vessels treated as art","titleCN":"把器皿当作艺术","definition":"pottery vessels whose form and surface are valued as artistic expression","definitionCN":"形制与表面被当作艺术表现的陶制器皿","example":"Ceramic art here means bowls, not only figures.","exampleCN":"这里的陶瓷艺术指碗盘，而不只是人像。","why":"The oldest ceramic objects were useful containers. A bowl becomes art when its shape and glaze are made to be looked at rather than merely used.","whyCN":"最古老的陶瓷物件是有用的容器。当碗的形状与釉色为了被观看而非仅被使用而做时，它就成了艺术。"},{"no":"03","title":"Ceramic sculpture","titleCN":"陶瓷雕塑","definition":"three-dimensional ceramic figures or forms made as sculpture rather than as vessels","definitionCN":"作为雕塑而非器皿制作的三维陶制形象或形体","example":"Her ceramic art is a row of seated figures.","exampleCN":"她的陶瓷艺术是一排坐着的形象。","why":"Clay can be modelled like any sculptural material, so the field includes solid figures that never hold anything.","whyCN":"陶土能像任何雕塑材料一样被塑形，因此这门领域也包含从不盛物的实心形象。"},{"no":"04","title":"Glaze as an artistic surface","titleCN":"釉作为艺术表面","definition":"the use of glaze colour, crackle and lustre as the main expressive surface of a ceramic work","definitionCN":"把釉色、开片与光泽当作陶瓷作品主要表现表面的做法","example":"The ceramic art depends on a copper-red glaze.","exampleCN":"这件陶瓷艺术靠铜红釉显出效果。","why":"Glaze is glass melted onto clay. It can be controlled but never fully, so its colour and crackle carry the maker's risk and skill.","whyCN":"釉是熔在陶土上的玻璃。它可以被控制，却永远不能完全控制，因此釉色与开片承载着制作者的风险与技艺。"},{"no":"05","title":"Ancient and archaeological ceramics","titleCN":"古代与考古陶瓷艺术","definition":"historic pottery studied and displayed as art and as evidence of past life","definitionCN":"作为艺术、也作为往昔生活证据来研究与展示的历史陶器","example":"The museum's ceramic art dates from the Bronze Age.","exampleCN":"博物馆的陶瓷艺术可追溯到青铜时代。","why":"Pottery survives where wood and cloth decay. Ancient ceramic art is therefore both an aesthetic record and a dating tool.","whyCN":"陶器能在木与布腐朽之处留存。因此古代陶瓷艺术既是审美记录，也是断代工具。"},{"no":"06","title":"The studio pottery movement","titleCN":"工作室陶艺运动","definition":"the twentieth-century movement of individual potters making signed work outside factories","definitionCN":"二十世纪个体陶艺家在工厂之外制作署名作品的运动","example":"Studio ceramic art rejected factory imitations.","exampleCN":"工作室陶艺拒绝工厂仿制品。","why":"When one pair of hands controls every stage, the pot becomes an individual work, and the phrase shifts from tradition to author.","whyCN":"当每一道工序都由同一双手掌控，器物就成为个人作品，这个短语也从传统转向作者。"},{"no":"07","title":"Architectural ceramics","titleCN":"建筑陶瓷装饰","definition":"tiles, reliefs and glazed surfaces designed as ceramic art for buildings","definitionCN":"为建筑设计的瓷砖、浮雕与釉面等陶瓷艺术","example":"The station façade is ceramic art from the nineteen fifties.","exampleCN":"车站立面是二十世纪五十年代的陶瓷艺术。","why":"Clay can be pressed into tiles and fired in quantity, so the art can cover a whole wall rather than sit on a shelf.","whyCN":"陶土能压成砖并批量烧制，因此这门艺术可以覆盖整面墙，而不是摆在架子上。"},{"no":"08","title":"Ritual and tomb figures","titleCN":"礼仪与陪葬陶俑","definition":"ceramic figures made for tombs, temples or ritual use","definitionCN":"为墓葬、神庙或礼仪用途制作的陶制形象","example":"The tomb yielded ceramic art in the form of horses.","exampleCN":"墓中出土了马形的陶瓷艺术品。","why":"Many cultures buried clay servants and animals with the dead. These figures were made to serve a ritual, yet they are now read as art.","whyCN":"许多文化把陶制仆从与动物随死者下葬。这些形象本为礼仪而作，如今却被当作艺术来读。"}],"etymology":{"intro":{"en":"Ceramic art joins a Greek word for potter's clay with the Latin word for skill. The first half reached English through nineteenth-century French scholarship. Dates are approximate.","cn":"ceramic art 把一个表示「陶土」的希腊词与表示「技艺」的拉丁词并在一起。前半经十九世纪法国学术进入英语。年代均为约数。"},"items":[{"era":"GREEK KERAMOS","en":"Greek keramos meant 'potter's clay, pottery'. Its origin is source uncertain; it is generally believed to be a pre-Greek loanword rather than an inherited Indo-European noun.","cn":"希腊 keramos 意为「陶土、陶器」。其来源属「来源不确定」；一般认为它是前希腊语的借词，而非继承自印欧语的固有名词。"},{"era":"GREEK KERAMIKOS","en":"The adjective keramikos 'of pottery' named the potters' quarter of Athens, the Kerameikos, and later any pottery technique.","cn":"形容词 keramikos「陶器的」曾指雅典的陶工区 Kerameikos，后来指任何陶艺技法。"},{"era":"FRENCH CÉRAMIQUE","en":"French scholarship revived the Greek adjective in the nineteenth century as céramique, a systematic term for the study and making of fired clay.","cn":"法国学术界在十九世纪重新启用这个希腊形容词，写作 céramique，作为研究并制作陶器的系统术语。"},{"era":"ENGLISH CERAMIC","en":"English borrowed ceramic in the same century, first as a technical adjective and later as a noun for the material and its products.","cn":"英语在同一世纪借入 ceramic，最初作技术形容词，后来作名词指材料及其制品。"},{"era":"LATIN ARS","en":"The second half is Latin ars 'skill, craft'. Its deeper origin is source uncertain, and the root often proposed for it is a reconstructed form.","cn":"后半是拉丁 ars「技艺、手艺」。其更深来源属「来源不确定」，常为其提出的词根只是重构形式。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: both the pre-Greek origin of keramos and the pre-Latin origin of ars are unresolved, so older forms offered for either are reconstructed forms.","cn":"来源不确定：keramos 的前希腊语来源与 ars 的前拉丁语来源都没有定论，因此为两者提出的更早形式都属于重构形式。"}]},"similar":{"note":{"en":"Group one holds forms of the same word that name different things; group two holds neighbouring words for fired clay.","cn":"第一组是同一个词的不同形式，却指不同事物；第二组是表示烧制陶土的相邻词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ceramic","ipa":"/səˈræmɪk/","tag":"material or adjective","definition":"the material itself, or an adjective meaning 'of fired clay'; ceramic art names the field, not the substance.","definitionCN":"材料本身，或表示「陶制的」的形容词；ceramic art 指领域，而非物质。"},{"word":"ceramics","ipa":"/səˈræmɪks/","tag":"plural category","definition":"the craft, the industry or objects as a class; it can include tiles and tableware that are not art.","definitionCN":"工艺、行业或作为类别的制品；可以包括并非艺术品的瓷砖与餐具。"},{"word":"ceramicist","ipa":"/səˈræmɪsɪst/","tag":"person, not the field","definition":"a person who makes ceramic work; it names the maker.","definitionCN":"制作陶瓷作品的人；它指创作者。"},{"word":"keramic","ipa":"/kəˈræmɪk/","tag":"older spelling","definition":"an older English spelling with k; it is the same word and not a separate term.","definitionCN":"较早的英语拼法，用 k 开头；它是同一个词，并非另一个术语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pottery","ipa":"/ˈpɒtəri/","tag":"the everyday word","definition":"the craft of making pots and the objects themselves; ceramic art is the formal term that claims artistic status.","definitionCN":"制陶手艺及陶制物件本身；陶瓷艺术是主张艺术地位的正式说法。"},{"word":"porcelain","ipa":"/ˈpɔːsəlɪn/","tag":"a finer material","definition":"a hard, white, translucent ceramic made from kaolin; it is one material within ceramic art, not the whole field.","definitionCN":"用高岭土制成的坚硬、洁白、半透明的陶瓷；它是陶瓷艺术中的一种材料，而非整个领域。"},{"word":"terracotta","ipa":"/ˌterəˈkɒtə/","tag":"earthenware type","definition":"brown-red unglazed earthenware; in art it names both the material and works made from it.","definitionCN":"棕红色无釉陶器；在艺术中既指材料，也指由此制成的作品。"},{"word":"sculpture","ipa":"/ˈskʌlptʃə/","tag":"broader category","definition":"three-dimensional art in any material; ceramic sculpture is one branch of ceramic art.","definitionCN":"任何材料的三维艺术；陶瓷雕塑是陶瓷艺术的一支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek root means potter's clay, so ceramic art is literally the art of clay.","cn":"希腊词根意为「陶土」，所以陶瓷艺术字面上就是「陶土的艺术」。"},{"en":"The adjective from that root named the potters' quarter of Athens before it named a technique.","cn":"由这个词根来的形容词先指雅典的陶工区，后来才指一种技法。"},{"en":"Fixed phrases sort its periods: ancient, studio, architectural, glazed.","cn":"固定搭配按时期与类型分类：古代的、工作室的、建筑的、上釉的。"},{"en":"A ceramicist is the maker; ceramic art is the field.","cn":"ceramicist 指创作者；ceramic art 指领域。"},{"en":"The plural ceramics includes tiles and cups that never claim to be art.","cn":"复数形式包含那些从不主张自己是艺术的瓷砖与杯子。"}],"abstract":[{"en":"Picture soft mud that becomes a hard, ringing object after one night in fire.","cn":"想象柔软的泥在火中过一夜，变成坚硬会响的器物。"},{"en":"Picture a bowl whose colour was decided by the kiln rather than the hand.","cn":"想象一只碗，颜色由窑火而非手决定。"},{"en":"Picture a cup that outlives the civilisation that made it.","cn":"想象一只杯子比制作它的文明活得更久。"}]},"examples":[{"en":"The exhibition traces ceramic art from tomb figures to studio bowls.","cn":"展览梳理了陶瓷艺术从陪葬陶俑到工作室碗器的历程。"},{"en":"She teaches ceramic art at a community kiln.","cn":"她在社区窑场教陶艺。"},{"en":"The building's ceramic art was restored tile by tile.","cn":"这座建筑的陶瓷装饰被逐块修复。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「陶瓷艺术」：把一团泥拉成器，再交给火定形 → 以陶土烧制的艺术","word":"ceramic art"},"root":"由 ceramic 与 art 组合：ceramic 经法语上溯至希腊 keramikos、keramos「陶土」，一般认为借自前希腊语；art 经古法语上溯至拉丁 ars「技艺」。两者的更早来源均不确定。","sensesIntro":{"en":"Eight senses follow one material from soft clay to hard art: the field itself, the vessel, the sculpture, the glazed surface, the archaeological relic, the studio author, the architectural wall, and the tomb figure.","cn":"八个义项让同一种材料从软泥走到硬器：领域本身、器皿、雕塑、釉面、考古遗物、工作室作者、建筑墙面，最后是墓葬陶俑。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wet lump on a wheel turned by hand, then fixed forever by fire.","cn":"核心意象：转盘上一团湿泥被手拉高，再被火永久固定。"},"chain":["CLAY","SHAPING","FIRING","GLAZED SURFACE","PERMANENT OBJECT","SCULPTURAL FORM"],"branches":[{"senses":"01","en":"THE FIELD: the phrase names the whole art of shaping and firing clay.","cn":"领域：这个短语指塑形并烧制陶土的整门艺术。"},{"senses":"02 · 03","en":"FORM: the useful vessel and the solid sculpture are two answers to the same clay.","cn":"形体：有用器皿与实心雕塑，是同一团泥的两种回答。"},{"senses":"04","en":"SURFACE: glaze adds colour and risk after the form is made.","cn":"表面：釉在形体完成之后增添颜色与风险。"},{"senses":"05 · 08","en":"DEEP TIME: archaeological pottery and tomb figures survive as evidence and as art.","cn":"深时间：考古陶器与陪葬陶俑同时作为证据与艺术留存下来。"},{"senses":"06 · 07","en":"FROM AUTHOR TO WALL: the studio potter signs the work, and architecture spreads it over a façade.","cn":"从作者到墙面：工作室陶艺家署名，建筑则把它铺满立面。"}]},"affixes":{"intro":{"en":"Ceramic art is a Greek material word joined to a Latin skill word; the Greek half names clay, the Latin half names the discipline.","cn":"ceramic art 是一个希腊材料词接上一个拉丁技艺词；希腊那一半指陶土，拉丁那一半指学科。"},"latinIntro":{"en":"The ceramic half has no native Latin cognate; Latin merely borrowed the Greek adjective as ceramicus. The art half descends from Latin ars, which gives art, artist and artisan.","cn":"陶瓷那一半没有本土拉丁同族词，拉丁语只是借用了希腊形容词 ceramicus。艺术那一半来自拉丁 ars，它给出 art、artist 与 artisan。"},"items":[{"word":"keramos","structure":"keramos (Greek noun, second declension)","meaning":"potter's clay, pottery","meaningCN":"陶土；陶器","example":"Keramos is generally believed to be a pre-Greek loanword.","exampleCN":"keramos 一般认为借自前希腊语。"},{"word":"keramikos","structure":"keramikos, keramike (Greek adjective)","meaning":"of pottery","meaningCN":"陶器的","example":"The adjective named the potters' quarter.","exampleCN":"这个形容词曾指陶工区。"},{"word":"ceramic","structure":"French céramique, from Greek keramikos","meaning":"of fired clay; the material","meaningCN":"陶制的；陶瓷材料","example":"The tile is ceramic.","exampleCN":"这块砖是陶制的。"},{"word":"ceramics","structure":"ceramic + -s (plural category)","meaning":"the craft, industry or objects","meaningCN":"陶瓷工艺、行业或制品","example":"The city is known for its ceramics.","exampleCN":"这座城市以陶瓷闻名。"},{"word":"ceramicist","structure":"ceramic + -ist (person who practises)","meaning":"a maker of ceramic work","meaningCN":"陶瓷艺术家","example":"The ceramicist signed the bowl.","exampleCN":"陶艺师在碗底署名。"},{"word":"ceramic art","structure":"ceramic + art","meaning":"the art of fired clay","meaningCN":"陶瓷艺术","example":"Ceramic art fills the lower gallery.","exampleCN":"陶瓷艺术占满下层画廊。"},{"word":"ceramic artist","structure":"ceramic + artist","meaning":"a person who makes ceramic art","meaningCN":"陶瓷艺术家","example":"The ceramic artist built the wall by hand.","exampleCN":"陶瓷艺术家亲手砌起那面墙。"},{"word":"ars","structure":"ars, artis (Latin noun, third declension)","meaning":"skill, craft","meaningCN":"技艺；手艺","example":"Ars supplies the second half of the phrase.","exampleCN":"ars 提供短语的后半部分。"},{"word":"art","structure":"Latin ars through Old French","meaning":"skill; the fine arts","meaningCN":"技艺；美术","example":"Art here means the discipline.","exampleCN":"这里的 art 指学科。"}],"latinEntries":[{"word":"ars","structure":"ars, artis (f., third declension)","meaning":"skill, craft, art","meaningCN":"技艺；手艺；艺术"}]}},{"word":"craftwork","ipa_uk":"/ˈkrɑːftwɜːk/","ipa_us":"/ˈkræftwɜːrk/","definition_zh":"手工制品；工艺劳作；手工艺","definition_en":"objects made by hand with skill, or the work of making them","core_image":"木桌上摆着刚做好的陶罐、编篮与木勺，每件都留有手指的痕迹","scene":"市集摊位上摆着村民亲手编的篮子、缝的布袋和削的木勺。The village stall sold baskets, cloth bags and wooden spoons as craftwork.","sceneCN":"这里指「手工制作的物件」（第 1 个义项：手工成品）；句意为村民的摊位出售篮子、布袋与木勺这类手工制品。可辨识物件：编篮、布袋、木勺、摊位。","pos":[{"tag":"n.","zh":"手工制品（集合）"},{"tag":"n.","zh":"手工制作；工艺劳作"}],"collocations":[{"phrase":"traditional craftwork","zh":"传统手工艺"},{"phrase":"handmade craftwork","zh":"手工制品"},{"phrase":"local craftwork","zh":"当地手工艺品"},{"phrase":"a piece of craftwork","zh":"一件手工艺品"},{"phrase":"craftwork skills","zh":"手工技艺"},{"phrase":"exhibit craftwork","zh":"展出手工艺品"}],"forms":[{"label":"不可数用法（指活动或成品总称）","form":"craftwork"},{"label":"可数用法（指一件作品，常以量词短语出现）","form":"a piece of craftwork"},{"label":"复数形式","form":"craftworks"},{"label":"所有格","form":"craftwork's"}],"derivatives":[{"word":"craftworker","pos":"n.","zh":"手工艺人（由表示技艺的词与表示「劳动者」的词复合，语义收窄为职业身份）"},{"word":"craftworking","pos":"n.","zh":"手工制作活动（由基础词加表示名词化的后缀构成，指持续的制作过程）"},{"word":"craftwork-like","pos":"adj.","zh":"类似手工制品的（由基础词加表示「像……的」后缀构成，语义偏移为性质描述）"},{"word":"craftwork tradition","pos":"n.","zh":"手工艺传统（由基础词与表示「传统」的词复合，语义偏移为传承体系）"}],"senses":[{"no":"01","title":"Handmade objects as a class","titleCN":"手工制品这一类别","definition":"objects made by hand with skill, considered together as a kind of product","definitionCN":"以技艺手工制作的物件，作为一类产品来看待","example":"The stall sold baskets, cloth bags and spoons as craftwork.","exampleCN":"摊位出售篮子、布袋与木勺这类手工制品。","why":"The word joins skill to work, so it names what skilled hands produce. The plural is avoided because the point is the class, not the count.","whyCN":"这个词把技艺与劳作并在一起，指有技艺的双手做出的东西。通常不用复数，因为重点在类别而非数量。"},{"no":"02","title":"The activity of making by hand","titleCN":"手工制作这项活动","definition":"the activity or labour of making objects by hand rather than by machine","definitionCN":"用手而非机器制作物件的活动或劳动","example":"Craftwork kept the household supplied through winter.","exampleCN":"整个冬天，家中靠手工制作维持用度。","why":"Skill and work can name either the doing or the done. In this sense the word is close to 'craft' as an activity.","whyCN":"技艺与劳作既可以指做的过程，也可以指做成的东西。这个义项接近表示活动的「手艺」。"},{"no":"03","title":"Regional traditional products","titleCN":"地方传统手工艺品","definition":"the characteristic handmade products of a place or community","definitionCN":"某个地方或社群特有的手工制品","example":"The island's craftwork is sold across the mainland.","exampleCN":"这座岛的手工艺品销往大陆各地。","why":"A region's materials and skills leave a visible signature, so craftwork becomes a way of naming local identity.","whyCN":"一个地方的材料与技艺会留下可见的印记，因此手工艺品成为命名地方身份的方式。"},{"no":"04","title":"The opposite of mass production","titleCN":"与批量生产相对的手工制作","definition":"hand production valued precisely because it is not machine-made or uniform","definitionCN":"正因为不是机器制造、也不整齐划一而受重视的手工生产","example":"Buyers pay more for craftwork than for factory copies.","exampleCN":"买家为手工艺品付的钱比工厂仿制品更多。","why":"In an industrial economy the word marks a boundary: small irregularities are proof of a hand, not defects.","whyCN":"在工业经济中，这个词划出一条界线：细微的不规整是手工的证明，而不是缺陷。"},{"no":"05","title":"Decorative handmade items","titleCN":"装饰性手工制品","definition":"handmade objects made mainly to decorate a home or a person","definitionCN":"主要为装饰住宅或人而制作的手工物件","example":"The fair was full of craftwork for the walls.","exampleCN":"集市上尽是挂在墙上的手工艺装饰。","why":"Once a craft object stops being useful, its surface and pattern carry the whole value, which is the decorative sense.","whyCN":"当手工物件不再实用，它的表面与图案就承载全部价值，这就是装饰义。"},{"no":"06","title":"School craft lessons","titleCN":"学校里的手工课","definition":"simple making activities taught to children with paper, clay, cloth and glue","definitionCN":"用纸、黏土、布与胶教给儿童的简单制作活动","example":"Craftwork occupies one afternoon a week.","exampleCN":"每周有一个下午安排手工课。","why":"Schools borrowed the word for making as a learning activity, where the process matters more than the product.","whyCN":"学校借这个词指作为学习活动的制作，其中过程比成品更重要。"},{"no":"07","title":"A livelihood from handwork","titleCN":"赖以为生的手工行业","definition":"hand production treated as a source of income for a family or village","definitionCN":"作为家庭或村庄收入来源的手工生产","example":"Craftwork supports thirty families in the valley.","exampleCN":"手工艺养活了山谷里的三十户人家。","why":"When the products are sold rather than used at home, craftwork becomes an occupation with prices, orders and seasons.","whyCN":"当制品被出售而非自家使用时，手工艺就成了有价格、订单与季节的职业。"},{"no":"08","title":"Visible mark of skilled labour","titleCN":"抽象义：熟练手工留下的痕迹","definition":"the visible trace of careful hand skill in any made thing, even one not usually called craft","definitionCN":"任何成品中可见的细致手工痕迹，即使该物通常不被称为手工艺品","example":"The cabinet is fine craftwork, joint by joint.","exampleCN":"这只柜子是一件精细的手工活，接榫处处见功夫。","why":"The word can praise any object where the hand's decisions remain visible, so it extends from baskets to furniture and even prose.","whyCN":"这个词可以称赞任何仍看得见手工判断的物件，因此从篮子延伸到家具，甚至文章。"}],"etymology":{"intro":{"en":"Craftwork is a native English compound of two Old English words: one for strength and skill, one for work. It has no Latin source. Dates are approximate.","cn":"craftwork 是由两个古英语词构成的本族复合词：一个表示力量与技艺，一个表示劳作。它没有拉丁来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH CRÆFT","en":"Cræft meant 'strength, power' before it meant 'skill, art, trade'. The modern word still carries both: a craft takes power as well as knowledge.","cn":"cræft 先意为「力量、能力」，后意为「技艺、本领、行业」。现代词仍保留两层：一门手艺既需知识，也需手上的力量。"},{"era":"OLD ENGLISH WEORC","en":"Weorc meant 'work, deed, labour'. It is the everyday Germanic word for doing something, not a borrowing.","cn":"weorc 意为「劳作、行为、工作」。它是日耳曼语中表示「做事情」的日常词，不是借词。"},{"era":"PROTO-GERMANIC","en":"The two stems go back to forms reconstructed as *kraftuz 'power' and *werkam 'work'; these are reconstructed forms, not recorded words.","cn":"这两个词干可上溯到被重构为 *kraftuz「力量」与 *werkam「工作」的形式；它们是重构形式，并非有记录的真实词形。"},{"era":"MIDDLE ENGLISH","en":"In Middle English craft widened from strength to skilled trade, and guilds used it for a body of workers with one skill.","cn":"在中古英语中，craft 从「力量」扩展到「熟练行业」，行会用它指拥有同一技艺的一群匠人。"},{"era":"MODERN COMPOUND","en":"The compound craftwork appeared with the nineteenth-century craft revival, when handmade goods were contrasted with factory output.","cn":"复合词 craftwork 随十九世纪的手工艺复兴出现；当时手工制品被拿来与工厂产品对照。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Germanic origin of both stems is unsettled, and the Indo-European root often cited for work is a reconstructed form rather than a recorded word.","cn":"来源不确定：两个词干在日耳曼语之前的来源都无定论，常为「工作」引用的印欧词根属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms from the same two stems that name other things; group two holds words for handmade production.","cn":"第一组是由同样两个词干构成、却指其他事物的形式；第二组是表示手工生产的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"craft","ipa":"/krɑːft/","tag":"skill or activity","definition":"the skill itself or the activity of making; craftwork names the products or the labour, not the skill alone.","definitionCN":"技艺本身或制作活动；craftwork 指制品或劳作，而不单指技艺。"},{"word":"craft worker","ipa":"/krɑːft ˈwɜːkə/","tag":"person","definition":"a person who makes things by hand; the two-word form names the person, while the one-word compound names the output.","definitionCN":"手工制作物件的人；分开写的形式指人，合写形式指产出。"},{"word":"crafty","ipa":"/ˈkrɑːfti/","tag":"changed meaning","definition":"cunning or sly; it comes from craft in the old sense of skill, but the meaning turned toward trickery.","definitionCN":"狡猾的；它来自 craft 表示「技艺」的旧义，但词义转向了诡计。"},{"word":"craft work","ipa":"/krɑːft wɜːk/","tag":"spelling variant, different stress","definition":"the same two words written separately, often meaning a specific job or assignment rather than the product class.","definitionCN":"同样两个词分开写，常指某项具体工作或任务，而非产品类别。"}]},{"heading":"NEAR MEANING","entries":[{"word":"handicraft","ipa":"/ˈhændikrɑːft/","tag":"close synonym","definition":"a craft made with the hands, or the objects so made; it stresses the hand where craftwork stresses the whole trade.","definitionCN":"用手制作的工艺或由此制成的物件；强调手，而 craftwork 强调整个行业。"},{"word":"handiwork","ipa":"/ˈhændiwɜːk/","tag":"result-focused","definition":"work done by a particular person's hands; it often praises the maker and implies authorship.","definitionCN":"某个人亲手做的工作；常含称赞之意，并暗示作者身份。"},{"word":"artisanry","ipa":"/ˈɑːtɪzənri/","tag":"formal register","definition":"the work or quality of skilled artisans; it is a formal term for the same economic activity.","definitionCN":"熟练工匠的工作或品质；是同一经济活动的正式说法。"},{"word":"handmade goods","ipa":"/ˈhændmeɪd ɡʊdz/","tag":"plain description","definition":"the everyday phrase for products made by hand; it states the fact without the cultural weight of craftwork.","definitionCN":"手工产品的日常说法；只陈述事实，不带 craftwork 的文化分量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Craft first meant strength, so craftwork is work done with power and skill together.","cn":"craft 最初指力量，因此 craftwork 是力量与技艺共同完成的劳作。"},{"en":"The two halves are both Old English, which is why the word feels plainer than most craft vocabulary.","cn":"两半都是古英语词，所以这个词比多数工艺词汇更朴素。"},{"en":"Fixed phrases place it: traditional craftwork, local craftwork, handmade craftwork.","cn":"固定搭配标出它的位置：传统手工艺、当地手工艺品、手工制品。"},{"en":"A craftworker is the person; craftwork is the output.","cn":"craftworker 指人；craftwork 指产出。"},{"en":"The word rose with the craft revival, when handmade goods were set against factory copies.","cn":"这个词随手工艺复兴而兴起，当时手工制品被拿来与工厂仿制品对照。"}],"abstract":[{"en":"Picture a table where every object shows a thumbprint or a knife mark.","cn":"想象一张桌子，每件东西都留着指印或刀痕。"},{"en":"Picture a basket that is slightly uneven precisely because a person made it.","cn":"想象一只略不规整的篮子，正因为它由人做成。"},{"en":"Picture a winter's supply of bowls and bags made at home while the fields slept.","cn":"想象田野沉睡时，家里做出一整个冬天要用的碗与袋子。"}]},"examples":[{"en":"The museum's craftwork collection includes baskets and wooden tools.","cn":"博物馆的手工艺品收藏包括篮子与木制工具。"},{"en":"Craftwork gives the village a steady income between harvests.","cn":"手工艺在收成之间的空档为村庄提供稳定收入。"},{"en":"The chair is honest craftwork, joined without nails.","cn":"这把椅子是实在的手工活，不用钉子接合。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「手艺 + 工作」—— 有手艺的人亲手做出来的东西 → 手工制品","word":"craftwork"},"root":"由古英语 cræft「力量、技艺」与 weorc「劳作」构成的本族复合词，属日耳曼语；两个词干在日耳曼语之前的来源均不确定，常见印欧词根属重构形式。","sensesIntro":{"en":"Eight senses follow skilled hands: the objects as a class, the activity, the regional product, the opposite of mass production, decoration, the school lesson, the family income, and finally the visible trace of care in any made thing.","cn":"八个义项围绕一双熟练的手展开：作为类别的制品、制作活动、地方产品、批量生产的对立面、装饰品、学校手工课、家庭收入，最后是任何成品中可见的用心痕迹。"},"semanticMap":{"core":{"en":"CORE IMAGE: a table of handmade objects, each carrying the small unevenness of a human hand.","cn":"核心意象：一桌手工物件，每件都带着人手造成的小小不齐。"},"chain":["SKILL","HAND WORK","MADE OBJECT","LOCAL PRODUCT","VISIBLE TRACE","HERITAGE SKILL"],"branches":[{"senses":"01 · 02","en":"MAKING AND MADE: the word covers both the labour and the objects it leaves behind.","cn":"制作与成品：这个词同时涵盖劳动与劳动留下的物件。"},{"senses":"03 · 07","en":"PLACE AND LIVELIHOOD: local products and family income tie the work to a community.","cn":"地方与生计：地方产品与家庭收入把这项工作系到社群上。"},{"senses":"04","en":"AGAINST THE MACHINE: craftwork is defined partly by what it is not.","cn":"与机器相对：手工艺部分地由「不是什么」来定义。"},{"senses":"05 · 06","en":"BEAUTY AND LEARNING: decoration and school lessons use the same hand skills for different ends.","cn":"美与学习：装饰与学校课程把同样的手工技能用于不同目的。"},{"senses":"08","en":"THE HAND'S SIGNATURE: the abstract sense praises any object where care remains visible.","cn":"手的签名：抽象义称赞任何仍看得见用心的物件。"}]},"affixes":{"intro":{"en":"Craftwork is built entirely from native English material, so it is read through two old stems rather than through Latin roots.","cn":"craftwork 完全由本族英语材料构成，因此要按两个古老词干来读，而不是按拉丁词根。"},"latinIntro":{"en":"No Latin borrowing stands behind this compound; the nearest Latin idea, ars 'skill', is a semantic counterpart and not a source form.","cn":"这个复合词背后没有拉丁借词；拉丁语中最近似的概念 ars「技艺」只是语义上的对应物，并非来源形式。"},"items":[{"word":"cræft","structure":"cræft (Old English noun, strong masculine)","meaning":"strength, power, skill","meaningCN":"力量；能力；技艺","example":"Cræft first named power before skill.","exampleCN":"cræft 先指力量，后指技艺。"},{"word":"craft","structure":"cræft, respelled in modern English","meaning":"skill; a skilled trade","meaningCN":"技艺；熟练行业","example":"The craft of weaving takes years.","exampleCN":"织造的技艺要学很多年。"},{"word":"weorc","structure":"weorc (Old English noun, strong neuter)","meaning":"work, deed","meaningCN":"劳作；行为","example":"Weorc is the everyday word for doing.","exampleCN":"weorc 是表示「做」的日常词。"},{"word":"work","structure":"weorc, respelled in modern English","meaning":"labour; a made result","meaningCN":"劳动；做成的结果","example":"The work took all winter.","exampleCN":"这件活干了一整个冬天。"},{"word":"craftwork","structure":"craft + work","meaning":"handmade goods; hand labour","meaningCN":"手工制品；手工劳作","example":"The shop sells local craftwork.","exampleCN":"这家店卖当地手工艺品。"},{"word":"craftworker","structure":"craft + worker","meaning":"a person who works by hand","meaningCN":"手工艺人","example":"The craftworker split the cane by hand.","exampleCN":"手艺人徒手劈开藤条。"},{"word":"craftworking","structure":"craftwork + -ing (action noun)","meaning":"the process of making by hand","meaningCN":"手工制作的过程","example":"Craftworking fills the winter months.","exampleCN":"手工制作填满了冬季的月份。"},{"word":"crafty","structure":"craft + -y (having the quality of)","meaning":"skilful, then cunning","meaningCN":"有技艺的，后转指狡猾的","example":"Crafty once meant skilled.","exampleCN":"crafty 曾意为「有技艺的」。"},{"word":"handcraft","structure":"hand + craft","meaning":"a craft made by hand","meaningCN":"手工技艺；手工艺品","example":"Handcraft survives beside machine work.","exampleCN":"手工技艺与机器生产并存。"},{"word":"craftwork-like","structure":"craftwork + -like (resembling)","meaning":"resembling handmade goods","meaningCN":"像手工制品的","example":"The moulded plastic looks craftwork-like.","exampleCN":"模压塑料看起来像手工制品。"}],"latinEntries":[]}},{"word":"artistic movement","ipa_uk":"/ɑːˈtɪstɪk ˈmuːvmənt/","ipa_us":"/ɑːrˈtɪstɪk ˈmuːvmənt/","definition_zh":"艺术运动；艺术流派","definition_en":"an organised trend in which a group of artists share aims and change how art is made","core_image":"一群艺术家在同一份宣言上签名，随后各自用不同材料表达同一种主张","scene":"十九世纪的画家们联合办展，发表宣言，反对学院派的规矩。A group of painters held their own exhibition and published a manifesto, founding an artistic movement.","sceneCN":"这里指「一群艺术家共同主张所形成的运动」（第 1 个义项：有共同目标的艺术运动）；句意为这群画家自办展览并发表宣言，开创了一个艺术运动。可辨识物件：画布、宣言纸、签名、展厅。","pos":[{"tag":"n.","zh":"艺术运动；艺术流派"},{"tag":"n.","zh":"（某一时期的）艺术潮流"}],"collocations":[{"phrase":"a new artistic movement","zh":"一场新的艺术运动"},{"phrase":"found an artistic movement","zh":"创立一个艺术运动"},{"phrase":"lead an artistic movement","zh":"领导一场艺术运动"},{"phrase":"a major artistic movement","zh":"一场重要的艺术运动"},{"phrase":"join an artistic movement","zh":"加入一场艺术运动"},{"phrase":"the artistic movements of the twentieth century","zh":"二十世纪诸艺术运动"}],"forms":[{"label":"单数形式","form":"artistic movement"},{"label":"复数形式","form":"artistic movements"},{"label":"所有格","form":"artistic movement's"},{"label":"定语用法","form":"artistic-movement"}],"derivatives":[{"word":"artist","pos":"n.","zh":"艺术家（由基础词根加表示「从事者」的后缀构成，语义收窄为职业）"},{"word":"artistic","pos":"adj.","zh":"艺术的；有艺术性的（由表示艺术家的词加表示「与……有关的」后缀构成，语义偏移为性质描述）"},{"word":"artistry","pos":"n.","zh":"艺术才能；艺术性（由表示艺术家的词加表示「技艺或集合」的后缀构成，语义偏移为能力）"},{"word":"art movement","pos":"n.","zh":"艺术运动（由表示艺术的词与表示「运动」的词缩略复合，省去形容词形式，语义不变而更常用于史论）"}],"senses":[{"no":"01","title":"A trend with shared aims","titleCN":"有共同目标的艺术运动","definition":"an organised trend in which many artists pursue the same aims at the same time","definitionCN":"许多艺术家在同一时期追求相同目标而形成的组织化潮流","example":"A group of painters founded an artistic movement in the capital.","exampleCN":"一群画家在首都发起了一场艺术运动。","why":"The phrase joins the adjective for art to the noun for motion. A movement is not one work but many works moving in one direction.","whyCN":"这个短语把表示艺术的形容词接到表示运动的名词上。运动不是一件作品，而是许多作品朝同一方向移动。"},{"no":"02","title":"A manifesto group","titleCN":"以宣言集结的艺术家团体","definition":"a group of artists bound by a published statement of principles","definitionCN":"由一份公开的原则声明联结起来的艺术家群体","example":"The artistic movement began with a single manifesto.","exampleCN":"这场艺术运动始于一份宣言。","why":"Modern movements needed a public text to declare what they rejected. The manifesto turns separate artists into a named body.","whyCN":"现代艺术运动需要一份公开文本，宣告自己拒绝什么。宣言把分散的艺术家变成一个有名号的团体。"},{"no":"03","title":"A period style named later","titleCN":"后来被命名的时期风格","definition":"a style of a period that critics and historians name after the fact","definitionCN":"由评论家与历史学家在事后命名的某一时期风格","example":"The artistic movement was named by a hostile critic.","exampleCN":"这场艺术运动是由一位敌意评论家命名的。","why":"Many movements did not choose their names. Critics supplied a label, and the label later became a period category.","whyCN":"许多运动的名字并非自己选定。评论家提供了标签，标签后来成为时期分类。"},{"no":"04","title":"An avant-garde challenge","titleCN":"前卫的挑战","definition":"a movement that deliberately breaks with accepted rules and institutions","definitionCN":"有意与既定规则和机构决裂的运动","example":"The artistic movement rejected the academy's rules.","exampleCN":"这场艺术运动拒绝了学院的规矩。","why":"Avant-garde movements define themselves by what they oppose, so conflict with institutions is part of the sense.","whyCN":"前卫运动以自己反对的东西来定义自身，因此与机构的冲突是这个义项的一部分。"},{"no":"05","title":"A single-medium movement","titleCN":"单一媒介内的运动","definition":"a movement confined to one art, such as painting, sculpture or photography","definitionCN":"局限于一种艺术门类内的运动，如绘画、雕塑或摄影","example":"Photography had its own artistic movement in the same decade.","exampleCN":"摄影在同一个十年里也有自己的艺术运动。","why":"Each medium has its own technical problems, so movements often form inside one discipline before spreading.","whyCN":"每种媒介都有自己的技术难题，因此运动常先在某一门类内部形成，再向外扩散。"},{"no":"06","title":"A movement across media","titleCN":"跨媒介的艺术运动","definition":"a movement that links painting, literature, music and design under one programme","definitionCN":"在一套纲领下把绘画、文学、音乐与设计联结起来的运动","example":"The artistic movement reached poetry and music as well.","exampleCN":"这场艺术运动也波及诗歌与音乐。","why":"When a movement has a shared theory rather than a shared technique, it can travel from canvas to page to stage.","whyCN":"当一场运动共享的是理论而非技法，它就能从画布走到书页，再走到舞台。"},{"no":"07","title":"A national or regional movement","titleCN":"国族或地方艺术运动","definition":"a movement tied to the identity or politics of a particular country or region","definitionCN":"与某一国家或地区的身份认同或政治相绑定的运动","example":"The artistic movement became part of the independence struggle.","exampleCN":"这场艺术运动成为独立斗争的一部分。","why":"Art can carry a nation's claim to its own language and history, so a movement may be organised around place as much as style.","whyCN":"艺术可以承载一个民族对自身语言与历史的主张，因此运动也可能围绕地方而非风格来组织。"},{"no":"08","title":"A reaction against another movement","titleCN":"针对另一场运动的反动","definition":"a movement formed chiefly in opposition to an earlier or rival movement","definitionCN":"主要为反对更早或敌对运动而形成的新运动","example":"The next artistic movement answered the first one directly.","exampleCN":"下一场艺术运动直接回应了前一场。","why":"Movements come in pairs: one sets a rule, the next breaks it. The phrase can therefore name a reaction as easily as an origin.","whyCN":"运动常成对出现：一场立规矩，下一场破规矩。因此这个短语既能命名源头，也能命名反动。"}],"etymology":{"intro":{"en":"Artistic movement joins an adjective built from art with a noun built from a Latin verb meaning 'to move'. Both halves are old borrowings, while the phrase itself is modern. Dates are approximate.","cn":"artistic movement 把由 art 构成的形容词与一个来自拉丁动词「移动」的名词并在一起。两半都是古老借词，短语本身却是现代的。年代均为约数。"},"items":[{"era":"LATIN ARS","en":"Latin ars 'skill, craft' gives art. Its deeper origin is source uncertain, and any older root proposed for it is a reconstructed form.","cn":"拉丁 ars「技艺、手艺」给出 art。其更深来源属「来源不确定」，为其提出的更早词根都是重构形式。"},{"era":"ARTIST AND ARTISTIC","en":"Artist came through French from Latin artista, itself from ars. English added -ic to make artistic in the eighteenth century.","cn":"artist 经法语来自拉丁 artista，而 artista 又出自 ars。英语在十八世纪加上表示「与……有关的」后缀，构成 artistic。"},{"era":"LATIN MOVERE","en":"Latin movere 'to move' produced motus 'a moving' and movimentum, the source of movement.","cn":"拉丁 movere「移动」产生 motus「运动」与 movimentum，后者是 movement 的来源。"},{"era":"OLD FRENCH MOVEMENT","en":"Old French movement carried the noun into English, where it first meant physical motion and later a collective campaign.","cn":"古法语 movement 把这个名词带进英语，最初指物理运动，后来指集体行动。"},{"era":"MODERN PHRASE","en":"Artistic movement became a standard term in the nineteenth century, when critics began grouping artists by shared programmes rather than by individual careers.","cn":"artistic movement 在十九世纪成为标准术语；当时评论家开始按共同纲领、而非个人生涯给艺术家分组。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origins of ars and movere are both unresolved, so older forms offered for either are reconstructed forms rather than recorded words.","cn":"来源不确定：ars 与 movere 在拉丁语之前的来源都没有定论，因此为两者提出的更早形式都属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms built from the same words with a different scope; group two holds historical terms for grouped art activity.","cn":"第一组是由同样几个词构成、范围不同的形式；第二组是表示群体艺术活动的史学术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"art movement","ipa":"/ɑːt ˈmuːvmənt/","tag":"short form","definition":"the usual shorter term in art history; it drops the adjective but keeps the same meaning.","definitionCN":"艺术史中常用的较短说法；省去形容词，意思不变。"},{"word":"artistic","ipa":"/ɑːˈtɪstɪk/","tag":"adjective only","definition":"relating to art or to artists; alone it describes a quality, not an organised group.","definitionCN":"与艺术或艺术家有关的；单独使用时描述一种性质，而非组织化群体。"},{"word":"artistry","ipa":"/ˈɑːtɪstri/","tag":"skill, not a group","definition":"the skill of an artist; it names personal ability, while a movement is collective.","definitionCN":"艺术家的技艺；它指个人能力，而运动是集体的。"},{"word":"movement","ipa":"/ˈmuːvmənt/","tag":"general noun","definition":"physical motion, or any organised campaign; the full phrase narrows it to art.","definitionCN":"物理运动，或任何组织化行动；完整短语把它收窄到艺术。"}]},{"heading":"NEAR MEANING","entries":[{"word":"school","ipa":"/skuːl/","tag":"grouping term","definition":"a group of artists sharing a style or teaching; it often implies a master and followers rather than a public programme.","definitionCN":"共享风格或师承的艺术家群体；常暗示师徒关系，而非公开纲领。"},{"word":"style","ipa":"/staɪl/","tag":"visual traits","definition":"the recurring visual features of works; a movement may have a style, but style alone does not imply organisation.","definitionCN":"作品中反复出现的视觉特征；运动可以有一种风格，但风格本身不意味组织。"},{"word":"avant-garde","ipa":"/ˌævɒ̃ ˈɡɑːd/","tag":"political metaphor","definition":"the advanced group that claims to lead; it stresses rejection of tradition more than the phrase artistic movement does.","definitionCN":"自称走在前列的先进群体；比 artistic movement 更强调拒绝传统。"},{"word":"trend","ipa":"/trend/","tag":"weaker claim","definition":"a general direction of change; it can be unplanned, while a movement implies shared intent.","definitionCN":"变化的大方向；可以是无计划的，而运动暗示共同意图。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Artistic is artist plus -ic, so the phrase literally means the art-related movement.","cn":"artistic 是在 artist 之后加表示「与……有关的」后缀而成，因此这个短语字面上就是「与艺术有关的运动」。"},{"en":"Movement goes back to a Latin verb for moving, which is why a trend can be pictured as many works walking one way.","cn":"movement 上溯到拉丁语表示「移动」的动词，所以一场潮流可以想象成许多作品朝同一方向行走。"},{"en":"Fixed phrases mark its stages: found, lead, join, and later study a movement.","cn":"固定搭配标出它的阶段：创立、领导、加入，后来是研究一场运动。"},{"en":"Art movement is the shorter term used most often in textbooks.","cn":"art movement 是教科书中最常用的较短说法。"},{"en":"Many movements were named by critics, which is why the label sometimes sounds hostile.","cn":"许多运动由评论家命名，这也是标签有时带敌意的原因。"}],"abstract":[{"en":"Picture a crowd walking in one direction without a leader visible at the front.","cn":"想象一群人朝同一方向走，最前面却看不见领队。"},{"en":"Picture a signature page where every name is written in a different hand.","cn":"想象一页签名，每个名字都出自不同的手。"},{"en":"Picture a rule being written down so that the next generation can break it.","cn":"想象一条规矩被写下来，好让下一代去打破它。"}]},"examples":[{"en":"Impressionism began as an artistic movement with its own exhibitions.","cn":"印象派最初是一场自办展览的艺术运动。"},{"en":"The artistic movement spread from painting into poetry and music.","cn":"这场艺术运动从绘画蔓延到诗歌与音乐。"},{"en":"Later critics treated the artistic movement as a single period style.","cn":"后来的评论家把这场艺术运动当作一个统一的时期风格。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「艺术的运动」—— 一群艺术家朝同一个方向一起走 → 艺术运动、艺术流派","word":"artistic movement"},"root":"由 artistic 与 movement 组合：artistic 源于拉丁 ars「技艺」经 artist 加表示「与……有关的」后缀；movement 经古法语上溯至拉丁 movere「移动」及其派生 movimentum。两者的更早来源均不确定。","sensesIntro":{"en":"Eight senses follow a collective drift: a shared aim, a manifesto, a later label, an avant-garde break, one medium, many media, a nation, and finally a reaction against the movement before it.","cn":"八个义项围绕一次集体转向展开：共同目标、宣言、事后标签、前卫决裂、单一媒介、跨媒介、国族，最后是对前一场运动的反动。"},"semanticMap":{"core":{"en":"CORE IMAGE: many artists walking one way, each carrying a different tool.","cn":"核心意象：许多艺术家朝同一方向走，每人手里拿着不同的工具。"},"chain":["SHARED AIM","PUBLIC PROGRAMME","GROUP OF ARTISTS","BREAK WITH RULES","LATER LABEL","MUSEUM CANON"],"branches":[{"senses":"01 · 02","en":"ORIGIN: a shared aim becomes public when a group writes it down.","cn":"起点：共同目标在群体把它写下来时成为公开纲领。"},{"senses":"03","en":"AFTERLIFE: critics turn the group into a period style with a name.","cn":"身后：评论家把这个群体变成一个有名号的时期风格。"},{"senses":"04","en":"OPPOSITION: the movement defines itself by what it refuses.","cn":"对抗：运动以自己拒绝的东西来定义自身。"},{"senses":"05 · 06","en":"MEDIA: one discipline or several can carry the same programme.","cn":"媒介：一门或数门艺术都能承载同一套纲领。"},{"senses":"07 · 08","en":"PLACE AND REACTION: a national cause and a counter-movement show that art moves with politics and with its rivals.","cn":"地方与反动：民族事业与反向运动说明艺术会随政治与对手一起移动。"}]},"affixes":{"intro":{"en":"The phrase is built from art and motion, and both halves bring productive families into English.","cn":"这个短语由「艺术」与「运动」构成，两半都为英语带来能产的词族。"},"latinIntro":{"en":"Latin ars gives art, artist, artistic and artisan; Latin movere gives move, movement, motion and motive.","cn":"拉丁 ars 给出 art、artist、artistic 与 artisan；拉丁 movere 给出 move、movement、motion 与 motive。"},"items":[{"word":"ars","structure":"ars, artis (Latin noun, third declension)","meaning":"skill, craft","meaningCN":"技艺；手艺","example":"Ars is the root of art.","exampleCN":"ars 是 art 的词根。"},{"word":"art","structure":"Latin ars through Old French","meaning":"skill; the fine arts","meaningCN":"技艺；美术","example":"Art changed meaning over centuries.","exampleCN":"art 的含义在几个世纪中发生变化。"},{"word":"-ist","structure":"-ist (Greek -istes through Latin -ista)","meaning":"a person who practises","meaningCN":"从事某种活动的人","example":"Artist means one who works in art.","exampleCN":"artist 指从事艺术的人。"},{"word":"artist","structure":"art + -ist","meaning":"a maker of art","meaningCN":"艺术家","example":"The artist joined the group.","exampleCN":"这位艺术家加入了那个群体。"},{"word":"-ic","structure":"-ic (Greek -ikos through Latin -icus)","meaning":"relating to","meaningCN":"与……有关的","example":"Artistic means relating to art.","exampleCN":"artistic 意为与艺术有关的。"},{"word":"artistic","structure":"artist + -ic","meaning":"relating to art","meaningCN":"艺术的","example":"The artistic aims were new.","exampleCN":"这些艺术目标很新。"},{"word":"movere","structure":"movere, movi, motum (Latin verb, second conjugation)","meaning":"to move","meaningCN":"移动","example":"Movere gives movement and motion.","exampleCN":"movere 给出 movement 与 motion。"},{"word":"movement","structure":"Old French movement, from Latin movimentum","meaning":"motion; an organised campaign","meaningCN":"运动；组织化行动","example":"The movement grew quickly.","exampleCN":"这场运动发展得很快。"},{"word":"artistic movement","structure":"artistic + movement","meaning":"a collective art trend","meaningCN":"集体性的艺术潮流","example":"The artistic movement had a manifesto.","exampleCN":"这场艺术运动有一份宣言。"},{"word":"art movement","structure":"art + movement (shortened form)","meaning":"the usual shorter term","meaningCN":"常用的较短说法","example":"Art movement is the textbook term.","exampleCN":"art movement 是教科书的说法。"}],"latinEntries":[{"word":"ars","structure":"ars, artis (f., third declension)","meaning":"skill, craft, art","meaningCN":"技艺；手艺；艺术"},{"word":"movere","structure":"movere, movi, motum (verb, second conjugation)","meaning":"to move","meaningCN":"移动"},{"word":"motus","structure":"motus, motus (m., fourth declension)","meaning":"a moving, motion","meaningCN":"运动；移动"}]}},{"word":"realism","ipa_uk":"/ˈriːəlɪzəm/","ipa_us":"/ˈriːəlɪzəm/","definition_zh":"现实主义；写实主义；务实态度；实在论","definition_en":"the attempt to show things as they really are, or the belief that reality exists independently of the mind","core_image":"画家把街角面包店的旧招牌、脏围裙与找零的手一分不差地画下来","scene":"画家在街角支起画架，把面包店的旧招牌与顾客的皱纹一起画进画里。The painter set up his easel at the corner and recorded the bakery's worn sign and its customers' wrinkles with realism.","sceneCN":"这里指「如实描绘日常生活的写实手法」（第 1 个义项：艺术中的现实主义）；句意为画家在街角支起画架，用写实手法记录旧招牌与顾客的皱纹。可辨识物件：画架、面包店招牌、顾客、皱纹。","pos":[{"tag":"n.","zh":"现实主义；写实主义（艺术与文学）"},{"tag":"n.","zh":"务实态度；实在论（哲学用语）"}],"collocations":[{"phrase":"literary realism","zh":"文学现实主义"},{"phrase":"socialist realism","zh":"社会主义现实主义"},{"phrase":"magical realism","zh":"魔幻现实主义"},{"phrase":"a sense of realism","zh":"现实感"},{"phrase":"realism in art","zh":"艺术中的现实主义"},{"phrase":"political realism","zh":"政治现实主义"}],"forms":[{"label":"单数形式","form":"realism"},{"label":"复数形式（指多种现实主义）","form":"realisms"},{"label":"所有格","form":"realism's"},{"label":"相关形容词","form":"realist"}],"derivatives":[{"word":"realist","pos":"n./adj.","zh":"现实主义者；写实的（由基础词加表示「信奉者」的后缀构成，语义收窄为立场身份）"},{"word":"realistic","pos":"adj.","zh":"现实的；写实的（由表示现实主义者的词加表示「与……有关的」后缀构成，语义偏移为性质描述）"},{"word":"realistically","pos":"adv.","zh":"现实地；写实地（由前一个形容词加构成副词的后缀构成，语义偏移为方式）"},{"word":"reality","pos":"n.","zh":"现实；真实（由基础词加表示状态的后缀构成，语义偏移为「真实的状态」）"}],"senses":[{"no":"01","title":"Art that shows ordinary life","titleCN":"描绘日常生活的现实主义","definition":"a nineteenth-century art movement that depicted ordinary people and everyday scenes without idealising them","definitionCN":"十九世纪一场描绘普通人和平常场景、不作美化的艺术运动","example":"The painter recorded the bakery's worn sign with realism.","exampleCN":"画家用写实手法画下面包店的旧招牌。","why":"The word claims that the artwork corresponds to the thing itself. Ordinary life is chosen because it has not been arranged for display.","whyCN":"这个词主张作品与事物本身相对应。选择日常生活，是因为它没有被安排成展示的样子。"},{"no":"02","title":"Literary realism","titleCN":"文学中的现实主义","definition":"a style of fiction that presents plausible people, settings and causes without romantic exaggeration","definitionCN":"以可信的人物、环境与因果呈现生活、不作浪漫夸张的小说风格","example":"The novel brought realism to the industrial city.","exampleCN":"这部小说把现实主义带进工业城市。","why":"Fiction can either flatter life or report it. Realism chooses report, and its plots follow ordinary cause and effect.","whyCN":"小说可以美化生活，也可以报道生活。现实主义选择报道，情节遵循日常的因果关系。"},{"no":"03","title":"The quality of being true to life","titleCN":"逼真的品质","definition":"the degree to which a work or account matches how things actually look or happen","definitionCN":"作品或叙述与实际外观或实际发生相符的程度","example":"The film's realism comes from its unpolished streets.","exampleCN":"这部影片的真实感来自未经修饰的街道。","why":"Here the word is a measure rather than a movement: any detail that matches experience increases realism.","whyCN":"这里这个词是一种尺度，而不是一场运动：任何与经验相符的细节都增加真实感。"},{"no":"04","title":"A practical attitude","titleCN":"务实态度","definition":"the habit of accepting facts and limits rather than wishes or ideals","definitionCN":"接受事实与限制、而非愿望或理想的态度","example":"The plan was received with realism rather than hope.","exampleCN":"这个计划得到的是务实评估，而非乐观期待。","why":"Someone who sees things as they are will not promise what cannot be done. The art sense becomes a temperament.","whyCN":"看清事物本相的人不会承诺做不到的事。艺术义由此变成一种性情。"},{"no":"05","title":"Philosophical realism","titleCN":"哲学中的实在论","definition":"the view that reality, or universals, exists independently of how minds perceive or describe it","definitionCN":"认为实在或共相独立于心灵感知与描述而存在的观点","example":"Realism holds that the mountain exists before anyone climbs it.","exampleCN":"实在论认为山在有人攀登之前就已存在。","why":"Philosophy asks whether the world depends on the observer. Realism answers no, and that answer is the oldest sense of the word.","whyCN":"哲学追问世界是否依赖观察者。实在论回答「不」，这个回答正是这个词最古老的义项。"},{"no":"06","title":"Realism in international relations","titleCN":"国际关系中的现实主义","definition":"the theory that states act mainly to pursue power and security in an anarchic world","definitionCN":"认为国家在无政府的世界上主要追求权力与安全的理论","example":"Realism explains the alliance as a balance of power.","exampleCN":"现实主义把这个联盟解释为权力平衡。","why":"Political realism applies the practical attitude to states: it assumes interests, not ideals, drive decisions.","whyCN":"政治现实主义把务实态度用到国家上：它假定驱动决策的是利益，而非理想。"},{"no":"07","title":"Legal realism","titleCN":"法学中的现实主义","definition":"the view that law is what courts and officials actually do rather than only what statutes say","definitionCN":"认为法律在于法院与官员实际怎么做、而不只是条文怎么写的主张","example":"Legal realism studies how judges really decide cases.","exampleCN":"法律现实主义研究法官实际如何判案。","why":"The same move recurs: look at practice rather than at the official description. Law's realism is about what happens in court.","whyCN":"同一个动作反复出现：看实践，而不是看官方描述。法学的现实主义关注的是法庭里实际发生的事。"},{"no":"08","title":"Photographic and cinematic realism","titleCN":"摄影与电影的真实感","definition":"the impression that a photograph or film shows events as they occurred, without intervention","definitionCN":"照片或影片呈现事件如同自然发生、未经干预的印象","example":"Handheld camera work adds realism to the scene.","exampleCN":"手持摄影给这个场景增添了真实感。","why":"A camera seems to record rather than compose, so its images borrow the word for truth even though every frame is chosen.","whyCN":"摄影机看似记录而非构图，因此它的影像借用了表示「真实」的词，尽管每一帧都是被选定的。"},{"no":"09","title":"Socialist realism","titleCN":"社会主义现实主义","definition":"the official style required in Soviet art, showing workers and leaders in an idealised revolutionary light","definitionCN":"苏联艺术中被要求采用的官方风格，以理想化的革命光辉表现劳动者与领袖","example":"Socialist realism turned factory work into heroic painting.","exampleCN":"社会主义现实主义把工厂劳动变成英雄式绘画。","why":"The name is paradoxical: a style called realism by decree idealises its subjects. The word here marks political approval, not accuracy.","whyCN":"这个名称本身矛盾：一种被法令规定为现实主义的风格却在美化对象。此处这个词标记的是政治认可，而非准确。"}],"etymology":{"intro":{"en":"Realism is Latin 'thing' plus the Greek suffix for a system or practice. The philosophical use is oldest, while the artistic use dates from the nineteenth century. Dates are approximate.","cn":"realism 由拉丁语表示「事物」的词加上表示体系或做法的希腊后缀构成。哲学用法最古老，艺术用法则始于十九世纪。年代均为约数。"},"items":[{"era":"LATIN RES","en":"Latin res meant 'thing, matter, affair'. Its deeper origin is source uncertain, and any older root proposed for it is a reconstructed form.","cn":"拉丁 res 意为「事物、事情、要务」。其更深来源属「来源不确定」，为其提出的更早词根都是重构形式。"},{"era":"LATE LATIN REALIS","en":"Late Latin realis 'of a thing' produced the English adjective real, first in the sense of something that actually exists.","cn":"晚期拉丁 realis「关于事物的」产生英语形容词 real，最初指确实存在的东西。"},{"era":"GREEK -ISMOS","en":"The suffix -ism came through Latin from Greek -ismos, naming a practice, system or doctrine.","cn":"表示学说的后缀经拉丁语来自希腊同名后缀，用来命名一种做法、体系或学说。"},{"era":"PHILOSOPHICAL USE","en":"In medieval philosophy realism named the view that universals are real; nominalism was its opposite. This use predates the artistic one.","cn":"在中世纪哲学中，realism 指认为共相真实存在的观点，唯名论则是其对立面。这一用法早于艺术用法。"},{"era":"FRENCH RÉALISME","en":"French criticism used réalisme in the nineteenth century for painters and novelists who reported ordinary life, and English followed.","cn":"法国批评界在十九世纪用 réalisme 指报道日常生活的画家与小说家，英语随后跟进。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origin of res is unresolved, and older Indo-European forms offered for it are reconstructed forms rather than recorded words.","cn":"来源不确定：res 在拉丁语之前的来源没有定论，为其提出的更早印欧语形式属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds words from the same stem that are constantly confused; group two holds competing ways of describing truth to life.","cn":"第一组是同出一个词干、极易混淆的词；第二组是描述「贴近生活」的几种竞争性说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"realist","ipa":"/ˈriːəlɪst/","tag":"person or adjective","definition":"a person who holds the view, or an adjective describing that style; realism is the view itself.","definitionCN":"持这种观点的人，或描述这种风格的形容词；realism 是观点本身。"},{"word":"realistic","ipa":"/riːˈlɪstɪk/","tag":"quality adjective","definition":"sensible and true to life; it describes things, while realism names a movement or doctrine.","definitionCN":"合理且贴近现实的；它描述事物，而 realism 指运动或学说。"},{"word":"reality","ipa":"/riˈæləti/","tag":"the thing itself","definition":"what actually exists; realism is the attitude or style that respects it.","definitionCN":"实际存在的事物；realism 是尊重它的态度或风格。"},{"word":"realty","ipa":"/ˈriːəlti/","tag":"property, different branch","definition":"land and buildings as property; it comes from real in the legal sense of immovable property, not from realism.","definitionCN":"作为财产的土地与建筑；它来自 real 表示「不动产」的法律义，与 realism 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"naturalism","ipa":"/ˈnætʃrəlɪzəm/","tag":"closer to science","definition":"a style that applies an almost scientific observation of cause and environment; it is stricter and often darker than realism.","definitionCN":"近乎科学地观察因果与环境的一种风格；比现实主义更严格，也常更阴暗。"},{"word":"verism","ipa":"/ˈvɪərɪzəm/","tag":"extreme accuracy","definition":"the deliberate choice of ugly or ordinary detail for maximum accuracy; it pushes realism to an extreme.","definitionCN":"刻意选择丑陋或平常的细节以求最大准确；把现实主义推到极端。"},{"word":"pragmatism","ipa":"/ˈpræɡmətɪzəm/","tag":"action-centred","definition":"the doctrine that the worth of an idea lies in its practical results; it shares realism's practical temper but is a philosophy of action.","definitionCN":"认为观念的价值在于实际结果的主张；与现实主义共享务实气质，但它是行动哲学。"},{"word":"idealism","ipa":"/aɪˈdɪəlɪzəm/","tag":"the opposite","definition":"the view that reality is mental, or the habit of measuring life against ideals; it is the standing opposite of realism in both art and philosophy.","definitionCN":"认为实在是精神的，或以理想衡量生活的习惯；在艺术与哲学中都是现实主义的对立面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Realism is real plus -ism: the doctrine or practice of the thing itself.","cn":"realism 是在 real 之后加表示学说的后缀：关于事物本身的做法或学说。"},{"en":"The philosophical sense is older than the artistic one, which is why the word also means a belief about reality.","cn":"哲学义比艺术义更古老，所以这个词也指一种关于实在的信念。"},{"en":"Fixed phrases mark its branches: literary, socialist, magical, political.","cn":"固定搭配标出它的分支：文学的、社会主义的、魔幻的、政治的。"},{"en":"A realist is the person; realistic is the adjective; realism is the position.","cn":"realist 指人；realistic 是形容词；realism 是立场。"},{"en":"The stem res means 'thing', so realism always turns attention back to things.","cn":"词干 res 意为「事物」，所以 realism 总是把注意力转回事物本身。"}],"abstract":[{"en":"Picture a painter refusing to move a chair because the room looks better without it.","cn":"想象一位画家拒绝挪动椅子，因为房间没有它更好看。"},{"en":"Picture a mountain that keeps existing when nobody is looking at it.","cn":"想象一座山，在无人观看时仍然存在。"},{"en":"Picture a style ordered by the state to call itself truthful.","cn":"想象一种被国家要求自称真实的风格。"}]},"examples":[{"en":"Realism in painting began with scenes of work and poverty.","cn":"绘画中的现实主义从劳动与贫困的场景开始。"},{"en":"The report was written with realism about the budget.","cn":"这份报告对预算作了务实的评估。"},{"en":"Philosophical realism defends a world independent of our descriptions.","cn":"哲学实在论捍卫一个独立于我们描述的世界。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「真实 + 主义」—— 坚持照着事物本来的样子写和画 → 现实主义、写实主义","word":"realism"},"root":"由晚期拉丁 realis「关于事物的」加希腊系的学说后缀构成；realis 出自拉丁 res「事物」。res 在拉丁语之前的来源不确定，更早的印欧语形式均属重构。","sensesIntro":{"en":"Nine senses follow one demand: look at the thing itself. Art, fiction, photography and law apply it to seeing and recording, while practical life, philosophy and politics apply it to belief and decision.","cn":"九个义项围绕同一个要求展开：看事物本身。艺术、小说、摄影与法律把它用于观看与记录，务实生活、哲学与政治则把它用于信念与决策。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand recording exactly what is on the table, including the dirt.","cn":"核心意象：一只手把桌上的东西原样记下，连灰尘也不漏。"},"chain":["THE THING","ACCURATE RECORD","ORDINARY LIFE","PRACTICAL JUDGEMENT","INDEPENDENT REALITY","PHILOSOPHICAL CLAIM"],"branches":[{"senses":"01 · 02","en":"ART AND FICTION: painting and the novel report ordinary life instead of improving it.","cn":"艺术与小说：绘画与小说报道日常生活，而不是美化它。"},{"senses":"03 · 08","en":"MEASURE OF TRUTH: a detail or a camera image can be judged by how closely it matches experience.","cn":"真实尺度：细节或摄影影像可按其与经验的接近程度来评判。"},{"senses":"04","en":"TEMPERAMENT: the same demand becomes a practical attitude toward limits.","cn":"性情：同一个要求变成面对限制时的务实态度。"},{"senses":"05 · 09","en":"TWO POLES: philosophy asserts an independent world, while socialist realism shows a doctrine using the word for approval.","cn":"两极：哲学主张独立世界，社会主义现实主义则展示一种学说如何借这个词表示认可。"},{"senses":"06 · 07","en":"PRACTICE OVER THEORY: politics and law study what actors actually do.","cn":"实践重于理论：政治与法学研究行动者实际做了什么。"}]},"affixes":{"intro":{"en":"Realism is one branch of the large real- family, built on a Latin word for 'thing' and expanded by a suffix for doctrines.","cn":"realism 是庞大的 real- 词族中的一支，其核心是拉丁语表示「事物」的词，再由表示学说的后缀扩展而成。"},"latinIntro":{"en":"Latin res 'thing' gives realis and realitas; English builds real, reality, realize, realism, realist and realistic on that stem.","cn":"拉丁 res「事物」给出 realis 与 realitas；英语在这一词干上构成 real、reality、realize、realism、realist 与 realistic。"},"items":[{"word":"res","structure":"res, rei (Latin noun, fifth declension)","meaning":"thing, matter, affair","meaningCN":"事物；事情；要务","example":"Res is the stem behind the whole family.","exampleCN":"res 是整个词族背后的词干。"},{"word":"realis","structure":"realis, reale (Late Latin adjective)","meaning":"of a thing; actual","meaningCN":"关于事物的；实际的","example":"Realis produced English real.","exampleCN":"realis 产生英语 real。"},{"word":"real","structure":"realis through Old French","meaning":"actually existing","meaningCN":"实际存在的","example":"The real chair stood in the corner.","exampleCN":"那把真椅子就放在角落里。"},{"word":"-ism","structure":"-ism (Greek -ismos through Latin -ismus)","meaning":"a practice, system or doctrine","meaningCN":"做法、体系或学说","example":"Realism names a doctrine about things.","exampleCN":"realism 命名一种关于事物的学说。"},{"word":"realism","structure":"real + -ism","meaning":"the doctrine or style of things as they are","meaningCN":"照事物本相的主张或风格","example":"Realism dominated the gallery.","exampleCN":"现实主义占据了画廊。"},{"word":"realist","structure":"real + -ist (person who holds a view)","meaning":"a believer in or maker of realism","meaningCN":"现实主义者；写实创作者","example":"The realist chose a factory gate.","exampleCN":"这位写实画家选择了工厂大门。"},{"word":"realistic","structure":"realist + -ic (relating to)","meaning":"true to life; sensible","meaningCN":"写实的；合乎实际的","example":"The estimate was realistic.","exampleCN":"这个估算是合乎实际的。"},{"word":"reality","structure":"real + -ity (state)","meaning":"what actually exists","meaningCN":"实际存在的事物","example":"Reality resisted the plan.","exampleCN":"现实让计划受挫。"},{"word":"realize","structure":"real + -ize (make or become)","meaning":"to make real; to understand","meaningCN":"实现；意识到","example":"They realized the design in stone.","exampleCN":"他们用石头实现了这个设计。"},{"word":"unreal","structure":"un- (not) + real","meaning":"not actual; fantastic","meaningCN":"不真实的；虚幻的","example":"The light made the street unreal.","exampleCN":"那种光让街道显得不真实。"}],"latinEntries":[{"word":"res","structure":"res, rei (f., fifth declension)","meaning":"thing, matter","meaningCN":"事物；事情"},{"word":"realis","structure":"realis, reale (adj., third declension)","meaning":"of a thing, actual","meaningCN":"关于事物的；实际的"},{"word":"realitas","structure":"realitas, realitatis (f., third declension)","meaning":"reality, actuality","meaningCN":"实在；现实性"}]}},{"word":"impressionism","ipa_uk":"/ɪmˈpreʃənɪzəm/","ipa_us":"/ɪmˈpreʃənɪzəm/","definition_zh":"印象派；印象主义","definition_en":"a style that tries to capture the immediate visual impression of light and colour rather than precise detail","core_image":"清晨的河面被短促的笔触点满，轮廓消失，只剩光在水上跳动","scene":"画家在清晨的河岸边快速落笔，只画光在水面上的瞬间变化。The painter worked quickly at the riverbank, and the result was impressionism.","sceneCN":"这里指「以瞬间光感为核心的印象派绘画」（第 1 个义项：印象派这一绘画流派）；句意为画家在河岸快速落笔，成果就是印象派。可辨识物件：河岸、画架、短笔触、水面反光。","pos":[{"tag":"n.","zh":"印象派；印象主义（绘画与音乐）"},{"tag":"n.","zh":"强调瞬间感受的创作倾向"}],"collocations":[{"phrase":"French impressionism","zh":"法国印象派"},{"phrase":"musical impressionism","zh":"音乐印象主义"},{"phrase":"a leader of impressionism","zh":"印象派的领军人物"},{"phrase":"impressionism in painting","zh":"绘画中的印象主义"},{"phrase":"the birth of impressionism","zh":"印象派的诞生"},{"phrase":"the impressionism of Monet","zh":"莫奈的印象派风格"}],"forms":[{"label":"单数形式","form":"impressionism"},{"label":"复数形式（指多种印象主义）","form":"impressionisms"},{"label":"所有格","form":"impressionism's"},{"label":"相关名词（艺术家）","form":"impressionist"}],"derivatives":[{"word":"impressionist","pos":"n./adj.","zh":"印象派画家；印象派的（由基础词干加表示「信奉者」的后缀构成，语义收窄为身份）"},{"word":"impressionistic","pos":"adj.","zh":"印象派的；印象式的（由表示印象派者的词加表示「与……有关的」后缀构成，语义偏移为性质描述）"},{"word":"impressionistically","pos":"adv.","zh":"以印象派方式地（由前一个形容词加构成副词的后缀构成，语义偏移为方式）"},{"word":"impression","pos":"n.","zh":"印象；压印（由表示「压入」的动词加表示动作结果的后缀构成，语义偏移为感受）"}],"senses":[{"no":"01","title":"The French painting movement","titleCN":"法国印象派绘画运动","definition":"the movement of French painters in the eighteen seventies who painted outdoor light with rapid broken brushwork","definitionCN":"十九世纪七十年代一批法国画家以快速破碎的笔触描绘户外光线的运动","example":"The painter worked quickly at the riverbank, and the result was impressionism.","exampleCN":"画家在河岸快速落笔，成果就是印象派。","why":"The name began as an insult. A critic seized on the title of one painting and called the whole group impressionists, and the label stuck.","whyCN":"这个名字起初是讽刺。一位评论家抓住一幅画的标题，把整个群体称为印象派，标签就此留下。"},{"no":"02","title":"Musical impressionism","titleCN":"音乐中的印象主义","definition":"a musical style that suggests atmosphere and colour through timbre and harmony rather than clear melody","definitionCN":"通过音色与和声暗示气氛与色彩、而非依靠清晰旋律的音乐风格","example":"Musical impressionism dissolves melody into colour.","exampleCN":"音乐印象主义把旋律化进色彩。","why":"Music critics borrowed the painting term for composers who worked by atmosphere. The medium changed, but the priority of sensation stayed.","whyCN":"音乐评论家借绘画术语来形容以气氛创作的作曲家。媒介变了，但对感官印象的优先次序没变。"},{"no":"03","title":"Literary impressionism","titleCN":"文学中的印象主义","definition":"a narrative style that records fleeting sensations and perceptions instead of a settled account","definitionCN":"记录短暂感觉与知觉、而非给出稳定叙述的叙事风格","example":"The novel's impressionism leaves causes unclear.","exampleCN":"这部小说的印象主义让原因显得模糊。","why":"Fiction can report events or report the mind receiving them. Impressionism chooses the second and lets the reader assemble the rest.","whyCN":"小说可以报道事件，也可以报道心灵接收事件的过程。印象主义选择后者，让读者自行拼合其余部分。"},{"no":"04","title":"Technique of catching light","titleCN":"捕捉光线的技法","definition":"the practice of using separate strokes of pure colour to make light appear to vibrate","definitionCN":"用分离的纯色笔触让光线看起来在振动的做法","example":"The water owes its glitter to impressionism, not to varnish.","exampleCN":"水面的闪烁靠的是印象派技法，而不是清漆。","why":"Colours placed side by side mix in the eye rather than on the palette. The technique is the physical basis of the style.","whyCN":"并置的颜色在眼睛里混合，而不是在调色板上混合。这一技法正是这种风格的物理基础。"},{"no":"05","title":"Priority of immediate sensation","titleCN":"优先呈现瞬间感受","definition":"a general artistic approach that values the first impression over finish, outline or detail","definitionCN":"重视第一印象、而非完成度、轮廓或细节的一般创作取向","example":"His sketches show impressionism rather than planning.","exampleCN":"他的速写显示的是印象式感受，而非事先规划。","why":"The movement's name generalized into a method: trust what the eye receives before the mind tidies it.","whyCN":"这场运动的名字一般化为一种方法：相信眼睛先接收到的，而不是心灵整理过的。"},{"no":"06","title":"Impressionist blur in photography","titleCN":"摄影与电影中的印象式模糊","definition":"the use of soft focus, blur or grain in a photograph or film to suggest a fleeting perception","definitionCN":"在照片或影片中用柔焦、模糊或颗粒暗示瞬间知觉","example":"The film's impressionism softens every street corner.","exampleCN":"这部影片的印象主义让每个街角都变柔。","why":"A lens can record sharp detail or a passing glance. Choosing softness imports the painter's priority into a mechanical medium.","whyCN":"镜头可以记录锐利细节，也可以记录匆匆一瞥。选择柔和就把画家的优先次序带进机械媒介。"},{"no":"07","title":"A critical label","titleCN":"作为评论标签","definition":"the term as used by critics to classify or dismiss a group of works","definitionCN":"评论家用来归类或贬低一批作品的说法","example":"Impressionism was first a term of abuse.","exampleCN":"印象主义最初是个贬义词。","why":"Because the label began in mockery, its later prestige shows how a hostile name can be captured by the group it attacked.","whyCN":"标签始于嘲弄，后来的声望则说明一个敌意名称如何被它所攻击的群体据为己有。"},{"no":"08","title":"Atmosphere over form","titleCN":"气氛重于形体","definition":"any approach in art that makes atmosphere and mood more important than solid form","definitionCN":"任何使气氛与情绪比坚实形体更重要的艺术取向","example":"The late landscapes drift toward impressionism.","exampleCN":"晚期风景画逐渐偏向印象主义。","why":"The most general sense drops the historical movement and keeps only the choice of atmosphere over structure.","whyCN":"最一般的义项放下历史运动，只保留「气氛重于结构」这一选择。"}],"etymology":{"intro":{"en":"Impressionism is a French coinage from the word for an impression, built on a Latin verb meaning 'to press into'. The name came from a painting's title and a hostile review. Dates are approximate.","cn":"impressionism 是法语新造词，来自表示「印象」的词，其动词在拉丁语中意为「压入」。名称源自一幅画的标题与一篇敌意评论。年代均为约数。"},"items":[{"era":"LATIN PREMERE","en":"Latin premere meant 'to press, squeeze'. Its deeper origin is source uncertain, and the root often proposed for it is a reconstructed form.","cn":"拉丁 premere 意为「压、挤」。其更深来源属「来源不确定」，常为其提出的词根属于重构形式。"},{"era":"LATIN IMPRIMERE","en":"The compound imprimere, from in- 'into' plus premere, meant 'to press into, imprint'. An impression was originally a mark pressed into a surface.","cn":"复合词 imprimere 由 in-「进入」加 premere 构成，意为「压入、印上」。impression 最初指压进表面的痕迹。"},{"era":"FRENCH IMPRESSION","en":"French impression kept the dual sense of a printed mark and a mental effect, and the second sense made the word available for art.","cn":"法语 impression 保留「印痕」与「心中效果」两层意思，后一层使这个词可以被艺术借用。"},{"era":"IMPRESSION, SUNRISE (1872)","en":"Monet titled a harbour view Impression, Sunrise. The title supplied the group's name even though the painting was meant as a sketch of light.","cn":"莫奈把一幅港口景色题作《印象·日出》。这幅画本意只是记录光线的速写，标题却提供了整个群体的名称。"},{"era":"CRITICAL REVIEW (1874)","en":"The critic Louis Leroy mocked the group as impressionists in a review of their first exhibition, and the painters later adopted the word.","cn":"评论家勒鲁瓦在评论他们的首次展览时，讥称这群人为「印象派」，画家们后来接受了这个称呼。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origin of premere is unresolved, and older Indo-European forms offered for it are reconstructed forms rather than recorded words.","cn":"来源不确定：premere 在拉丁语之前的来源没有定论，为其提出的更早印欧语形式属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but name different things; group two holds neighbouring styles.","cn":"第一组是形近或音近、却指不同事物的词；第二组是相邻的风格。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impression","ipa":"/ɪmˈpreʃən/","tag":"the source noun","definition":"a mark pressed into a surface, or an effect on the mind; impressionism is the style built on such effects.","definitionCN":"压进表面的痕迹，或对心灵的效果；印象主义是建立在这种效果上的风格。"},{"word":"impressionist","ipa":"/ɪmˈpreʃənɪst/","tag":"person or adjective","definition":"a painter of the group, or an adjective for their style; impressionism is the movement's name.","definitionCN":"该群体的画家，或形容其风格的形容词；impressionism 是运动的名称。"},{"word":"impressionistic","ipa":"/ˌɪmpreʃəˈnɪstɪk/","tag":"quality adjective","definition":"vague, atmospheric or loosely observed; it often describes a report rather than a painting.","definitionCN":"模糊的、重气氛的或观察粗略的；常形容报道而非绘画。"},{"word":"expressionism","ipa":"/ɪkˈspreʃənɪzəm/","tag":"different movement","definition":"a style that distorts form to express inner feeling; it sounds close but begins from ex- 'out', not in- 'into'.","definitionCN":"通过扭曲形体表达内心感受的风格；听起来相近，但其前缀是 ex-「向外」，而非 in-「向内」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pointillism","ipa":"/ˈpɔɪntɪlɪzəm/","tag":"technique branch","definition":"painting with small dots of pure colour; it shares the optical mixing of impressionism but is more systematic.","definitionCN":"用纯色小点作画；与印象主义共享光学混色，但更系统化。"},{"word":"post-impressionism","ipa":"/ˌpəʊst ɪmˈpreʃənɪzəm/","tag":"successor","definition":"the generation after impressionism that kept bright colour but restored structure and personal expression.","definitionCN":"印象主义之后的一代，保留明亮色彩，却恢复结构与个人表达。"},{"word":"luminism","ipa":"/ˈluːmɪnɪzəm/","tag":"light-centred","definition":"an American style devoted to clear, glowing light and stillness; it shares the subject of light but not the broken stroke.","definitionCN":"致力于清澈发光的光线与静谧的美国风格；共享光这一主题，却不用破碎笔触。"},{"word":"tonalism","ipa":"/ˈtəʊnəlɪzəm/","tag":"mood-centred","definition":"a style of soft, muted tones and atmosphere; it also prefers mood to detail but avoids bright broken colour.","definitionCN":"以柔和黯淡色调与气氛为主的风格；同样重情绪轻细节，但避免明亮的破碎色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The word is impression plus -ism, so the style is the doctrine of the first impression.","cn":"这个词是在 impression 之后加表示学说的后缀，所以这种风格就是「第一印象」的主义。"},{"en":"Impression itself comes from a verb meaning 'press into', like a mark pressed into wax.","cn":"impression 本身来自意为「压入」的动词，就像压进蜡里的痕迹。"},{"en":"The name came from a painting title and a mocking review, which is why it was once an insult.","cn":"名称来自一幅画的标题与一篇嘲讽评论，因此它曾是贬义词。"},{"en":"Fixed phrases mark its spread: French, musical, literary, photographic.","cn":"固定搭配标出它的扩散：法国的、音乐的、文学的、摄影的。"},{"en":"Impressionist is the painter; impressionistic is the quality.","cn":"impressionist 指画家；impressionistic 指性质。"}],"abstract":[{"en":"Picture a scene that exists only for the second the light lasts.","cn":"想象一个只存在于光线持续的那一秒的场景。"},{"en":"Picture colours that mix in your eye rather than on the palette.","cn":"想象颜色在眼睛里混合，而不是在调色板上混合。"},{"en":"Picture an insult that a group decided to wear as a badge.","cn":"想象一句侮辱，被一个群体决定当作徽章戴上。"}]},"examples":[{"en":"Impressionism changed how painters treated shadow and water.","cn":"印象派改变了画家处理阴影与水面的方式。"},{"en":"The critic's attack gave impressionism its name.","cn":"那位评论家的攻击给了印象派名字。"},{"en":"Her later work moves from impressionism toward abstraction.","cn":"她后期的作品从印象派走向抽象。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「印象 + 主义」—— 只画眼睛第一眼收到的感觉 → 印象派","word":"impressionism"},"root":"法语 impressionnisme，来自 impression，上溯至拉丁 impressio 与动词 imprimere（in-「进入」+ premere「压」）。名称源自莫奈画题《印象·日出》与一八七四年评论家的讥评。premere 更早来源不确定。","sensesIntro":{"en":"Eight senses follow one priority: record the sensation before the mind corrects it. Painting, music, fiction, technique, photography and criticism each apply that priority in a different medium.","cn":"八个义项围绕同一个优先次序展开：在心灵修正之前先记录感官印象。绘画、音乐、小说、技法、摄影与评论各自在不同媒介中实行这一优先。"},"semanticMap":{"core":{"en":"CORE IMAGE: a few dozen strokes of light on water, with no outline at all.","cn":"核心意象：水面上几十笔光，全无轮廓。"},"chain":["FIRST SENSATION","BROKEN STROKE","OPTICAL MIXING","ATMOSPHERE","CRITICAL LABEL","GLOBAL STYLE"],"branches":[{"senses":"01","en":"THE MOVEMENT: a group of painters turns a shared technique into a named school.","cn":"运动：一群画家把共同技法变成有名号的流派。"},{"senses":"02 · 03","en":"OTHER MEDIA: music and fiction borrow the same priority of sensation.","cn":"其他媒介：音乐与小说借用同样的感官优先。"},{"senses":"04","en":"THE TECHNIQUE: separate colours mix in the eye, which is how the effect is made.","cn":"技法：分离的颜色在眼中混合，效果由此产生。"},{"senses":"05 · 06","en":"THE METHOD: immediate sensation and soft photographic focus generalize the approach.","cn":"方法：瞬间感受与摄影的柔焦把这一取向一般化。"},{"senses":"07 · 08","en":"THE LABEL AND THE MOOD: a hostile name becomes a style, and atmosphere outranks form.","cn":"标签与气氛：敌意名称变成风格，气氛压过形体。"}]},"affixes":{"intro":{"en":"Impressionism sits inside the press- family: a Latin verb for pressing gives impression, and the suffix for doctrines turns it into a movement.","cn":"impressionism 属于「压」这一词族：拉丁语表示按压的动词给出 impression，表示学说的后缀又把它变成一场运动。"},"latinIntro":{"en":"Latin premere and its compound imprimere give impression, impress and imprint; the suffix -ism marks the doctrine.","cn":"拉丁 premere 及其复合词 imprimere 给出 impression、impress 与 imprint；表示学说的后缀标记其主义身份。"},"items":[{"word":"premere","structure":"premere, pressi, pressum (Latin verb, third conjugation)","meaning":"to press, squeeze","meaningCN":"压；挤","example":"Premere is the base of the whole family.","exampleCN":"premere 是整个词族的基础。"},{"word":"imprimere","structure":"in- 'into' + premere","meaning":"to press into, imprint","meaningCN":"压入；印上","example":"Imprimere gave French imprimer.","exampleCN":"imprimere 给出法语 imprimer。"},{"word":"impressio","structure":"impressio, impressionis (Latin noun)","meaning":"a pressing into; an impression","meaningCN":"压入；印象","example":"Impressio is the source of impression.","exampleCN":"impressio 是 impression 的来源。"},{"word":"impression","structure":"French impression, from Latin impressio","meaning":"a mark; an effect on the mind","meaningCN":"印记；心中效果","example":"The first impression lasted.","exampleCN":"第一印象持续了很久。"},{"word":"-ism","structure":"-ism (Greek -ismos through Latin -ismus)","meaning":"a practice or doctrine","meaningCN":"做法或学说","example":"The suffix turns a word into a movement.","exampleCN":"这个后缀把一个词变成一场运动。"},{"word":"impressionism","structure":"impression + -ism","meaning":"the style of immediate sensation","meaningCN":"重瞬间感受的风格","example":"Impressionism changed painting.","exampleCN":"印象派改变了绘画。"},{"word":"impressionist","structure":"impression + -ist (person)","meaning":"a painter of the group","meaningCN":"印象派画家","example":"The impressionist painted outdoors.","exampleCN":"这位印象派画家在户外作画。"},{"word":"impressionistic","structure":"impressionist + -ic (relating to)","meaning":"loose, atmospheric","meaningCN":"印象式的；重气氛的","example":"The account is impressionistic.","exampleCN":"这段叙述是印象式的。"},{"word":"impress","structure":"im- + press","meaning":"to make a mark or a strong effect","meaningCN":"留下印记；给人深刻印象","example":"The light impressed itself on the canvas.","exampleCN":"光线在画布上留下了自己的印记。"}],"latinEntries":[{"word":"premere","structure":"premere, pressi, pressum (verb, third conjugation)","meaning":"to press","meaningCN":"压"},{"word":"impressio","structure":"impressio, impressionis (f., third declension)","meaning":"a pressing into; an impression","meaningCN":"压入；印象"},{"word":"impressus","structure":"impressus, impressa, impressum (participle)","meaning":"pressed into","meaningCN":"被压入的"}]}},{"word":"expressionism","ipa_uk":"/ɪkˈspreʃənɪzəm/","ipa_us":"/ɪkˈspreʃənɪzəm/","definition_zh":"表现主义","definition_en":"a style that distorts shape and colour to express inner feeling rather than to record outer appearance","core_image":"人脸被涂成刺眼的绿与橙，形体扭曲，像情绪把形状撑破","scene":"画家把天空画成旋涡，把街道压成斜线，让恐惧直接冲出画面。The painter twisted the sky into a spiral and tilted the street, and the style was called expressionism.","sceneCN":"这里指「以扭曲形体表达内心情绪的表现主义」（第 1 个义项：表现主义绘画流派）；句意为画家把天空扭成旋涡、把街道压斜，这种风格被称为表现主义。可辨识物件：旋涡天空、倾斜街道、扭曲人脸、浓烈颜色。","pos":[{"tag":"n.","zh":"表现主义（绘画、文学、音乐等）"},{"tag":"n.","zh":"强调表达内心感受的创作倾向"}],"collocations":[{"phrase":"German expressionism","zh":"德国表现主义"},{"phrase":"expressionism in painting","zh":"绘画中的表现主义"},{"phrase":"the rise of expressionism","zh":"表现主义的兴起"},{"phrase":"expressionism in film","zh":"电影中的表现主义"},{"phrase":"a work of expressionism","zh":"一件表现主义作品"},{"phrase":"expressionism and impressionism","zh":"表现主义与印象主义"}],"forms":[{"label":"单数形式","form":"expressionism"},{"label":"复数形式（指多种表现主义）","form":"expressionisms"},{"label":"所有格","form":"expressionism's"},{"label":"相关名词（艺术家）","form":"expressionist"}],"derivatives":[{"word":"expressionist","pos":"n./adj.","zh":"表现主义艺术家；表现主义的（由基础词干加表示「信奉者」的后缀构成，语义收窄为身份）"},{"word":"expressionistic","pos":"adj.","zh":"表现主义的；表现式的（由表示表现主义者之词加表示「与……有关的」后缀构成，语义偏移为性质描述）"},{"word":"expressionistically","pos":"adv.","zh":"以表现主义方式地（由前一个形容词加构成副词的后缀构成，语义偏移为方式）"},{"word":"expression","pos":"n.","zh":"表达；表情（由表示「压出」的动词加表示动作结果的后缀构成，语义偏移为外在表现）"}],"senses":[{"no":"01","title":"The early twentieth-century movement","titleCN":"二十世纪初的表现主义运动","definition":"the art movement of the early twentieth century that distorted form and colour to express intense feeling","definitionCN":"二十世纪初通过扭曲形体与色彩表达强烈情感的艺术运动","example":"The painter twisted the sky and tilted the street, and the style was called expressionism.","exampleCN":"画家把天空扭成旋涡、把街道压斜，这种风格被称为表现主义。","why":"The word comes from a verb meaning 'press out'. The movement wanted feeling to come out of the artist and into the shape, even at the cost of accuracy.","whyCN":"这个词来自意为「压出」的动词。这场运动要让情感从艺术家体内压进形体，即使牺牲准确也在所不惜。"},{"no":"02","title":"German expressionism","titleCN":"德国表现主义","definition":"the German groups of the early twentieth century that used harsh colour and angular form to attack modern city life","definitionCN":"二十世纪初以刺目色彩与尖锐形体批判现代城市生活的德国团体","example":"German expressionism painted the city as a scream.","exampleCN":"德国表现主义把城市画成一声尖叫。","why":"In Germany the movement took a sharply critical tone, because industrial cities and war made the inner life feel under attack.","whyCN":"在德国，这场运动带有尖锐的批判语气，因为工业城市与战争让内心生活感觉受到攻击。"},{"no":"03","title":"Expressionism in music","titleCN":"音乐中的表现主义","definition":"a musical style that uses harsh intervals and extreme dynamics to express anxiety and inner conflict","definitionCN":"用刺耳音程与极端力度表达焦虑与内心冲突的音乐风格","example":"The string quartet carries expressionism to the edge of hearing.","exampleCN":"这首弦乐四重奏把表现主义推到听觉的边缘。","why":"Music need not depict anything, so expressionism there drops representation entirely and works directly on the listener's nerves.","whyCN":"音乐无需描绘任何对象，因此音乐中的表现主义完全放下再现，直接作用于听者的神经。"},{"no":"04","title":"Theatre and film expressionism","titleCN":"戏剧与电影中的表现主义","definition":"a staging and film style of exaggerated sets, shadows and gestures that externalises mental states","definitionCN":"用夸张布景、阴影与动作把心理状态外化的舞台与电影风格","example":"Film expressionism bends the walls of the room.","exampleCN":"电影表现主义把房间的墙壁弯折。","why":"A skewed set can show a character's mind more directly than a realistic room, so theatre and cinema used distortion as psychology.","whyCN":"倾斜的布景能比写实房间更直接地呈现人物心理，因此戏剧与电影把扭曲当作心理学手段。"},{"no":"05","title":"Literary expressionism","titleCN":"文学中的表现主义","definition":"a literary style of intense, fragmented speech that projects inner crisis rather than describing events","definitionCN":"以强烈、破碎的语言投射内心危机、而非叙述事件的文学风格","example":"The novella's expressionism breaks sentences into cries.","exampleCN":"这部中篇的表现主义把句子拆成呼喊。","why":"Language can report or erupt. Expressionist writing chooses eruption, so grammar is sacrificed for pressure of feeling.","whyCN":"语言可以报道，也可以爆发。表现主义写作选择爆发，因此为了情感压力而牺牲语法。"},{"no":"06","title":"Expressionist architecture","titleCN":"表现主义建筑","definition":"an architecture of sculptural, distorted forms that express movement or emotion rather than structural logic","definitionCN":"以雕塑般扭曲形体表达动势或情绪、而非结构逻辑的建筑","example":"The brick tower is expressionism made habitable.","exampleCN":"那座砖塔是可以住人的表现主义。","why":"Buildings usually show how they stand. Expressionist buildings hide that logic in favour of a shape that feels like motion.","whyCN":"建筑通常显露自己如何站立。表现主义建筑却把这种逻辑藏起来，偏爱一种像在运动的外形。"},{"no":"07","title":"The general principle","titleCN":"一般原则：把内心状态外化","definition":"any artistic practice that lets inner state determine form, regardless of subject or period","definitionCN":"让内心状态决定形式、不分题材与时期的一切创作实践","example":"His portraits are expressionism before the movement existed.","exampleCN":"他的肖像画在运动出现之前就已是表现主义。","why":"The historical movement named a permanent option in art: shape may follow feeling rather than fact.","whyCN":"这场历史运动命名了艺术中一个永久选项：形体可以跟随感受，而不必跟随事实。"},{"no":"08","title":"An applied critical label","titleCN":"被广泛套用的评论标签","definition":"the term used loosely by critics for any work with violent colour or distorted form","definitionCN":"评论家宽松地用来指任何色彩激烈或形体扭曲的作品","example":"Critics slapped expressionism on every loud canvas that year.","exampleCN":"那一年，评论家给每幅喧闹的画都贴上表现主义标签。","why":"When a movement becomes famous, its name turns into a convenient adjective. Loose use marks enthusiasm rather than analysis.","whyCN":"一场运动出名之后，它的名字就成了方便的形容词。宽松使用标记的是热情，而不是分析。"}],"etymology":{"intro":{"en":"Expressionism comes from the Latin verb for pressing out, through the noun expression. The art term was formed in the early twentieth century, partly after German usage. Dates are approximate.","cn":"expressionism 经名词 expression 来自拉丁语表示「压出」的动词。艺术术语形成于二十世纪初，部分沿用了德语用法。年代均为约数。"},"items":[{"era":"LATIN PREMERE","en":"Latin premere meant 'to press'. Its deeper origin is source uncertain, and any older root proposed for it is a reconstructed form.","cn":"拉丁 premere 意为「压」。其更深来源属「来源不确定」，为其提出的更早词根属于重构形式。"},{"era":"LATIN EXPRIMERE","en":"Exprimere, from ex- 'out' plus premere, meant 'to press out', like juice from a fruit. The image is force applied until something comes out.","cn":"exprimere 由 ex-「向外」加 premere 构成，意为「压出」，如从果实压出汁液。意象是施力直到有东西出来。"},{"era":"LATIN EXPRESSIO","en":"Expressio meant 'a pressing out' and then 'a representation'. The physical and mental senses travelled together.","cn":"expressio 意为「压出」，后指「表现」。物理义与心理义一同流传。"},{"era":"ENGLISH EXPRESSION","en":"English expression arrived through French with both senses: the act of showing and the look on a face.","cn":"英语 expression 经法语而来，同时带两层意思：展示的动作与脸上的神情。"},{"era":"GERMAN EXPRESSIONISMUS (C. 1910)","en":"German critics and artists used Expressionismus for the new art of distortion, and other languages borrowed the term in the same decade.","cn":"德国评论家与艺术家用 Expressionismus 指这种以扭曲为特征的新艺术，其他语言在同一个十年里借入该词。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origin of premere is unresolved, so older forms offered for it are reconstructed forms rather than recorded words.","cn":"来源不确定：premere 在拉丁语之前的来源没有定论，为其提出的更早形式属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds look-alike and sound-alike words that are often confused; group two holds neighbouring movements.","cn":"第一组是常被混淆的形近、音近词；第二组是相邻的艺术运动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impressionism","ipa":"/ɪmˈpreʃənɪzəm/","tag":"different prefix","definition":"the style that records the impression received from outside; expressionism turns the other way and presses feeling outward.","definitionCN":"记录从外部收到的印象的风格；表现主义方向相反，把感受向外压出。"},{"word":"expression","ipa":"/ɪkˈspreʃən/","tag":"the source noun","definition":"the act of showing feeling, or a look on a face; expressionism is the style built on this idea.","definitionCN":"展示感受的动作，或脸上的神情；表现主义是建立在这一观念上的风格。"},{"word":"expressionist","ipa":"/ɪkˈspreʃənɪst/","tag":"person or adjective","definition":"an artist of the movement, or an adjective for the style; expressionism is the movement's name.","definitionCN":"这场运动中的艺术家，或形容该风格的形容词；expressionism 是运动名称。"},{"word":"expressive","ipa":"/ɪkˈspresɪv/","tag":"quality adjective","definition":"full of feeling or meaning; it describes any effective sign, not specifically the movement.","definitionCN":"充满感情或意味的；它描述任何有效表达，并不特指这场运动。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fauvism","ipa":"/ˈfəʊvɪzəm/","tag":"colour-led","definition":"the French movement of wild, non-natural colour; it shares expressive colour but keeps recognizable subjects.","definitionCN":"以狂野、非自然色彩为特征的法国运动；共享表现性色彩，但保留可辨识的题材。"},{"word":"surrealism","ipa":"/səˈrɪəlɪzəm/","tag":"dream logic","definition":"a movement that joins realistic detail with dreamlike juxtaposition to reach the unconscious.","definitionCN":"把写实细节与梦境般并置结合起来、以触及无意识的运动。"},{"word":"symbolism","ipa":"/ˈsɪmbəlɪzəm/","tag":"suggestion","definition":"a movement that suggests inner states through symbols and atmospheres rather than direct statement.","definitionCN":"通过象征与气氛暗示内心状态、而非直接陈述的运动。"},{"word":"abstract expressionism","ipa":"/ˈæbstrækt ɪkˈspreʃənɪzəm/","tag":"later movement","definition":"the mid twentieth-century painting of large gesture and paint as feeling; it inherits expressionism but drops the figure.","definitionCN":"二十世纪中叶以大幅笔势与颜料本身表达情绪的画派；继承表现主义，却放下人物形象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means 'press out', like squeezing juice from fruit, and the style squeezes feeling out of the artist.","cn":"词根意为「压出」，像从果实挤汁；这种风格把感受从艺术家体内挤出。"},{"en":"Expression is the noun; expressionism is the doctrine built on it.","cn":"expression 是名词；expressionism 是建立其上的主义。"},{"en":"The prefix ex- means out, which is the exact opposite of impressionism's in-.","cn":"前缀 ex- 意为「向外」，正好与印象主义的前缀 in-「向内」相反。"},{"en":"Fixed phrases mark its media: painting, music, theatre, film, architecture.","cn":"固定搭配标出它的媒介：绘画、音乐、戏剧、电影、建筑。"},{"en":"An expressionist is the maker; expressionistic is the quality.","cn":"expressionist 指创作者；expressionistic 指性质。"}],"abstract":[{"en":"Picture a face painted green because fear is green, not because skin is.","cn":"想象一张涂成绿色的脸，因为恐惧是绿的，而不是皮肤是绿的。"},{"en":"Picture a room whose walls lean in to show that the occupant feels trapped.","cn":"想象一间墙壁向内倾斜的房间，以表现居住者感到被困。"},{"en":"Picture a scream that takes the shape of a street.","cn":"想象一声尖叫长成了街道的形状。"}]},"examples":[{"en":"Expressionism turned anxiety into angular lines.","cn":"表现主义把焦虑变成尖锐的线条。"},{"en":"The film uses expressionism to show the character's panic.","cn":"这部影片用表现主义呈现人物的惊慌。"},{"en":"Critics once used expressionism as a term of blame.","cn":"评论家曾把表现主义当作指责用语。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「把内心的东西压出来 + 主义」—— 形体跟着情绪扭曲 → 表现主义","word":"expressionism"},"root":"经英语 expression 上溯至拉丁 expressio 与动词 exprimere（ex-「向外」+ premere「压」），本义「压出」。艺术术语形成于二十世纪初，部分沿用德语 Expressionismus。premere 更早来源不确定。","sensesIntro":{"en":"Eight senses follow one outward pressure: paint, music, stage, fiction and building all let inner feeling bend the form. The last two senses show the idea becoming a general option and then a loose label.","cn":"八个义项围绕同一种向外的压力展开：绘画、音乐、舞台、小说与建筑都让内心感受压弯形式。最后两个义项显示这一观念先成为普遍选项，再成为宽松标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a face coloured by feeling, not by skin, with form bent outward from inside.","cn":"核心意象：一张被情绪而非皮肤决定颜色的脸，形体由内向外被撑弯。"},"chain":["INNER STATE","PRESSURE OUTWARD","DISTORTED FORM","SHARED MOVEMENT","LOOSE LABEL","MODERN ECHO"],"branches":[{"senses":"01 · 02","en":"THE MOVEMENT: early twentieth-century art, especially in Germany, turns inner pressure into harsh colour and angle.","cn":"运动：二十世纪初的艺术，尤其在德国，把内心压力变成刺目色彩与尖角。"},{"senses":"03 · 05","en":"SOUND AND WORD: music and literature express the same pressure without any depicted object.","cn":"声音与文字：音乐与文学在没有任何描绘对象的情况下表达同样的压力。"},{"senses":"04","en":"STAGE AND SCREEN: skewed sets and shadows make a mind visible in space.","cn":"舞台与银幕：倾斜布景与阴影让心灵在空间中可见。"},{"senses":"06","en":"BUILDING: architecture hides structural logic to make a form that feels like motion.","cn":"建筑：建筑藏起结构逻辑，做出一种像在运动的形体。"},{"senses":"07 · 08","en":"BEYOND THE PERIOD: the principle can appear in any era, and the name can be applied loosely by critics.","cn":"超越时期：这一原则可出现在任何时代，名称也可被评论家宽松套用。"}]},"affixes":{"intro":{"en":"Expressionism belongs to the press-out family, a branch of the same Latin verb that gives impression. The prefix decides the direction.","cn":"expressionism 属于「压出」词族，与 impression 同出一个拉丁动词。前缀决定方向。"},"latinIntro":{"en":"Latin premere gives press and print; its compound exprimere gives express, expression and expressive, while imprimere gives impression and imprint.","cn":"拉丁 premere 给出 press 与 print；其复合词 exprimere 给出 express、expression 与 expressive，而 imprimere 给出 impression 与 imprint。"},"items":[{"word":"premere","structure":"premere, pressi, pressum (Latin verb, third conjugation)","meaning":"to press","meaningCN":"压","example":"Premere is shared by both movements' words.","exampleCN":"两个运动的词都共享 premere。"},{"word":"exprimere","structure":"ex- 'out' + premere","meaning":"to press out","meaningCN":"压出","example":"Exprimere names the outward direction.","exampleCN":"exprimere 标出向外的方向。"},{"word":"expressio","structure":"expressio, expressionis (Latin noun)","meaning":"a pressing out; a representation","meaningCN":"压出；表现","example":"Expressio is the source of expression.","exampleCN":"expressio 是 expression 的来源。"},{"word":"express","structure":"ex- + press","meaning":"to put into words or signs","meaningCN":"用语言或符号表达","example":"The painting expresses fear.","exampleCN":"这幅画表达了恐惧。"},{"word":"expression","structure":"express + -ion (result)","meaning":"the act of showing feeling","meaningCN":"展示感受的行为","example":"Her expression changed at once.","exampleCN":"她的表情立刻变了。"},{"word":"expressive","structure":"express + -ive (tending to)","meaning":"full of feeling","meaningCN":"富于表现力的","example":"The lines are highly expressive.","exampleCN":"这些线条极具表现力。"},{"word":"-ism","structure":"-ism (Greek -ismos through Latin -ismus)","meaning":"a doctrine or movement","meaningCN":"学说或运动","example":"The suffix turned expression into a movement.","exampleCN":"这个后缀把表达变成一场运动。"},{"word":"expressionism","structure":"expression + -ism","meaning":"the style of outward emotional form","meaningCN":"把情感外化为形体的风格","example":"Expressionism distorts to reveal.","exampleCN":"表现主义以扭曲来揭示。"},{"word":"expressionist","structure":"expression + -ist (person)","meaning":"an artist of the movement","meaningCN":"表现主义艺术家","example":"The expressionist used violent red.","exampleCN":"这位表现主义画家用了激烈的红色。"},{"word":"expressionistic","structure":"expressionist + -ic (relating to)","meaning":"distorted for feeling","meaningCN":"为表达情绪而扭曲的","example":"The set is expressionistic.","exampleCN":"这套布景是表现主义的。"}],"latinEntries":[{"word":"premere","structure":"premere, pressi, pressum (verb, third conjugation)","meaning":"to press","meaningCN":"压"},{"word":"exprimere","structure":"exprimere, expressi, expressum (verb, third conjugation)","meaning":"to press out","meaningCN":"压出"},{"word":"expressio","structure":"expressio, expressionis (f., third declension)","meaning":"a pressing out; expression","meaningCN":"压出；表现"}]}},{"word":"abstract art","ipa_uk":"/ˈæbstrækt ɑːt/","ipa_us":"/ˈæbstrækt ɑːrt/","definition_zh":"抽象艺术；抽象派艺术","definition_en":"art that does not try to show recognizable objects but works with colour, line, shape and form","core_image":"画布上没有桌子也没有人脸，只有一块红、一条弧线与一片蓝彼此推挤","scene":"画家不再画任何可辨认的物体，只用色块与线条让画面自己站住。The painter stopped painting recognizable objects and used only colour fields and lines, producing abstract art.","sceneCN":"这里指「不描绘可辨认物象的艺术」（第 1 个义项：抽象艺术这一门类）；句意为画家不再画可辨认物体，只用色块与线条，创作出抽象艺术。可辨识物件：色块、线条、空画布、画笔。","pos":[{"tag":"n.","zh":"抽象艺术（作为门类）"},{"tag":"n.","zh":"抽象艺术作品（单件或集合）"}],"collocations":[{"phrase":"an abstract art exhibition","zh":"抽象艺术展"},{"phrase":"geometric abstract art","zh":"几何抽象艺术"},{"phrase":"the abstract art movement","zh":"抽象艺术运动"},{"phrase":"a piece of abstract art","zh":"一件抽象艺术作品"},{"phrase":"abstract art and realism","zh":"抽象艺术与现实主义"},{"phrase":"the rise of abstract art","zh":"抽象艺术的兴起"}],"forms":[{"label":"单数形式","form":"abstract art"},{"label":"复数形式（指多个门类或作品）","form":"abstract arts"},{"label":"所有格","form":"abstract art's"},{"label":"定语用法","form":"abstract-art"}],"derivatives":[{"word":"abstraction","pos":"n.","zh":"抽象化；抽象作品（由基础词加表示动作或结果的后缀构成，语义偏移为过程与成品）"},{"word":"abstractly","pos":"adv.","zh":"抽象地（由基础词加构成副词的后缀构成，语义偏移为方式）"},{"word":"abstractness","pos":"n.","zh":"抽象性（由基础词加表示性质的后缀构成，语义偏移为程度）"},{"word":"abstracted","pos":"adj.","zh":"心不在焉的；被抽离的（由基础词加表示「处于……状态」的后缀构成，语义偏移为神情）"}],"senses":[{"no":"01","title":"Art without a recognizable subject","titleCN":"不描绘可辨认物象的艺术","definition":"art that does not attempt to represent objects in the visible world","definitionCN":"不试图再现可见世界中物体的艺术","example":"The painter used only colour fields and lines, producing abstract art.","exampleCN":"画家只用色块与线条，创作出抽象艺术。","why":"The word means 'drawn away'. The subject has been pulled out, leaving colour, line and shape to work on their own.","whyCN":"这个词意为「被抽走」。题材被抽走之后，颜色、线条与形状便独自发挥作用。"},{"no":"02","title":"Non-objective painting","titleCN":"非对象性绘画","definition":"painting that refers to nothing outside itself, associated with early twentieth-century pioneers","definitionCN":"不指向自身之外任何事物的绘画，与二十世纪初的先驱相关","example":"Early abstract art abandoned the model entirely.","exampleCN":"早期抽象艺术完全放弃了模特。","why":"Non-objective painters argued that a picture need not point at anything. Music had long worked this way, and painting followed.","whyCN":"非对象性画家主张，一幅画不必指向任何东西。音乐早已如此运作，绘画随后跟上。"},{"no":"03","title":"Geometric abstraction","titleCN":"几何抽象","definition":"abstraction built from precise squares, circles and grids rather than loose gesture","definitionCN":"由精确的方块、圆与网格而非松散笔势构成的抽象","example":"The wall is pure geometric abstract art.","exampleCN":"这面墙是纯粹的几何抽象艺术。","why":"Geometry offers a shared, rational vocabulary. Painters used it to make order visible without depicting any object.","whyCN":"几何提供一套共享而理性的词汇。画家用它让秩序可见，却不描绘任何物体。"},{"no":"04","title":"Abstract expressionism, loosely","titleCN":"宽泛意义上的抽象表现主义","definition":"the mid twentieth-century painting of large gesture and field, often grouped under the phrase","definitionCN":"二十世纪中叶以大幅笔势与色域为主的绘画，常被归入这一说法","example":"The gallery calls the splashed canvases abstract art.","exampleCN":"画廊把这些泼洒的画布称为抽象艺术。","why":"When gesture replaced the figure, critics needed a broad label, so the older phrase absorbed the newer movement.","whyCN":"当笔势取代人物，评论家需要一个宽泛标签，于是旧短语吸收了新运动。"},{"no":"05","title":"Abstract sculpture","titleCN":"抽象雕塑","definition":"three-dimensional work that explores mass, space and balance without representing a figure","definitionCN":"探索体量、空间与平衡、却不表现具体形象的三维作品","example":"The plaza holds abstract art in steel.","exampleCN":"广场上立着钢制的抽象艺术。","why":"Sculpture has weight and space even without a subject, so abstraction can be felt bodily rather than read as a picture.","whyCN":"雕塑即使没有题材也有重量与空间，因此抽象可以被身体感到，而不必被读成一幅画。"},{"no":"06","title":"Abstraction in design and pattern","titleCN":"设计与图案中的抽象","definition":"the use of simplified non-representational pattern in textiles, graphics and interiors","definitionCN":"在织物、平面与室内设计中使用简化的非再现图案","example":"The carpet repeats abstract art in wool.","exampleCN":"地毯用羊毛重复了抽象艺术。","why":"Once abstraction became a visual language, it moved from gallery to surface, where pattern matters more than authorship.","whyCN":"抽象一旦成为视觉语言，就从画廊移到表面；在表面上，图案比作者身份更重要。"},{"no":"07","title":"Abstraction as inner necessity","titleCN":"作为内在必然的抽象","definition":"the early belief that abstract form expresses spiritual or emotional necessity rather than decoration","definitionCN":"早期的一种信念：抽象形式表达精神或情感的必然，而非装饰","example":"The first abstract art was a spiritual programme.","exampleCN":"最早的抽象艺术是一套精神纲领。","why":"Pioneers did not want empty decoration. They believed colour and shape could speak directly to the inner life, without any object as a middleman.","whyCN":"先驱们并不想要空洞装饰。他们相信颜色与形状能直接对内心说话，不需要任何物体作中间人。"},{"no":"08","title":"A contested category","titleCN":"有争议的类别","definition":"the phrase as a disputed label argued over by artists, critics and audiences","definitionCN":"被艺术家、评论家与观众争论不休的标签","example":"What counts as abstract art is still argued.","exampleCN":"什么算抽象艺术至今仍有争论。","why":"If art need not depict, then the boundary of the category is open. The phrase often marks an argument rather than a settled class.","whyCN":"如果艺术不必描绘，那么类别的边界就是敞开的。这个短语常标记一场争论，而不是一个定论。"}],"etymology":{"intro":{"en":"Abstract art joins a Latin participle meaning 'drawn away' with the Latin word for skill. The phrase is a twentieth-century formation, though both halves are old. Dates are approximate.","cn":"abstract art 把一个意为「被抽走」的拉丁分词与表示「技艺」的拉丁词并在一起。短语形成于二十世纪，但两半都很古老。年代均为约数。"},"items":[{"era":"LATIN TRAHERE","en":"Latin trahere meant 'to draw, pull, drag'. Its deeper origin is source uncertain, and the root often proposed for it is a reconstructed form.","cn":"拉丁 trahere 意为「拉、拖、牵引」。其更深来源属「来源不确定」，常为其提出的词根属于重构形式。"},{"era":"LATIN ABSTRAHERE","en":"Abstrahere, from abs- 'away' plus trahere, meant 'to draw away, detach'. The mind draws a quality away from the object that has it.","cn":"abstrahere 由 abs-「离开」加 trahere 构成，意为「抽走、分离」。心灵把某种性质从拥有它的物体上抽出来。"},{"era":"LATIN ABSTRACTUS","en":"The participle abstractus 'drawn away' entered English as abstract, first for qualities considered apart from things.","cn":"分词 abstractus「被抽走的」进入英语作 abstract，最初指被抽离事物来考虑的性质。"},{"era":"ENGLISH ABSTRACT","en":"By the seventeenth century abstract could mean both a summary and a quality separated from matter; the artistic sense came much later.","cn":"到十七世纪，abstract 既可指摘要，也可指脱离物质的性质；艺术义要晚得多。"},{"era":"TWENTIETH-CENTURY PHRASE","en":"Abstract art became the standard term when painters and sculptors stopped using a visible subject altogether.","cn":"当画家与雕塑家完全停止使用可见题材，abstract art 才成为标准说法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Latin origin of trahere is unresolved, so older forms offered for it are reconstructed forms rather than recorded words.","cn":"来源不确定：trahere 在拉丁语之前的来源没有定论，为其提出的更早形式属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms of the same word that are easily confused; group two holds names for non-representational practices.","cn":"第一组是同一个词的不同形式，容易混淆；第二组是非再现性实践的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"abstract","ipa":"/ˈæbstrækt/","tag":"adjective or verb","definition":"existing as a quality rather than an object, or the act of removing something; abstract art is the field.","definitionCN":"作为性质而非物体存在，或取走某物的动作；abstract art 指领域。"},{"word":"abstraction","ipa":"/æbˈstrækʃən/","tag":"process or work","definition":"the act of drawing something away, or an abstract work; it names the process, while abstract art names the category.","definitionCN":"抽取的动作，或一件抽象作品；它指过程，而 abstract art 指类别。"},{"word":"abstracted","ipa":"/æbˈstræktɪd/","tag":"different sense","definition":"distracted or lost in thought; the word kept the idea of being drawn away, but from the present moment.","definitionCN":"分心的；出神的。这个词保留了「被抽走」的意思，只是抽离的对象变成了当下。"},{"word":"attract","ipa":"/əˈtrækt/","tag":"same root, opposite prefix","definition":"to pull toward; it uses the same Latin verb for drawing but with ad- 'to' instead of abs- 'away'.","definitionCN":"吸引；它使用同一个表示「拉」的拉丁动词，但前缀是 ad-「向」而非 abs-「离」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"non-objective art","ipa":"/nɒn əbˈdʒektɪv ɑːt/","tag":"stricter term","definition":"art that refers to no object at all; it is stricter than abstract art, which can still start from a real subject.","definitionCN":"完全不指向任何对象的艺术；比抽象艺术更严格，因为后者仍可从真实题材出发。"},{"word":"concrete art","ipa":"/kənˈkriːt ɑːt/","tag":"geometric branch","definition":"a term for purely geometric construction with no reference to nature; it rejects the word abstract as too vague.","definitionCN":"指纯几何构造、不参照自然的说法；它认为「抽象」一词过于含糊而拒绝使用。"},{"word":"minimalism","ipa":"/ˈmɪnɪməlɪzəm/","tag":"reduction","definition":"a later movement reducing art to simple forms and materials; it is narrower and more austere than abstract art.","definitionCN":"较晚的运动，把艺术减到简单形式与材料；比抽象艺术更窄、更严峻。"},{"word":"realism","ipa":"/ˈriːəlɪzəm/","tag":"the opposite","definition":"the style of showing things as they appear; abstract art is its long-standing opposite in modern art history.","definitionCN":"如实呈现事物外观的风格；在现代艺术史中是抽象艺术的长期对立面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Abstract means drawn away, so the subject has been pulled out of the picture.","cn":"abstract 意为「被抽走」，所以题材被从画面里抽走了。"},{"en":"The Latin verb is trahere 'to draw or pull', the same one behind attract, with the opposite prefix.","cn":"拉丁动词是 trahere「拉、牵引」，与 attract 同一个动词，只是前缀相反。"},{"en":"Fixed phrases mark its branches: geometric, early, sculptural, design.","cn":"固定搭配标出它的分支：几何的、早期的、雕塑的、设计的。"},{"en":"Abstraction is the process; abstract art is the category.","cn":"abstraction 是过程；abstract art 是类别。"},{"en":"Non-objective art is the stricter name used by artists who rejected the word abstract.","cn":"非对象性艺术是那些拒绝「抽象」一词的艺术家使用的更严格名称。"}],"abstract":[{"en":"Picture a painting where a red square is simply red, not a roof or a flag.","cn":"想象一幅画，红色方块就只是红色，不是屋顶也不是旗子。"},{"en":"Picture a sculpture whose meaning is the space it pushes aside.","cn":"想象一件雕塑，它的意义就是它推开的那部分空间。"},{"en":"Picture a picture with nothing to recognize, so your eye must invent a path.","cn":"想象一幅没有东西可认的画，你的眼睛只好自己发明一条路径。"}]},"examples":[{"en":"Abstract art asks the viewer to look at colour before subject.","cn":"抽象艺术要求观者先看颜色，再看题材。"},{"en":"The museum hangs abstract art beside nineteenth-century landscapes.","cn":"博物馆把抽象艺术与十九世纪风景画挂在一起。"},{"en":"Her definition of abstract art excludes any hint of a figure.","cn":"她对抽象艺术的定义排除任何人物形象的暗示。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「抽走形象 + 艺术」—— 把桌子椅子都抽走，只剩颜色与线条 → 抽象艺术","word":"abstract art"},"root":"由 abstract 与 art 组合：abstract 来自拉丁分词 abstractus，源自 abstrahere（abs-「离开」+ trahere「拉」）；art 经古法语上溯至拉丁 ars「技艺」。trahere 与 ars 的更早来源均不确定。","sensesIntro":{"en":"Eight senses follow one subtraction: the object is drawn away and colour, line, mass and pattern remain. The phrase covers painting, sculpture, design, a spiritual programme and, finally, a disputed boundary.","cn":"八个义项围绕同一次减法展开：物体被抽走，剩下颜色、线条、体量与图案。这个短语涵盖绘画、雕塑、设计、一套精神纲领，最后是一条有争议的边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a canvas with no table and no face, only red, a curve and blue pressing against each other.","cn":"核心意象：一块没有桌子也没有脸的画布，只有红、一条弧线与蓝相互推挤。"},"chain":["SUBJECT REMOVED","COLOUR AND LINE","NON-OBJECTIVE","GEOMETRY OR GESTURE","OPEN CATEGORY","GLOBAL PRACTICE"],"branches":[{"senses":"01 · 02","en":"THE SUBTRACTION: the visible subject is removed and the picture refers to nothing outside itself.","cn":"减法：可见题材被移除，画面不再指向自身之外的任何事物。"},{"senses":"03 · 06","en":"ORDER AND SURFACE: geometry and design turn abstraction into a shared visual language.","cn":"秩序与表面：几何与设计把抽象变成共享的视觉语言。"},{"senses":"04 · 05","en":"GESTURE AND MASS: splashed paint and steel sculpture show two bodily ways of being abstract.","cn":"笔势与体量：泼洒的颜料与钢制雕塑展示抽象的两种身体方式。"},{"senses":"07","en":"INNER NECESSITY: early abstraction claims spiritual meaning rather than decoration.","cn":"内在必然：早期抽象主张精神意义，而非装饰。"},{"senses":"08","en":"THE ARGUMENT: what counts as abstract remains a contested label.","cn":"争论：什么算抽象仍是一个有争议的标签。"}]},"affixes":{"intro":{"en":"Abstract art is built on a Latin verb for pulling, with a prefix that means away. The same verb, with the opposite prefix, gives attract.","cn":"abstract art 建立在一个表示「拉」的拉丁动词上，其前缀意为「离开」。同一个动词若用相反前缀，就给出 attract。"},"latinIntro":{"en":"Latin trahere gives traction, tractor and attract; its compound abstrahere gives abstract, abstraction and abstract art.","cn":"拉丁 trahere 给出 traction、tractor 与 attract；其复合词 abstrahere 给出 abstract、abstraction 与 abstract art。"},"items":[{"word":"trahere","structure":"trahere, traxi, tractum (Latin verb, third conjugation)","meaning":"to draw, pull","meaningCN":"拉；牵引","example":"Trahere is the base of the whole family.","exampleCN":"trahere 是整个词族的基础。"},{"word":"abs-","structure":"abs- (Latin prefix, 'away from')","meaning":"away, off","meaningCN":"离开；脱离","example":"The prefix marks removal.","exampleCN":"这个前缀标记「拿走」。"},{"word":"abstrahere","structure":"abs- + trahere","meaning":"to draw away, detach","meaningCN":"抽走；分离","example":"Abstrahere gives the English abstract.","exampleCN":"abstrahere 给出英语 abstract。"},{"word":"abstract","structure":"Latin abstractus, participle of abstrahere","meaning":"drawn away; not concrete","meaningCN":"被抽走的；非具体的","example":"The idea is abstract.","exampleCN":"这个观念是抽象的。"},{"word":"abstraction","structure":"abstract + -ion (result)","meaning":"the act or result of drawing away","meaningCN":"抽取的动作或结果","example":"Abstraction is a mental move.","exampleCN":"抽象化是一种心智动作。"},{"word":"abstract art","structure":"abstract + art","meaning":"art without a visible subject","meaningCN":"没有可见题材的艺术","example":"Abstract art fills the west wing.","exampleCN":"抽象艺术占满西翼。"},{"word":"abstract artist","structure":"abstract + artist","meaning":"a maker of abstract work","meaningCN":"抽象艺术家","example":"The abstract artist works in layers.","exampleCN":"这位抽象艺术家分层作画。"},{"word":"abstract expressionism","structure":"abstract + expressionism","meaning":"the gesture-based later movement","meaningCN":"以笔势为主的后期运动","example":"Abstract expressionism enlarged the canvas.","exampleCN":"抽象表现主义把画布放大。"},{"word":"attract","structure":"ad- 'to' + trahere","meaning":"to pull toward","meaningCN":"吸引","example":"Attract reverses the direction of abstract.","exampleCN":"attract 把 abstract 的方向反转。"},{"word":"tractor","structure":"trahere + -or (thing that pulls)","meaning":"a machine that pulls","meaningCN":"牵引机；拖拉机","example":"The tractor keeps the Latin pulling image.","exampleCN":"tractor 保留了拉丁语「拉」的意象。"}],"latinEntries":[{"word":"trahere","structure":"trahere, traxi, tractum (verb, third conjugation)","meaning":"to draw, pull","meaningCN":"拉；牵引"},{"word":"abstrahere","structure":"abstrahere, abstraxi, abstractum (verb, third conjugation)","meaning":"to draw away","meaningCN":"抽走；分离"},{"word":"abstractus","structure":"abstractus, abstracta, abstractum (participle)","meaning":"drawn away","meaningCN":"被抽走的"},{"word":"ars","structure":"ars, artis (f., third declension)","meaning":"skill, craft","meaningCN":"技艺；手艺"}]}},{"word":"symbolism","ipa_uk":"/ˈsɪmbəlɪzəm/","ipa_us":"/ˈsɪmbəlɪzəm/","definition_zh":"象征主义；象征手法；象征体系","definition_en":"the use of symbols to suggest ideas and feelings, or a system of such symbols","core_image":"一只白鸽、一盏灯、一株枯树，各自不只是自己，而指向看不见的意思","scene":"诗人拒绝直说，用月亮、镜子和秋天暗示难以言明的情绪。The poet refused direct statement and used moons, mirrors and autumn, trusting symbolism to carry the feeling.","sceneCN":"这里指「用意象暗示言外之意的象征手法」（第 1 个义项：以象征表达观念）；句意为诗人拒绝直说，借月亮、镜子与秋天让象征手法承载情绪。可辨识物件：月亮、镜子、秋天的树、诗稿。","pos":[{"tag":"n.","zh":"象征主义（文学与艺术运动）"},{"tag":"n.","zh":"象征手法；象征体系"}],"collocations":[{"phrase":"religious symbolism","zh":"宗教象征体系"},{"phrase":"the symbolism of colours","zh":"颜色的象征意义"},{"phrase":"Symbolism in literature","zh":"文学中的象征主义"},{"phrase":"national symbolism","zh":"国族象征"},{"phrase":"dream symbolism","zh":"梦境象征"},{"phrase":"a movement of symbolism","zh":"一场象征主义运动"}],"forms":[{"label":"单数形式","form":"symbolism"},{"label":"复数形式（指多种象征体系）","form":"symbolisms"},{"label":"所有格","form":"symbolism's"},{"label":"相关名词（艺术家）","form":"symbolist"}],"derivatives":[{"word":"symbolist","pos":"n./adj.","zh":"象征主义者；象征派的（由基础词加表示「信奉者」的后缀构成，语义收窄为身份）"},{"word":"symbolic","pos":"adj.","zh":"象征的；象征性的（由基础词加表示「与……有关的」后缀构成，语义偏移为性质描述）"},{"word":"symbolically","pos":"adv.","zh":"象征性地（由前一个形容词加构成副词的后缀构成，语义偏移为方式）"},{"word":"symbology","pos":"n.","zh":"象征学；符号体系（由基础词加表示学科的后缀构成，语义偏移为研究领域）"}],"senses":[{"no":"01","title":"Use of symbols to convey ideas","titleCN":"用象征传达观念的手法","definition":"the practice of using one thing to stand for another idea or feeling","definitionCN":"用一个事物代表另一个观念或感受的做法","example":"The poet trusted symbolism to carry the feeling.","exampleCN":"诗人让象征手法承载情绪。","why":"The Greek word behind symbol meant a token split in two and matched later for recognition. One half stands for the whole, and that structure is the core of symbolism.","whyCN":"symbol 背后的希腊词指一分为二、日后拼合以确认身份的信物。一半代表整体，这一结构正是象征的核心。"},{"no":"02","title":"The Symbolist movement","titleCN":"象征主义运动","definition":"the late nineteenth-century literary and artistic movement that favoured suggestion over description","definitionCN":"十九世纪末偏爱暗示而非描写的文学与艺术运动","example":"Symbolism began as a revolt against realistic description.","exampleCN":"象征主义最初是对写实描写的反叛。","why":"The movement took the general practice and made it a programme: never name the feeling, let the image carry it.","whyCN":"这场运动把一般做法变成纲领：永远不要直接说出感受，让意象去承载。"},{"no":"03","title":"A system of symbols","titleCN":"成套的象征体系","definition":"an organised set of signs used by a religion, culture or institution","definitionCN":"宗教、文化或机构使用的一整套有组织的符号","example":"Religious symbolism fills the nave.","exampleCN":"宗教象征体系布满中殿。","why":"When many symbols are related and repeated, they form a grammar that members of a community can read.","whyCN":"当许多符号相互关联并反复出现，它们就构成一套社群成员能读懂的语法。"},{"no":"04","title":"The symbolic meaning of an object","titleCN":"某物的象征含义","definition":"the meaning an object carries beyond its literal use","definitionCN":"某物在字面用途之外承载的含义","example":"The ring's symbolism outlives its gold.","exampleCN":"这枚戒指的象征意义比它的黄金活得更久。","why":"Any object can acquire a second meaning by repeated association, and that second meaning is what the word names here.","whyCN":"任何物件都能通过反复关联获得第二层意义，这里命名的正是那层意义。"},{"no":"05","title":"Dream symbolism","titleCN":"梦境象征","definition":"the interpretation of dream images as standing for hidden wishes or fears","definitionCN":"把梦中意象解释为隐藏愿望或恐惧的替身","example":"Dream symbolism gave the water a second meaning.","exampleCN":"梦境象征让水有了第二层意义。","why":"Psychoanalysis treated dream images as a coded language, so the word entered medicine as a method of decoding.","whyCN":"精神分析把梦中意象当作编码语言，因此这个词作为解码方法进入医学。"},{"no":"06","title":"Colour and number symbolism","titleCN":"颜色与数字的象征","definition":"fixed meanings attached to particular colours or numbers within a culture","definitionCN":"某种文化中附着于特定颜色或数字的固定含义","example":"Colour symbolism makes white mean mourning in one place and joy in another.","exampleCN":"颜色象征使白色在一地表示哀悼，在另一地表示喜悦。","why":"Colour and number are abstract, so cultures assign them meanings by convention, and the meanings travel with the group.","whyCN":"颜色与数字本身抽象，文化便按约定给它们分配含义，而这些含义随群体流传。"},{"no":"07","title":"Political and national symbolism","titleCN":"政治与国族象征","definition":"flags, colours, monuments and rituals used to represent a state or cause","definitionCN":"用来代表国家或事业的旗帜、颜色、纪念碑与仪式","example":"National symbolism gathered around the old bridge.","exampleCN":"国族象征聚集在那座老桥周围。","why":"A political body needs visible signs that can be shared by strangers, so symbolism becomes a tool of unity and claim.","whyCN":"政治体需要陌生人也能共享的可见符号，因此象征成为团结与主张的工具。"},{"no":"08","title":"Symbolic notation in logic","titleCN":"逻辑与数学中的符号记法","definition":"the use of formal signs instead of words to make reasoning precise","definitionCN":"用形式化符号代替词语、使推理精确的做法","example":"Modern logic depends on symbolism more than on prose.","exampleCN":"现代逻辑依赖符号记法甚于散文。","why":"Here a symbol is not suggestive but exact. The same word covers both the poetic sign and the mathematical one, because both stand in place of something else.","whyCN":"这里的符号不求暗示，而求精确。同一个词兼指诗性符号与数学符号，因为两者都代替别的东西。"}],"etymology":{"intro":{"en":"Symbolism comes from a Greek word for a token matched to its other half. Latin borrowed it, and the suffix for doctrines made it a movement. Dates are approximate.","cn":"symbolism 来自一个希腊词，指可与另一半拼合以确认身份的信物。拉丁语借入该词，表示学说的后缀又把它变成一场运动。年代均为约数。"},"items":[{"era":"GREEK SYMBALLEIN","en":"Greek symballein meant 'to throw together', from syn- 'together' plus ballein 'to throw'. Its deeper origin is source uncertain.","cn":"希腊 symballein 意为「一起投掷」，由 syn-「一起」加 ballein「投掷」构成。其更深来源属「来源不确定」。"},{"era":"GREEK SYMBOLON","en":"A symbolon was a token broken in two, each half kept by one party and matched later as proof of identity. The sign and the thing it stood for were two halves of one object.","cn":"symbolon 是分成两半的信物，双方各持一半，日后拼合以证明身份。符号与它所代表之物，正是同一物件的两半。"},{"era":"LATIN SYMBOLUM","en":"Latin symbolum kept the senses of token, creed and sign, and from it English took symbol in the fifteenth century.","cn":"拉丁 symbolum 保留「信物、信条、符号」诸义，英语在十五世纪由它借入 symbol。"},{"era":"FRENCH SYMBOLISME (1886)","en":"The poet Jean Moréas published a manifesto of Symbolisme in 1886, and the label spread to painting and music.","cn":"诗人莫雷亚斯在一八八六年发表《象征主义》宣言，这个标签随后扩散到绘画与音乐。"},{"era":"ENGLISH SYMBOLISM","en":"English adopted symbolism for both the movement and the general practice of standing one thing for another.","cn":"英语用 symbolism 兼指这场运动与「以一物代表另一物」的一般做法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Greek origin of ballein is unresolved, and any older root proposed for it is a reconstructed form rather than a recorded word.","cn":"来源不确定：ballein 在希腊语之前的来源没有定论，为其提出的更早词根属于重构形式，而非有记录的真实词形。"}]},"similar":{"note":{"en":"Group one holds forms of the same word that are constantly confused; group two holds neighbouring ways of meaning something indirectly.","cn":"第一组是同一个词的不同形式，常被混淆；第二组是间接表意的相邻方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symbol","ipa":"/ˈsɪmbəl/","tag":"the sign itself","definition":"the thing that stands for something else; symbolism is the practice or system built from such things.","definitionCN":"代表另一事物的东西；symbolism 是由这些符号构成的做法或体系。"},{"word":"symbolic","ipa":"/sɪmˈbɒlɪk/","tag":"adjective","definition":"acting as a sign of something else; it describes a single sign, while symbolism names a practice.","definitionCN":"作为另一事物之标志的；它描述单个符号，而 symbolism 指做法。"},{"word":"symbolist","ipa":"/ˈsɪmbəlɪst/","tag":"person or adjective","definition":"an artist of the movement, or an adjective for its style; symbolism is the movement's name.","definitionCN":"这场运动中的艺术家，或形容其风格的形容词；symbolism 是运动名称。"},{"word":"symbology","ipa":"/sɪmˈbɒlədʒi/","tag":"study, not practice","definition":"the study or system of symbols; it names research or a catalogue, not the artistic method.","definitionCN":"对符号的研究或符号体系；它指研究或分类，而非艺术手法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"metaphor","ipa":"/ˈmetəfə/","tag":"verbal comparison","definition":"calling one thing another to transfer meaning; it is a figure of language, while symbolism can work without words.","definitionCN":"把一物称作另一物以转移意义；它是语言修辞，而象征可以在没有语言的情况下运作。"},{"word":"allegory","ipa":"/ˈælɪɡəri/","tag":"extended code","definition":"a story whose characters and events each stand for a second meaning; it is more systematic and explicit than symbolism.","definitionCN":"人物与事件各自代表第二层意义的故事；比象征更系统、更明确。"},{"word":"imagery","ipa":"/ˈɪmɪdʒəri/","tag":"sensory language","definition":"vivid sensory description in writing; imagery may or may not carry a symbolic second meaning.","definitionCN":"写作中鲜明的感官描写；意象可以带有、也可以不带象征的第二层意义。"},{"word":"emblem","ipa":"/ˈembləm/","tag":"fixed badge","definition":"a fixed sign with an official or public meaning; it shares the Greek throwing root but uses a different prefix.","definitionCN":"具有官方或公共含义的固定标志；它共享希腊语「投掷」词根，但前缀不同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek token was split in two, so a symbol is literally half of a pair.","cn":"希腊信物被分成两半，因此一个符号字面上就是一对中的一半。"},{"en":"The verb behind it means 'throw together', which is why a symbol joins two things into one sign.","cn":"其后的动词意为「一起投掷」，所以象征把两样东西合成一个符号。"},{"en":"Fixed phrases mark its fields: religious, colour, national, dream.","cn":"固定搭配标出它的领域：宗教的、颜色的、国族的、梦境的。"},{"en":"A symbolist is the artist; symbolic is the adjective; symbolism is the practice.","cn":"symbolist 指艺术家；symbolic 是形容词；symbolism 是做法。"},{"en":"Symbolism became a named movement in 1886 with a published manifesto.","cn":"象征主义在一八八六年随一份宣言成为有名号的运动。"}],"abstract":[{"en":"Picture a broken coin where each half proves the other.","cn":"想象一枚裂开的硬币，两半各自证明对方。"},{"en":"Picture a moon that is also a mother and also an ending.","cn":"想象一轮月亮，同时是母亲，也是结局。"},{"en":"Picture a flag that makes a stranger stand still without knowing why.","cn":"想象一面旗，让陌生人不知为何就站住。"}]},"examples":[{"en":"Symbolism in the play turns the closed door into a whole history.","cn":"剧中的象征手法把一扇关着的门变成一整段历史。"},{"en":"The church's symbolism is explained on a small card.","cn":"教堂的象征体系印在一张小卡片上说明。"},{"en":"The movement of symbolism influenced music and painting alike.","cn":"象征主义运动同时影响了音乐与绘画。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「符号 + 主义」—— 用看得见的东西代表看不见的意思 → 象征主义、象征手法","word":"symbolism"},"root":"经拉丁 symbolum 上溯至希腊 symbolon「一分为二的认亲信物」，源自 symballein（syn-「一起」+ ballein「投掷」）；再加表示学说的后缀构成主义之名。ballein 更早来源不确定。","sensesIntro":{"en":"Eight senses follow one sign standing for another: poetic suggestion, a named movement, a religious grammar, a single object's second meaning, dreams, colour, the nation, and finally the exact notation of logic.","cn":"八个义项围绕「一物代表另一物」展开：诗性暗示、有名号的运动、宗教语法、单件物体的第二层意义、梦境、颜色、国族，最后是精确的逻辑记法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dove on a windowsill that is also, for the viewer, peace.","cn":"核心意象：窗台上的一只白鸽，在观者眼中同时是和平。"},"chain":["SIGN","SECOND MEANING","SYSTEM OF SIGNS","MOVEMENT","EXACT NOTATION","EVERYDAY SIGN"],"branches":[{"senses":"01 · 04","en":"THE BASIC MOVE: one thing is made to stand for another, and an object gains a second meaning.","cn":"基本动作：一物被用来代表另一物，物体因此获得第二层意义。"},{"senses":"02","en":"THE MOVEMENT: suggestion becomes a programme and a named school.","cn":"运动：暗示变成纲领，也成为有名号的流派。"},{"senses":"03 · 06","en":"THE GRAMMAR: religion and colour assign fixed signs that a community can read.","cn":"语法：宗教与颜色分配固定符号，供社群共同读取。"},{"senses":"05 · 07","en":"THE INNER AND THE PUBLIC: dreams decode private images, while nations display public ones.","cn":"内在与公共：梦境解读私人意象，国族展示公共意象。"},{"senses":"08","en":"THE EXACT EDGE: logic uses signs that are precise rather than suggestive.","cn":"精确的边缘：逻辑使用精确而非暗示性的符号。"}]},"affixes":{"intro":{"en":"Symbolism belongs to a Greek family built on throwing things together, which is why a symbol joins two halves into one sign.","cn":"symbolism 属于一个以「把东西投到一起」为核心的希腊词族，因此一个符号把两半合成一个记号。"},"latinIntro":{"en":"Greek symbolon passed into Latin as symbolum, and English took symbol, symbolic and symbolism from that stem; emblem shares the throwing root with a different prefix.","cn":"希腊 symbolon 进入拉丁语作 symbolum，英语从这一词干取得 symbol、symbolic 与 symbolism；emblem 共享「投掷」词根，但前缀不同。"},"items":[{"word":"syn-","structure":"syn- (Greek prefix, 'together')","meaning":"together, with","meaningCN":"一起；共同","example":"The prefix joins two halves.","exampleCN":"这个前缀把两半合在一起。"},{"word":"ballein","structure":"ballein (Greek verb, 'to throw')","meaning":"to throw","meaningCN":"投掷","example":"Ballein is the root of symbol and emblem.","exampleCN":"ballein 是 symbol 与 emblem 的词根。"},{"word":"symbolon","structure":"syn- + ballein","meaning":"a token thrown together; a matched half","meaningCN":"拼合的信物；配对的一半","example":"The symbolon proved identity.","exampleCN":"symbolon 用来证明身份。"},{"word":"symbolum","structure":"symbolum (Latin noun, second declension)","meaning":"token, creed, sign","meaningCN":"信物；信条；符号","example":"Latin symbolum gave English symbol.","exampleCN":"拉丁 symbolum 给出英语 symbol。"},{"word":"symbol","structure":"symbolum through French","meaning":"a sign standing for something else","meaningCN":"代表另一事物的记号","example":"The ring is a symbol of promise.","exampleCN":"戒指是承诺的象征。"},{"word":"symbolic","structure":"symbol + -ic (relating to)","meaning":"acting as a sign","meaningCN":"起符号作用的","example":"The gesture was symbolic.","exampleCN":"这个姿态具有象征意义。"},{"word":"symbolism","structure":"symbol + -ism","meaning":"the practice or system of signs","meaningCN":"象征手法或象征体系","example":"Symbolism fills the poem.","exampleCN":"象征手法充满这首诗。"},{"word":"symbolist","structure":"symbol + -ist (person)","meaning":"an artist of the movement","meaningCN":"象征主义艺术家","example":"The symbolist avoided direct naming.","exampleCN":"这位象征主义者避免直接点名。"},{"word":"symbology","structure":"symbol + -ology (study of)","meaning":"the study of symbols","meaningCN":"符号学；象征体系研究","example":"Symbology catalogues the signs.","exampleCN":"象征学给这些符号编目。"},{"word":"emblem","structure":"en- 'in' + ballein","meaning":"a fixed sign with public meaning","meaningCN":"具有公共含义的固定标志","example":"The eagle is an emblem of the state.","exampleCN":"鹰是国家的标志。"}],"latinEntries":[{"word":"symbolum","structure":"symbolum, symboli (n., second declension)","meaning":"token, sign, creed","meaningCN":"信物；符号；信条"},{"word":"symbolus","structure":"symbolus, symboli (m., second declension)","meaning":"a mark, a sign","meaningCN":"标记；符号"}]}}]);
